// Файл згенеровано scripts/build_kz_akafisty.py. Абзац з префіксом § — рубрика, з префіксом # — підзаголовок.
import type { MvBook } from '../molytvoslov';
const D: MvBook[] = [{"u":"Акафіст святому благовірному князю В’ячеславу Чеському","e":"Akathist to the Holy Right-Believing Prince Wenceslas of Bohemia","secs":[{"h":"Кондак 1","ps":["Богоізбра́нний кня́же і кро́ткий во́їне Христо́в, в ро́ді христия́нськаго кня́зя Богемії Боривоя і блаже́нній княги́ні Людмили рожде́нний, родителями князе́м Вратиславом і княгиней Драгомирой с і́менем В'ячеслава крещенний, велича́юще просла́вльшаго тя Го́спода, воспіва́єм ті похва́льная. Ти же із младе́нчества христия́нському благоче́стію науче́нний от вся́ких нас бід свободи́:","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць посла́ тя, свя́тче Бо́жий, Це́ркве Правосла́вній в укріпле́ніє, жа́ждущим ві́дінія і́стини во благо́є вразумле́ніє, благочести́вим житіє́м твої́м в назидательноі окормле́ніє. Ми же, див'я́щеся таково́му о тебі́ Промишле́нію Вседержи́теля, с ра́достію вопіє́м ті:","Ра́дуйся, страни́ Чешскиє украше́ніє;","Ра́дуйся, смире́нієм і кро́тостію показа́вий стезю́ духо́внаго восхожде́нія.","Ра́дуйся, кня́же, блаже́нній Людмили люби́моє окормле́ніє;","Ра́дуйся, христия́нським і́стинам ві́рноє науче́ніє.","Ра́дуйся, Ду́ха Свята́го в се́рдці вмісти́вий;","Ра́дуйся, огне́м боже́ственной любві́ ду́шу свою́ распаливий.","Ра́дуйся, ра́зума Єва́нгельськаго іспо́лненний;","Ра́дуйся, зе́млю Чешськую житіє́м благи́м твої́м во ві́рі утверди́вий.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 2","ps":["Ви́дяще Госпо́дь чистоту́ помишле́ній се́рдця твоєго́, святи́й о́тче наш В'ячеславе, ізбра́ тя в ору́жіє Своє́ на землі́ Чешськия в христия́нськоє просвіще́ніє, да утверждаємиє твої́ми моли́твами і наставленіями с надеждой вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Под сі́нію блаже́нной Людмили богові́дініє твоє́ Госпо́дь укріпля́л єси́, свя́тче Бо́жий, і в утвержде́ніє твоє́ на прародительськом престо́ле кня́же Вратислав на ступени алтаря пред лице́ святи́тельськоє возве́л єси́ тя, глаго́ля: Преподай, влади́ко, благослове́ніє си́ну, наслі́днику моєму́. Ми же, ви́дяще Бо́жиє благоволе́ніє к тебі́, с ра́достію вопіє́м ті си́це:","Ра́дуйся, подо́бно пра́ведним праотцям Авраа́му, Ісаа́ку і Іа́кову благослове́нний;","Ра́дуйся, во вінча́нії равноапо́стольним царе́м Константи́ну і Єле́ні уподобленний.","Ра́дуйся, от ю́ности ревни́телю благоче́стія богоізбра́нний;","Ра́дуйся, утвержде́нія Правосла́вной ві́ри істо́чниче отрадний.","Ра́дуйся, язи́чества ди́вний просвіти́телю;","Ра́дуйся, аскетичеського житія́ ревни́телю.","Ра́дуйся, о словесном ста́ді Христо́вом землі́ Чешськия попече́ніє;","Ра́дуйся, о спасе́нії наро́да твоєго́ непреста́нноє помишле́ніє.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго служе́ніє княжеськоє твоє́ воі́стину определила єси́, ві́ру в Го́спода на́шего Ісу́са Христа́ наро́ду я́вно яви́л єси́, днем і ночію хра́ми Бо́жії для моле́ній посіща́яй, растерявших благода́ть святу́ю к покая́нію призива́яй. Ми же, ви́дяще попече́нія Бо́жия сія́, со умиле́нієм вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Благоволи́л єси́ Госпо́дь яви́ти Своєго́ світи́льника ми́ру, тебі́, святи́й о́тче В'ячеславе, і́стини ві́дініє, ізоби́ліє любве́ і кро́тости дарова́л єси́, в умноженії христия́нських доброді́телей утверди́л єси́; все би́ли ра́вни пред лице́м твої́м. Сего́ ра́ди поє́м Бо́гу о тебі́:","Ра́дуйся, упра́вителю землі́ Чешськия ві́рний;","Ра́дуйся, носи́телю ду́ха кро́тости добропобі́дний.","Ра́дуйся, бога́тим і убозим ра́бе ві́рний;","Ра́дуйся, сві́том небе́сним напо́лненний.","Ра́дуйся, сиро́т і вдов упова́ніє;","Ра́дуйся, душ христия́нських врачева́ніє.","Ра́дуйся, ми́рнаго ду́ха храни́телю;","Ра́дуйся, язи́чества кро́ткий обличи́телю.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 4","ps":["Бу́ри безу́мія і злорі́чія могущественних вельмо́ж не убоя́лся єси́, ко́зні язи́чников превозмогаяй і зе́млю Чешськую в Правосла́вії соблюда́яй. Ми же, побі́ду духо́вну зря, с ра́достію вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Ви́дящи язи́чества окруже́ніє, свя́тче Бо́жий, прилі́жно кни́ги церковниє ізучал єси́, ду́хом ві́дінія і́стини ісполня́яся, му́дрості і тве́рдости княжеськой набираяся. Сего́ ра́ди вопіє́м ті:","Ра́дуйся, чи́стий істо́чниче вдохнове́нія;","Ра́дуйся, гони́мих за пра́вду неізмі́нноє окормле́ніє.","Ра́дуйся, уби́йць любимой наста́вници блаженнной Людмили обличе́ніє;","Ра́дуйся, роди́тельници твоєя́ Драгомири, коснеющей в язичестві, удале́ніє.","Ра́дуйся, в утвержде́нії за́повіді Бо́жієй с матерю примире́ніє;","Ра́дуйся, гріха́ краткаго отчужденія сле́знаго омове́ніє.","Ра́дуйся, во во́зраст духо́вній зрелости неізмі́нноє восхожде́ніє;","Ра́дуйся, самобитноє о́бласти твоєя́ устроє́ніє.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ всім христия́ном страни́ твоєя́ яви́лся єси́, святи́й му́чениче В'ячеславе, благочести́вим житіє́м на покая́ніє, на путь несенія креста́ смире́нно наставля́яй. Ми же, ві́рою узрі́вши спасительность смире́нія і кро́тости на путі́ Христа́, с ра́достію вопіє́м ті: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівши вельмо́жи страни́ Чешськия вели́каго тя благоче́стія защи́тника, святи́й о́тче, бра́та твоєго́ Болеслава ложію во іскуше́ніє ввели, благоче́стіє твоє́ іскажали. Ми же всі, твоєму́ боголю́бію див'я́щеся, вопіє́м ті:","Ра́дуйся, подви́жниче богопросла́вленний і ди́вний;","Ра́дуйся, враго́м ро́да человечеського, дия́волом, поносимий.","Ра́дуйся, к чистоті́ духо́вній, к ві́рі в І́стину призива́вий;","Ра́дуйся, о любві́ Христо́вой житіє́м твої́м віща́вий.","Ра́дуйся, чети́ріх твої́х сесте́р в жени́ за князе́й окре́стних стран с ра́достію отда́вий;","Ра́дуйся, благода́тію Свята́го Ду́ха страну́ твою́ омивавий.","Ра́дуйся, бра́та Болеслава по-християнськи возлюби́вий;","Ра́дуйся, нивочто наговори єго́ на тя вміни́вий.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 6","ps":["Пропові́дуєть Свята́я Це́рков по́двизі і труди́ твоя́, богоно́сне уго́дниче Христо́в, о сла́ві Бо́жієй і о спасе́нії всім возвіща́л єси́, о благода́тном пламененії душі́ житіє́м твої́м благовіству́яй, науча́й тім лю́ди твоя́ благода́рственно пі́ти Го́споду: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ сві́том і́стини в страні́ многострадальной, святи́й кня́же В'ячеславе, любо́вію твоє́ю о́браз Христа́ явля́єши, гробо́м го́рдості, тщесла́вія і себ'ялюбія себі́ пред всі́ми утвержда́юще. Сего́ ра́ди воспіва́єм ті такова́я:","Ра́дуйся, княжеськоє страни́ твоєя́ окормле́ніє;","Ра́дуйся, всім жа́ждущим спасе́нія і до ни́ні благо́є утіше́ніє.","Ра́дуйся, украше́нієм хра́мов і очище́нієм душ ві́рних ко спасе́нію препровождаєши;","Ра́дуйся, княжеством твої́м і ві́рою правосла́вних христия́н умудря́єши.","Ра́дуйся, ста́до Христо́во святи́ми моли́твами вразумля́єши;","Ра́дуйся, волко́во в овечих шкурах дони́ні облича́єши.","Ра́дуйся, страни́ Чешскиє украше́ніє;","Ра́дуйся, свято́й Людмили Чешськия досто́йноє послі́дованіє.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 7","ps":["Хотя́й ві́ру Правосла́вную на землі́ Чешськия в чистоті́ утверди́ти, свя́тче Бо́жий, проти́в язи́чеськаго кня́зя Куримськаго с войськом виступил єси́, в жела́нії овладеть страной Богемієй єго́ облича́яй і открито на поєдинок напавшаго кня́зя визиваяй. Ми же, ви́дяще отважность ві́ри твоєя́, благода́рно со слеза́ми вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Ві́дуще тя ізбра́нника Бо́жия, святи́й о́тче наш В'ячеславе, безмо́лвно стоя́ло пре́данноє тебі́ во́йсько, суда́ Госпо́дня ожида́яй, і вот внеза́пу князь язи́чник пред лице́м твої́м сві́тлий крест узрі́л єси́; пав ниць, твоє́ благоду́шноє проще́ніє обріта́яй. Ми же, всі труди́ твої́ помина́юще непреста́нно воспіва́єм ті сицева́я:","Ра́дуйся, благоче́стія христия́нськаго попечи́телю;","Ра́дуйся, безкро́вной би́тви побіди́телю.","Ра́дуйся, врачу́ наш ско́рий і благода́тний;","Ра́дуйся, ві́рних Го́споду Ісу́су Христу́ защи́тниче сла́вний.","Ра́дуйся, градо́в чешських щит і огражде́ніє;","Ра́дуйся, во ві́рі Правосла́вной утвержде́ніє.","Ра́дуйся, в ну́ждах упова́нію на Бо́га науча́єши;","Ра́дуйся, бога́тство лиш на не́бі собира́ти призива́єши.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 8","ps":["Бо́жию ми́лость ви́дим на тебі́, святи́й му́чениче В'ячеславе, благоче́стія діла́ творя́ на сові́т імперський опоздал єси́, обвине́нія собра́вшихся князе́й смире́нно принимаяй. А́нгелов о́крест тя і крест сія́ющий на челі́ твоє́м Бог ке́сарю откри́л єси́ внеза́пно і пред тобо́ю єго́ ниць пове́рг єси́ для всіх нежданно. Ми же, зря сокро́вища сія́, со умиле́нієм вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь всім засту́пниче яви́лся єси́, блаже́нне о́тче В'ячеславе, часть моще́й свята́го Вита у ке́саря, повергшагося пред тобо́ю, іспроси́л єси́ і в гра́ді Праге це́рков в честь свята́го освяти́л єси́, на похвалу́ всіх подвиза́я пі́ти Бо́гу:","Ра́дуйся, престо́лу і главі́ духо́вній в страні́ Чешстей поревнова́вий;","Ра́дуйся, ка́федру архієпископськую Бо́жиїм смотре́нієм основа́вий.","Ра́дуйся, по́двигами і моли́твою наро́ду чешському хода́таю спасе́нія;","Ра́дуйся, приводя́й всіх жа́ждущих к істо́чнику очище́нія.","Ра́дуйся, согревающую благода́ть слуге твоєму́ Подивою открива́яй;","Ра́дуйся, слі́довати за Христо́м «слід в слід» в зи́мнім по́ле науча́яй.","Ра́дуйся, нощни́м печенієм святи́х просфор Бо́га славивий;","Ра́дуйся, діте́й язи́чников і́стинному Бо́гу служи́ти посвящавий.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 9","ps":["Вся́коє єстество́ А́нгельськоє удиви́ся Про́мислу милосе́рдія Твоєго́, Бо́же наш, я́ко дарова́л єси́ нам толи́ко му́драго і те́плаго моли́твенника і о спасе́нії душ на́ших пред Престо́лом Твої́м, Го́споди, попечи́теля. Кто сочте́ть, свя́тче Бо́жий, все труди́ твоя́, я́же сотвори́л єси́, Го́сподеві поя́: Аллилу́я."]},{"h":"Ікос 9","ps":["Всего́ себе́ Го́споду пре́дал єси́, мир Христо́в посреді́ люде́й утвержда́яй і ко́зні сатани́нськая любо́вію Христо́вой побіжда́яй. Ми же, благочести́воє житіє́ твоє́ зря, с любо́вію вопіє́м ті:","Ра́дуйся, дар прозорливости стяжа́вий;","Ра́дуйся, о перенесенії ті́ла святі́й Людмили в девичію оби́тель свята́го Гео́ргия открове́ніє Сви́ше восприя́вий.","Ра́дуйся, монашество приняти возжела́вий;","Ра́дуйся, бу́дущеє твоє́ ду́хом Святи́м позна́вий.","Ра́дуйся, А́нгельськоє і на́ше непреста́нноє удивле́ніє;","Ра́дуйся, носи́телю Бо́жия прославле́нія.","Ра́дуйся, добровольной ску́дости не ізміни́вий;","Ра́дуйся, Ду́ха самоотверже́нія і любве́ приіми́й.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́й всім челові́ком, і́же на кро́ві му́чеников Свої́х Це́рков основа́вий, сердцеві́дець Христо́с положи́ тя, о́тче наш В'ячеславе, в со́нмі святи́х му́чеников во основа́ніє хра́мини страни́ Чешськия, да всі в ней су́щия вопію́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Наста́вниче бил єси́ всім с ві́рою к тебі́ прибегающим, свя́тче Бо́жий, страні́ Чешськия щит і огражде́ніє, і о чистоті́ Правосла́вния ві́ри сла́вноє попече́ніє. Ми же обетованноє святи́ми духо́вноє возста́ніє богохранимих стран слав'янських в моли́твах призива́єм і в покая́нії вопіє́м си́це:","Ра́дуйся, крест страда́ній на ра́мена во утвержде́ніє Правосла́вія прия́вий;","Ра́дуйся, серде́чную м'я́гкость стяжа́вий.","Ра́дуйся, отмстителем себі́ Го́спода ізбра́вий;","Ра́дуйся, о́бразе митаре́ва смире́нія.","Ра́дуйся, кро́ткий лик небе́снаго прозрі́нія;","Ра́дуйся, стра́нники і нищія пита́вий.","Ра́дуйся, бла́гость Христо́вой любві́ позна́вий;","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 11","ps":["Пі́ніє благоуха́нноє непреста́нно Святі́й Тро́йці і Ді́ві Богоро́диці вознося́ще, всі́ми по́мислами, житіє́м твої́м, о́бразом благоче́стія в страні́ твоєя́ преби́л єси́; подо́бно бра́тієм князіям Бори́су і Глі́бу на Свято́й Русі́, преда́тельство от бра́та Болеслава прия́л єси́. Ми же, возлюби́вше Бо́га за такову́ю ми́лость, ви́ну зове́м Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Богоізбра́нний во́їне Христо́в, святи́й му́чениче кня́же В'ячеславе, я́ко світоза́рноє світи́ло возсія́л єси́, кро́тость і смире́ніє істоча́яй, смисл житія́ і сме́рті христия́нстій утвержда́яй, любо́вію на стезю́ спасе́нія, стезю́ несенія креста́ во спасе́ніє душі́ призива́яй. Тім же поє́м ті:","Ра́дуйся, понине святи́є хра́ми Бо́жії устроя́єши;","Ра́дуйся, с любо́вію свяще́нство в них собира́єши.","Ра́дуйся, послі́дній храм твой свято́му пра́отцю Авраа́му посвятивий;","Ра́дуйся, бра́та твоєго́ с благогові́нієм на освяще́ніє пригласивий.","Ра́дуйся, созидателю душ христия́нських сла́вний;","Ра́дуйся, наро́да Бо́жия любо́в стяжа́вий.","Ра́дуйся, во́їне Христо́в, явле́нний в подража́ніє;","Ра́дуйся, оте́ць чадолюби́вий, Бо́гом просла́вленний нам в утіше́ніє.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 12","ps":["К тебі́ любо́в Пречи́стой Богоро́диці ві́дущи, свя́тче Бо́жий, на пра́здник святи́х Безсре́бреников ко бра́ту Болеславу преби́л єси́, я́ко овча́, ведо́моє на заколе́ніє, смерть прозрі́л єси́ і кров свою́ за Христа́ Бо́га проли́ти возжела́л єси́, слова́ми сіє́ предваря́яй: Завтра на у́треннім бді́нії ра́йськаго предстоя́теля свята́го Михаї́ла бу́ду пи́ти ча́шу, Влади́ка, і́бо уже́ Арха́нгеле ду́шу мою́ Влади́ці обіща́л єси́; ви же, ра́достно со мно́ю ни́ні піющиє вино́, ві́дайте, что от сего́ часа́ уже́ не бу́ду пи́ти о́ноє с ва́ми. Сего́ ра́ди вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Це́рков Бо́жия земна́я сла́ву небе́сную утвержда́яй, пою́ще страда́нія твоя́, подо́бно христопродавцю Іу́ді, брат твой Болеслав на пир нечести́ваго скопища преда́телей увлек єси́ тя, великодушний святи́й му́чениче В'ячеславе, у́тром во врата́х до́ма княжеськаго смерть от меча́ бра́та і клевретов єго́ с кро́тостію прия́л єси́ і на порогі церко́вном ду́шу Го́споду пре́дал єси́. Ми же все сія́ зря, со слеза́ми вопіє́м ті:","Ра́дуйся, святи́й кня́же, по́сланний нам во укріпле́ніє;","Ра́дуйся, о́бразе Христо́в, призва́нний в покаянноі очище́ніє.","Ра́дуйся, лю́б'ящим тя хода́таю спасе́нія;","Ра́дуйся, величающим тя і подражающим щит і огражде́ніє.","Ра́дуйся, немощни́м во благо́є утіше́ніє;","Ра́дуйся, всім ві́рним побідоно́сноє благослове́ніє.","Ра́дуйся, всіх при́сних в Небе́сния оби́телі с собо́ю призва́вий;","Ра́дуйся, сле́зи по́здняго раска́янія ма́тері твоєя́ Драгомири позна́вий.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 13","ps":["О преди́вний уго́дниче Христо́в, прийми́ ма́лоє сіє́ моле́ніє на́ше в похвалу́ тебі́ от правосла́вной бра́тії возноси́моє, при́зри на нас немощни́х, ко гріху́ прекло́нних, малопросвещенних, заботами обремене́нних і, предстоя́ в небе́сній сла́ві пред Престо́лом Царя́ ца́рствующих, моли́ся о нас, вели́кий кня́же: проси́, свя́тче Бо́жий, да обря́щем милосе́рдіє Єго́ в день су́дний, в ра́дості пою́ще Пресвяті́й Тро́йце: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Творе́ць посла́ тя, свя́тче Бо́жий, Це́ркве Правосла́вній в укріпле́ніє, жа́ждущим ві́дінія і́стини во благо́є вразумле́ніє, благочести́вим житіє́м твої́м в назидательноі окормле́ніє. Ми же, див'я́щеся таково́му о тебі́ Промишле́нію Вседержи́теля, с ра́достію вопіє́м ті:","Ра́дуйся, страни́ Чешскиє украше́ніє;","Ра́дуйся, смире́нієм і кро́тостію показа́вий стезю́ духо́внаго восхожде́нія.","Ра́дуйся, кня́же, блаже́нній Людмили люби́моє окормле́ніє;","Ра́дуйся, христия́нським і́стинам ві́рноє науче́ніє.","Ра́дуйся, Ду́ха Свята́го в се́рдці вмісти́вий;","Ра́дуйся, огне́м боже́ственной любві́ ду́шу свою́ распаливий.","Ра́дуйся, ра́зума Єва́нгельськаго іспо́лненний;","Ра́дуйся, зе́млю Чешськую житіє́м благи́м твої́м во ві́рі утверди́вий.","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Кондак 1","ps":["Богоізбра́нний кня́же і кро́ткий во́їне Христо́в, в ро́ді христия́нськаго кня́зя Богемії Боривоя і блаже́нній княги́ні Людмили рожде́нний, родителями князе́м Вратиславом і княгиней Драгомирой с і́менем В'ячеслава крещенний, велича́юще просла́вльшаго тя Го́спода, воспіва́єм ті похва́льная. Ти же із младе́нчества христия́нському благоче́стію науче́нний от вся́ких нас бід свободи́:","Ра́дуйся, святи́й му́чениче В'ячеславе, страни́ Чешскиє кня́же преди́вний."]},{"h":"Молитва","ps":["О, святи́й благові́рний кня́же му́чениче В'ячесла́ве, ізбра́нний воєво́до землі́ Че́шськия і всіх христия́н слове́нських те́плий пред Бо́гом предста́телю! Днесь, в па́м'ять твою́ єдиноду́шно соше́дшеся в честні́м хра́мі сем і пред іко́ною твоє́ю умиле́нно моля́щеся, си́це із глубини́ се́рдця на́шего к тебі́ взива́єм: Ти в житії́ твоє́м ревни́тель і защи́тник правосла́вния ві́ри бил єси́, і нас в ней те́плими твої́ми к Бо́гу моли́твами непоколеби́ми утверди́. Ти вели́коє возложе́нноє на тя служе́ніє усе́рдно проходи́л єси́, і нас твоє́ю по́мощію пребива́ти коєго́ждо, в не́мже призва́н єсть, наста́ви. Ти супоста́тов полки́ от оте́чества твоєго́ си́лою ра́тною і му́дростію управи́тельною отгна́л єси́, і на нас ополча́ющихся всіх враго́во ви́димих і неви́димих низложи́. Ти в преде́лах страни́ своєя́ пра́вду і мир і милосе́рдіє насажда́ти потща́лся єси́, і нам от ми́лостиваго Бо́га в сих доброді́теліх преуспі́яніє іспроси́. Ти безви́нную кров твою́ а́ки А́вель от руки́ бра́та своєго́ пред врати́ церко́вними пролія́л єси́, і нас, я́ко чад єди́ния ма́тере Це́ркве, братолю́бію і кро́тости научи́. О, вели́кий і сла́вний кня́же В'ячесла́ве, ра́ди вя́щшія сла́ви Небе́сния віне́ць земна́го княже́нія оста́вивий і вінце́м му́ченичеським пра́ведно увінча́нний! Ни́ні с му́дрою наста́вницею, прама́терію твоє́ю Людми́лою, і всі́ми святи́ми у Престо́ла Бо́жия предстоя́, не забу́ди нас си́рих і убо́гих, я́коже в животі́ твоє́м нікого́же от такови́х оста́вил єси́. І предста́тельством твої́м житіє́ ти́хоє і безгрі́шноє і к ві́чному Ца́рствію ше́ствіє устро́й нам, да просла́вим Бо́га, ди́внаго во святи́х Свої́х, Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Днесь А́нгели с челові́ки ра́дуються вку́пі о́бщим весе́лієм, / Не́бо і земля́ сві́тло лику́ють в па́м'ять твою́, свя́те. / І ми, грі́шнії, прилі́жно ті вопіє́м: / помоли́ся к Влади́ці о нас, / ізба́вити ни от напа́сти / ви́димих і неви́димих враг, // чту́щих пресві́тлую па́м'ять твою́."]},{"h":"Кондак, глас 1","ps":["С ли́ки А́нгельськими предстоя́, / блаже́нне кня́же В'ячесла́ве, / наслажда́єшися Боже́ственния і неізрече́нния добро́ти, / і отту́ду благоде́тельния да́ри поче́рп чуде́с, / всім, притека́ющим ві́рою под твою́ святи́ню // істоча́єши цільба́м дарова́ніє."]},{"h":"Величання","ps":["Велича́єм тя, благові́рний кня́же В'ячесла́ве, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святій мучениці Іулії Карфагенській","e":"Akathist to the Holy Martyr Julia of Carthage","secs":[{"h":"Кондак 1","ps":["Ізбра́нная іспове́днице Христо́ва, свята́я му́ченице Іу́ліє, похва́льная пі́нія прино́сим ті, чистоту́ житія́ твоєго́ ді́вственнаго і честна́я страда́нія твоя́ восхваля́юще; ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, бу́ди пред Ним те́плая моли́твенниця о душа́х на́ших, да зове́м ті:","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Ікос 1","ps":["А́нгелом Небе́сним єще́ на землі́ уподо́билася єси́, Іу́ліє всесла́вная, в пламене́ющей ко Творцю́ любві́ пребива́я і в а́нгельстій чистоті́ себі́ соблюда́я. Ми же, ви́дя добро́ту душі́ твоєя́, єя́же ра́ди Небе́сних черто́гов Влади́ка сподо́би тя, воспіва́єм ті си́це:","Ра́дуйся, блаже́нная Христо́ва после́довательнице.","Ра́дуйся, ві́ри христия́нськия небоя́зненная пропові́днице.","Ра́дуйся, роди́телей боголюби́вих благоче́стіє восприя́вшая.","Ра́дуйся, Боже́ственноє Писа́ніє і за́повіді Госпо́дні возлюби́вшая.","Ра́дуйся, я́ко прия́вши Ду́ха Свята́го, ізмла́да ідолослуже́ніє отри́нула єси́.","Ра́дуйся, я́ко земна́го обру́чника па́че Небе́снаго зна́ти не восхоті́ла єси́.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 2","ps":["Ви́дя нечести́вий твой господи́н ангелоподо́бноє житіє́ твоє́, і я́ко ні лесть, ні преще́нія, ні устраше́нія не возмого́ша к ідолослуже́нію уклони́ти тя, сего́ ра́ди я́ко святу́ю тя почита́ше, Іу́ліє всехва́льная; ти же, благода́тію Спа́совою, я́ко броне́ю, укрепля́ємая і защища́ємая, непреста́нно воспіва́ла єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зумом, сви́ше просвіще́нним, любо́в к ми́ру і вся, я́же в ми́рі, отве́ргла єси́, непоро́чная отрокови́це, і все́ю душе́ю твоє́ю Ісу́са Христа́ возлюби́в, да́же до сме́рти му́ченичеськия Єму́ послужи́ла єси́, среди́ неві́рних і́стиннаго Бо́га пропові́дуя. Сего́ ра́ди, таково́му твоєму́ ра́зуму див'я́ся, глаго́лем:","Ра́дуйся, в моли́тві і по́сте непреста́нно пребива́вшая.","Ра́дуйся, от страсте́й, я́ко щито́м, цілому́дрієм себі́ огражда́вшая.","Ра́дуйся, я́ко ско́рби мно́гія за і́м'я Госпо́днє прия́ла єси́.","Ра́дуйся, я́ко сорасп'я́тися Христу́ вседу́шні вожделі́ла єси́.","Ра́дуйся, во вертогра́ді Небе́снім присноцвету́щая.","Ра́дуйся, я́ко крин, воня́ми доброді́телей благоуха́ющая.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 3","ps":["Си́лою Бо́жиєю сви́ше препоя́санная, благохва́льная ді́во, не́мощ же́нськаго єстества́ отложи́ла єси́, в броню́ іспові́данія Христо́ва обле́кшися; о неві́рующих же во Христа́ Ісу́са сле́зи пролива́ла єси́, я́ко о немогу́щих наслі́довати жи́зні ві́чния і в селе́ніїх ра́йських воспі́ти Єму́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи крі́пкую наде́жду то́кмо на єди́наго Бо́га, неврежде́нна преби́в, мучи́телей горди́ню побіди́ла єси́, му́ченице многострада́льная, і віне́ць побі́ди от Вседержи́теля прия́ла єси́. Ті́мже, му́жественноє в же́нстій пло́ті душі́ мудрова́ніє нося́щей, удивля́ємся си́лі ду́ха твоєго́ і умиле́нно поє́м ті:","Ра́дуйся, я́ко за ві́ру і́стинную со ідолослужи́тели крі́пко ра́товала єси́.","Ра́дуйся, я́ко ра́ди Го́спода Ісу́са мно́гажди пострада́ла єси́.","Ра́дуйся, я́ко устраши́ти тя муче́нії лю́тими тща́щіїся от Христа́ тя не отврати́ша.","Ра́дуйся, я́ко ні ра́ни, ні преще́нія от любве́ Єго́ отлучи́ти тя не возмого́ша.","Ра́дуйся, терпі́нієм твої́м ко́зні вра́жия побіди́вшая.","Ра́дуйся, за іспові́даніє ві́ри жи́зні своєя́ не пощади́вшая.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 4","ps":["Бу́ря я́рости мучи́телеви нападе́ на тя, незло́бивая голуби́це, но не поколеба́ крі́пости душі́ твоєя́: основа́на бо бі на тве́рдем ві́ри Христо́ви ка́мені, на не́мже ти неподви́жно стоя́щи, воспіва́ла єси́ Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Імі́я всегда́ пред оча́ми свої́ми Го́спода, предста́ла єси́ на суди́щі му́жественно, і врага́ терпі́нієм твої́м побіди́ла єси́, всехва́льная Іу́ліє. Ті́мже, помина́юще честна́я твоя́ страда́нія, со умиле́нієм зове́м ті:","Ра́дуйся, повелі́ніє нечести́воє му́жественно отве́ргшая.","Ра́дуйся, болі́зньми многообра́зними не устраше́нная, А́нгели удиви́вшая.","Ра́дуйся, по лани́там деви́чеським неща́дно біє́нная.","Ра́дуйся, за власи́ мучи́телями терза́ємая і влачи́мая.","Ра́дуйся, я́ко ра́ди любві́ ко Христу́ лю́тия му́ки му́жественно переноси́ла єси́.","Ра́дуйся, я́ко страда́нієм за Него́ несказа́нно ра́довалася єси́.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́билася єси́, прему́драя ді́во, єгда́ на кресті́ неві́рними ра́сп'ятая, лику́ющи, славосло́вила єси́ Спаси́теля ми́ра, за род челові́чеський на Кресті́ в же́ртву Себі́ прине́сшаго; ті́мже днесь Тому́жде Го́сподеві предстої́ши, непреста́нно воспіва́ющи а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше лю́діє пресла́вноє чу́до, по ісхо́ді святи́я душі́ твоя́, я́ко із уст твої́х голуби́ця бі́лая к Небесі́ возлеті́, удиви́шася зіло́; мучи́теліє же, узрі́вше А́нгелов близ бездиха́ннаго ті́ла твоєго́, біжа́ша, страх бо ве́лій нападе́ на ня. Ми же, твоє́ до́блественноє му́жество помина́юще, вопіє́м ті:","Ра́дуйся, Спаси́телю ми́ра, на Кресті́ ви́сящу, спострада́вшая.","Ра́дуйся, кре́стним страда́нієм Єго́ соприча́стницею би́вшая.","Ра́дуйся, во страда́ніїх твої́х благода́тную по́мощ от Христа́ Бо́га получи́вшая.","Ра́дуйся, от крове́й твої́х сві́тлую ри́зу спасе́нія себі́ істка́вшая.","Ра́дуйся, я́ко неві́рних сві́том ві́ри єва́нгельськия просвіти́ла єси́.","Ра́дуйся, я́ко любо́вію твоє́ю ко Христу́ А́нгельськая ликостоя́нія возвесели́ла єси́.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 6","ps":["Пропові́дниця чуде́с і сла́ви Бо́жия яви́лася єси́, ла́стовице доброгла́сная, і́ноком оби́телі близлежа́щия, А́нгелом Госпо́днім о му́ченичестій кончи́ні твоє́й ізвіще́нним. Они́ же, взя́вше свято́є ті́ло твоє́, погребо́ша є во хра́мі, воспіва́я Бо́гові: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́, я́ко світоза́рная звізда́, і Боже́ственною благода́тію отгна́ла єси́ многобо́жія тьму, смире́нная а́гнице, просвіти́вши мно́гия лю́ди, і́же ви́діша чудеса́ Бо́жия і ісціле́нія мно́гая, от моще́й твої́х оби́льно проістека́ющия. Просвіти́ у́бо і нас, омраче́нних мгло́ю гріхо́вною, і сві́том невече́рнім озари́ тя сла́в'ящих і пою́щих такова́я:","Ра́дуйся, Го́спода Ісу́са страда́ньми і чудеси́ просла́вившая.","Ра́дуйся, мно́гая страда́нія за і́м'я Єго́ претерпі́вшая.","Ра́дуйся, ві́ри і́стинния неустраши́мая пропові́днице.","Ра́дуйся, неду́гов челові́чеських ми́лостивая ціли́тельнице.","Ра́дуйся, вінце́м іспове́дничеським от Бо́га украше́нная.","Ра́дуйся, я́ко ма́слина, в дому́ Бо́жії насажде́нная.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 7","ps":["Хотя́ Влади́ка і Госпо́дь Сла́ви яви́ти тя, ві́рную рабу́ Свою́, я́ко світи́льник, во тьмі світя́щий і сві́том Небе́сним всіх просвіща́ющий, призва́ тя на по́двиг страда́льчеський, да ви́дящії му́жество і тве́рдую ві́ру твою́ пока́ються в заблужде́ніїх свої́х і вку́пі со ізбра́нними да воспою́ть Єму́: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вий живо́т, ві́чний, прия́ла єси́, богохва́льная ді́во, єгда́ кре́стною кончи́ною от пло́ті своєя́ многострада́льния разріши́вшися, в черто́г Небе́снаго Жениха́ вошла́ єси́, Єго́же моля́щи не преста́й за ни, грі́шния, любо́вію страда́нія твоя́ почита́ющия і глаго́лющия:","Ра́дуйся, добропобі́дная страстоте́рпице, сме́рті тіле́сния не устраши́вшаяся.","Ра́дуйся, до́блестная му́ченице, в страда́ніїх, я́ко зла́то в горни́лі, очи́стившаяся.","Ра́дуйся, доброгла́сная цівни́це, си́лу Бо́жию пред нечести́вими пропові́давшая.","Ра́дуйся, богому́драя ді́во, к і́стинній ві́рі мно́гія заблу́ждшия лю́ди приве́дшая.","Ра́дуйся, благово́нная сми́рно, я́зви Го́спода твоєго́ на ті́лі своє́м носи́вшая.","Ра́дуйся, страда́лице Христо́ва, му́ченичеський лик на Небесі́х возвесели́вшая.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 8","ps":["Стра́нния і стра́шния страда́нія святи́я му́ченици ви́дівше, ві́рнії удиви́шася, ка́ко мла́да отрокови́ця в ю́ностнім тілесі́ такови́я му́жественно за Христа́ терпи́ть му́ки, да і ми, іспо́лншеся умиле́нія, благода́рно возопії́м Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь Сладча́йший Ісу́с сла́дость, весь жела́ніє тебі́ бисть, страстоте́рпице всехва́льная, Єго́ бо ра́ди го́ркія му́ки і тя́жкия страда́нія да́же до му́ченичеськия кончи́ни ра́достно терпі́ла єси́. Ті́мже і по сме́рті честно́є ті́ло твоє́ Бо́жиїм ізволе́нієм нетлі́нно сохрани́ся, да істоча́єть оби́ліє чуде́с с ві́рою к заступле́нію твоєму́ прибега́ющим і моли́твенно тебі́ взива́ющим:","Ра́дуйся, я́ко страда́нієм твої́м Це́рков Христо́ву украси́ла єси́.","Ра́дуйся, я́ко ісціле́ній неоскудіва́ємий істо́чник яви́лася єси́.","Ра́дуйся, нетлі́нієм моще́й твої́х сла́вно от Бо́га возвели́ченная.","Ра́дуйся, в ли́ці дів на Небесі́ просла́вленная.","Ра́дуйся, лозо́ многопло́дная, благода́тними да́ри ві́рних пита́ющая.","Ра́дуйся, кади́льнице злата́я, я́ко фиміа́м благоуха́нний, моли́тви Твоя́ за ни к Бо́гу принося́щая.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 9","ps":["Всі А́нгели і святи́х ли́ци ра́достно тя сріто́ша, всехва́льная, єгда́ во врата́ Ца́рствія Небе́снаго вошла́ єси́, во є́же побі́ди віне́ць от руки́ Христа́ Жизнода́вця прия́ти. У́бо і нам, недосто́йним, наслі́діє ві́чноє со святи́ми іспроси́, да возмо́жем ку́пно с тобо́ю воспіва́ти Бо́гові во Ца́рствії Єго́: Аллилу́я."]},{"h":"Ікос 9","ps":["Ві́тіії многовіща́ннії не возмо́гуть по достоя́нію восхвали́ти доброді́телі і страда́нія твоя́, преди́вная ді́во, ка́ко благода́тію Бо́жиєю побіди́ла єси́ дре́вняго іско́ннаго врага́ і посрами́ла єси́ і́дольськую пре́лесть, мно́жество душ ко Христу́ приве́дши. Ті́мже, ублажа́юще му́ченичеськую кончи́ну твою́, поє́м со умиле́нієм такова́я:","Ра́дуйся, во о́браз христия́нським ді́вам сви́ше пронарече́нная.","Ра́дуйся, свято́є целому́дріє і чистоту́ ді́вства до́брі сохра́ншая.","Ра́дуйся, і́стинноє богопочита́ніє да́же до сме́рти возлюби́вшая.","Ра́дуйся, я́ко світи́льник златоле́пний посреді́ му́чениць возсія́вшая.","Ра́дуйся, Боже́ственним огне́м сердця́ на́ша возжига́ющая.","Ра́дуйся, в Небе́снім вертогра́ді неізрече́нною ра́достію наслажда́ющаяся.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 10","ps":["Спасти́ся всім хотя́щим споспі́шествуй моли́твами твої́ми пред Го́сподем, му́ченице свята́я, і іспроси́ разріше́ніє гріхо́в почита́ющим честна́я страда́нія твоя́, да вопіє́м с тобо́ю: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю моли́тв твої́х от вся́каго іскуше́нія нас огради́, іспове́днице Христо́ва, і путе́м пра́вим в Ца́рствіє Небе́сноє руководи́, зане́ даде́ся тебі́ благода́ть моли́тися о лю́діх правосла́вних пред Престо́лом Го́спода Вседержи́теля. Ми же, помина́юще по́двиги і страда́нія твоя́, ублажа́єм тя си́це:","Ра́дуйся, му́чеников ра́дованіє і ді́вственников сла́во.","Ра́дуйся, ві́рним христия́ном крі́пкоє заступле́ніє.","Ра́дуйся, от го́рних висо́т к земноро́дним ми́лостиво приника́ющая.","Ра́дуйся, всім тружда́ющимся по́мощ неви́димо подаю́щая.","Ра́дуйся, во благи́х проше́нія на́ша ско́ро ісполня́ющая.","Ра́дуйся, в неду́зіх стра́ждущих благода́тно посіща́ющая.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим ті, достохва́льная Іу́ліє, прославля́юще твоя́ за Христа́ страда́нія, і мо́лим тя: іспроси́ у Ми́лостиваго Го́спода всім нам здра́віє, долгоде́нствіє і на враги́ побі́ду і одолі́ніє, а найпа́че – гріхо́в проще́ніє і душ спасе́ніє, да поє́м Єму́ во ві́ки: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлими луча́ми чуде́с немерца́ємо сія́єши, Іу́ліє добронра́вная, просвіща́я сердца́ ві́рних, ісціля́я неду́жних, утіша́я бі́дствующих і моля́ся о всіх притека́ющих к тебі́ с любо́вію і вопію́щих ті та́ко:","Ра́дуйся, о спасе́нії грі́шних усе́рдная хода́тайце.","Ра́дуйся, ді́вам і жена́м христия́нським ми́лостивая помо́щнице.","Ра́дуйся, ві́рних чад Це́ркве Правосла́вния духо́вноє услажде́ніє.","Ра́дуйся, в го́рестіх і страда́ніїх при́сноє утіше́ніє.","Ра́дуйся, неду́ги тіле́сния і душе́вния ско́ро ісціля́ющая.","Ра́дуйся, ше́ствующих путе́м Христо́вих за́повідей укріпля́ющая.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 12","ps":["Благода́ть Госпо́дня моли́твами твої́ми, свята́я му́ченице Іу́ліє, дарова́ся істо́чнику ціле́бния води́, із ка́мене істе́кшему; сего́ ра́ди і хра́му во і́м'я твоє́ созда́тися на мі́сті кре́стних страда́ній твої́х благоволи́ Бог. Ті́мже, і нас, па́м'ять твою́ сві́тло пра́зднующих, благода́ті іспо́лни моли́твами твої́ми, да воспоє́м вку́пі с тобо́ю чуде́с Пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще Бо́га, ди́внаго во святи́х Свої́х, ублажа́єм тя, страстоте́рпице Христо́ва, почита́я страда́нія твоя́, сла́вим долготерпі́ніє і непобіди́моє му́жество, хва́лим му́ченичеськую кончи́ну і мо́лим тя: простри́ с Небесе́ по́мощ твою́ і на нас, вопію́щих ті такова́я:","Ра́дуйся, ча́ше даро́в Бо́жиїх преізоби́льная.","Ра́дуйся, сокро́вищнице ісціле́ній неоску́дная.","Ра́дуйся, ра́дости несконча́ємия і сла́ви ві́чния хода́тайце.","Ра́дуйся, благ Небе́сних пода́тельнице.","Ра́дуйся, тіле́с на́ших здра́віє і душ спасе́ніє.","Ра́дуйся, ві́рним христия́ном крі́пкоє заступле́ніє.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 13","ps":["О пресла́вная і всехва́льная му́ченице Іу́ліє! Прийми́ ми́лостивно от нас ма́лоє моле́ніє сіє́ і не преста́ни моли́тися за ни ко Го́споду, да ізба́вить нас от враг ви́димих і неви́димих і твої́м богоприя́тним хода́тайством сподо́бит нас Ца́рствія Небе́снаго, іді́же вку́пі с тобо́ю і всі́ми святи́ми сподо́бимся воспіва́ти Єму́ побі́дную піснь: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом Небе́сним єще́ на землі́ уподо́билася єси́, Іу́ліє всесла́вная, в пламене́ющей ко Творцю́ любві́ пребива́я і в а́нгельстій чистоті́ себі́ соблюда́я. Ми же, ви́дя добро́ту душі́ твоєя́, єя́же ра́ди Небе́сних черто́гов Влади́ка сподо́би тя, воспіва́єм ті си́це:","Ра́дуйся, блаже́нная Христо́ва после́довательнице.","Ра́дуйся, ві́ри христия́нськия небоя́зненная пропові́днице.","Ра́дуйся, роди́телей боголюби́вих благоче́стіє восприя́вшая.","Ра́дуйся, Боже́ственноє Писа́ніє і за́повіді Госпо́дні возлюби́вшая.","Ра́дуйся, я́ко прия́вши Ду́ха Свята́го, ізмла́да ідолослуже́ніє отри́нула єси́.","Ра́дуйся, я́ко земна́го обру́чника па́че Небе́снаго зна́ти не восхоті́ла єси́.","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Кондак 1","ps":["Ізбра́нная іспове́днице Христо́ва, свята́я му́ченице Іу́ліє, похва́льная пі́нія прино́сим ті, чистоту́ житія́ твоєго́ ді́вственнаго і честна́я страда́нія твоя́ восхваля́юще; ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, бу́ди пред Ним те́плая моли́твенниця о душа́х на́ших, да зове́м ті:","Ра́дуйся, свята́я Іу́ліє, неві́сто Христо́ва пресла́вная."]},{"h":"Молитва","ps":["О свята́я ді́во і му́ченице Іу́ліє, і́стинная неві́сто Христо́ва! К тебі́, я́ко благонаде́жней пред Го́сподем предста́тельнице на́шей усе́рдно прибіга́єм і во умиле́нії серде́ць на́ших мо́лимся: предстоя́щи у Престо́ла Пресвяти́я Тро́йці і наслажда́ющися неізрече́ннаго блаже́нства Небе́снаго, при́зри у́бо ми́лостивно на нас, принося́щих ті хвале́бноє пі́ніє сіє́, і іспроси́ у Преблага́го Го́спода дарова́ти нам душе́вноє і тіле́сноє здра́віє, во благоче́стії христия́нстім преуспі́яніє, к житію́ вре́менному ну́жная і дово́льная і вся я́же ко спасе́нію потре́бная, да ми́рно і благоче́стно пожи́вше, сподо́бимся благу́ю кончи́ну христия́нськую улучи́ти і Ца́рствіє Небе́сноє наслі́довати, сла́в'яще ди́внаго во святи́х Свої́х Бо́га, Отця́ і Си́на і Свята́го Ду́ха, во ві́ки віко́в. Амі́нь."]},{"h":"Величання","ps":["Велича́єм тя, / страстоте́рпиця Христо́ва Іу́ліє, / і чтим честно́є страда́ніє твоє́, / я́же за Христа́ // претерпі́ла єси́."]}],"notes":[]},{"u":"Акафіст святителю Дмитрію, митрополиту Ростовському, чудотворцю","e":"Akathist to St Demetrius, Metropolitan of Rostov, the Wonderworker","secs":[{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, многоціле́бний чуде́с істо́чниче, неісчерпа́ємия благода́ті хода́таю, те́плий моли́твенниче, вели́кий святи́телю Христо́в Дими́тріє, я́ко імі́яй дерзнове́ніє ко Христу́ Бо́гу на́шему, от вся́ких нас бід свободи́ зову́щих:","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Ікос 1","ps":["А́нгел нра́вом, а́ще і челові́к єстество́м бил єси́, святи́телю Дими́тріє: от са́мих бо млади́х ногте́й ум твой, пренебре́гши земна́я, в небе́сная впери́л єси́, і плоть нося́, о пло́ті неради́л єси́. Ті́мже і всели́ся в тя Пресвяти́й Дух, Єго́же тя обита́лищем би́ти уві́дівше, похва́льная воспису́єм ті:","Ра́дуйся, незло́бієм твої́м А́гнця, прорече́ннаго Іса́їєм, подража́вий;","ра́дуйся, милосе́рдієм ни́щія препита́вий.","Ра́дуйся, воздержа́нієм а́нгелов удиви́вий;","ра́дуйся, посто́м і моли́твою плоть твою́ удручи́вий.","Ра́дуйся, к подвла́стним чадолюби́вим отце́м би́вий;","ра́дуйся, стра́ждущия сердобо́лієм уті́шивий.","Ра́дуйся, вмі́сто тлі́нних нетлі́нная стяжа́вий;","ра́дуйся, небе́сний челові́че.","Ра́дуйся, земни́й а́нгеле;","ра́дуйся, Ду́ха Свята́го сосу́де ізбра́нний.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 2","ps":["Ви́дяще оби́льную реку́ чуде́с і ісціле́ній, от святи́х твої́х моще́й істека́ющую, благогові́нія і ра́дости іспо́лншеся, благодари́м Бо́га, прославля́ющаго святи́я Своя́, Єму́же і о тебі́ вопіє́м: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум і́стиннаго богосло́вія внуша́я ча́дом Христо́вим Це́ркве, златослове́сними поуче́ніями утвержда́л єси́, єрети́чествующих же раско́льников, привлека́я к спаси́тельному єдиноми́слію, в заблужде́ніях облича́л єси́, за таково́є твоє́ о душа́х на́ших попече́ніє взива́єм ті си́це:","Ра́дуйся, таї́нниче Пресвяти́я Тро́йці;","ра́дуйся, пропові́дниче неісче́тних чуде́с Бо́жиїх.","Ра́дуйся, апо́стольських преда́ній блюсти́телю;","ра́дуйся, бри́нських душегу́бцев побіди́телю.","Ра́дуйся, пла́меню, є́ресі пожига́ющий;","ра́дуйся, гро́ме, устраша́ющий соблазня́ющия.","Ра́дуйся, свіще́, Бо́гом возже́нная, мрак нече́стія разгоня́ющая;","ра́дуйся, звіздо́, путь ко спасе́нію показу́ющая.","Ра́дуйся, тимпа́ні, Бо́жию сла́ву бряця́яй;","ра́дуйся, орга́не Ду́ха Свята́го.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жия єще́ во вре́менной жи́зні прия́л єси́ власть, свя́те Дими́тріє, неду́ги ісціля́ти і бі́си ізгоня́ти. По сме́рті же твоє́й найпа́че просла́ви тебе́ Всемогу́щий Бог мно́гими чудотворе́ніями, да всі, взира́я на сіє́, усе́рдно притека́ють ко ісціле́нію тобо́ю от неду́гов тіле́сних, а па́че душе́вних, Бо́гу же вопію́ть: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я неуси́пноє попече́ніє о спасе́нії душ, вві́ренних тебі́ от Бо́га, святи́телю Дими́тріє, па́стирськи к душеспаси́тельной жи́зні і сло́вом і са́мим ді́лом, показу́я нелі́ностний по́двиг в подража́нії святи́м Бо́жиїм, непреста́нно наставля́л єси́. Сего́ ра́ди прийми́ от на́шего усе́рдія досто́йния похвали́ тебі́:","Ра́дуйся, па́стирю до́брий, заблужда́ющих по гора́м суєму́дрія взиска́вий;","ра́дуйся, благи́й ра́бе і ві́рний, да́нний тебі́ от Го́спода тала́нт усугу́бивий.","Ра́дуйся, ді́лателю виногра́да Христо́ва;","ра́дуйся, благоче́стія сто́лпе неподви́жимий.","Ра́дуйся, тве́рдоє забра́ло Христо́ви Це́ркве;","ра́дуйся, щі́те, защища́яй благоче́стіє.","Ра́дуйся, мечу́ острі́йший, посіка́яй злоче́стіє;","ра́дуйся, непоколеби́моє Правосла́вія основа́ніє.","Ра́дуйся, тве́рдий ка́меню ві́ри;","ра́дуйся, корми́ло церко́вноє, управля́ющеє ві́рних к ти́хому приста́нищу.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 4","ps":["Бу́ря єресе́й от преіспо́дніх, чрез А́рія по Гре́ції возроди́вшаяся, а в послі́дняя лі́та про́ісками Марти́на Армени́на чрез бри́нських скитонача́льников возни́кшая в на́шем оте́честві, гото́ва била́ опрове́ргнуть тишину́ єди́ния, святи́я собо́рния і апо́стольськія Це́ркві. Ти же, па́стир до́брий, положи́вий ду́шу твою́ за о́вці, прогна́в о́них душепа́губних волко́в, бу́рю суєму́дрія укроти́л єси́, ві́рния же научи́л єси́ Трийпоста́сному Бо́гу взива́ти: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шаша суєму́дреннії раско́льници твоє́ к ним ізобличе́ніє, є́же ти, болі́знуя о серде́чном їх заблужде́нії, написа́л єси́, возбеси́шася зіло́ зіло́, і мно́жество із них вмі́сто до́лжнаго ісправле́нія а́дський пла́мень ізри́гнуша на тя; ти же, я́ко тве́рдий адама́нт, под уда́рами зло́би і не́нависті не ізміни́лся єси́. Сего́ ра́ди Це́рков свята́я блажи́ть тя приві́тствії си́ми:","Ра́дуйся, а́нгелов сожи́телю;","ра́дуйся, апо́столов преє́мниче.","Ра́дуйся, святи́телей сопресто́льниче;","ра́дуйся, Россі́йський златоу́сте.","Ра́дуйся, Спиридо́ну, вели́кому Васи́лію, Григо́рію Богосло́ву і про́чим вели́ким святи́телям єдиноче́стне;","ра́дуйся, Никола́ю Мирликі́йському і Меле́тію Антіохі́йському єдинонра́вне.","Ра́дуйся, преподо́бних собесі́дниче;","ра́дуйся, мона́хов і по́стников наста́вниче.","Ра́дуйся, му́чеников удобре́ніє;","ра́дуйся, пра́ведних украше́ніє.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 5","ps":["Боготе́чная звізда́ яви́лся єси́ в тече́нії твоє́м, є́же ти соверша́л єси́, своє́ устроя́я спасе́ніє; приме́ром же ві́рних ду́ші назида́я, научи́л єси́ благоприя́тно пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше а́нгельстії чи́нове єще́ во вре́менной жи́зні вели́кіє твої́ по́двиги во вся́ком благоче́стії і чистоті́, удивля́хуся, прославля́юще Человіколю́бця Бо́га, немощно́є челові́чеськоє єстество́ подкрепля́ющаго. Ми же тя, усе́рдно любо́вію почита́юще, честву́єм похвала́ми си́ми:","Ра́дуйся, луча́ Трисо́лнечнаго Сві́та;","ра́дуйся, світи́льниче, на сві́щниці церко́вном поста́вленний.","Ра́дуйся, світи́ло, путь пра́вий показу́ющеє;","ра́дуйся, во́їне Христо́в непобіди́мий.","Ра́дуйся, Єдиносу́щния Тро́йці і́стинний побо́рниче;","ра́дуйся, уста́ єрети́чеськая загради́вий.","Ра́дуйся, златослове́сними уста́ми небе́сния і́стини віща́яй;","ра́дуйся, вся своя́ імі́нія по словесі́ Госпо́дню прода́вий.","Ра́дуйся, єди́наго безці́ннаго би́сера — Христа́ Го́спода сниска́вий;","ра́дуйся, вма́лі бив ві́рен, над мно́гими поста́вленний.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 6","ps":["Пропові́дник немо́лчний та́йни Пресвяти́я, Єдиносу́щния і Неразділи́мия Тро́йці бил єси́. Сего́ ра́ди пропові́дуєть Россі́я вели́чія Бо́жия, пока́занная на тебі́, святи́телю Дими́тріє, я́ко прия́л єси́ дар ціли́ти неду́ги душе́вниє і тіле́сниє, да всі єди́ним се́рдцем і єди́ними усти́ воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ во возлю́бленной Бо́гом душе́ твоє́й блиста́ющий і́стиннаго богові́дінія світ на освяще́ніє і просвіще́ніє ві́рних, єго́же с сла́достію внима́ющії спаси́тельному уче́нію твоєму́ ви́дяще, ві́рно позна́єм, я́ко і в єдинонадеся́тий час прише́дий, ра́вний с дре́вніми святи́ми і богоно́сними отці́ дина́рій прия́л єси́. Ті́мже восхваля́єм тя си́це:","Ра́дуйся, вмісти́лище доброді́телей;","ра́дуйся, досто́йноє святи́ні жили́ще.","Ра́дуйся, мо́ре, нече́стіє ми́ра потопи́вшеє;","ра́дуйся, кри́не благоуха́нний, чуде́сно процві́тшій.","Ра́дуйся, сокро́вище медото́чних уче́ній;","ра́дуйся, уневі́стивий ду́шу твою́ Жениху́ Христу́.","Ра́дуйся, смире́нія Єго́ і́стинний подража́телю;","ра́дуйся, і́ночеськую нищету́ до конця́ сохрани́вий.","Ра́дуйся, вше́дий с му́дрими в ра́дость Го́спода твоєго́;","ра́дуйся, благово́ніє Ду́ха Свята́го.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 7","ps":["Хотя́ досто́йним о́бразом соверши́ти по́двиг, возложе́нний на тя от Бо́га, пе́рвіє укріпля́л єси́ свою́ ду́шу прочита́нієм житія́ святи́х, предполага́я себі́ подража́ніє о́ним. Та́же почу́вствовав по́льзу, із того́ проістека́ющую, не обліни́лся єси́ би́ти списа́телем жи́зні тіх, с ни́миже ни́ні в невече́рнім сві́те лику́єши, воспіва́я Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя о нас моли́твенника, ціли́теля душ і тіле́с, і хода́тая нам спасе́нія ві́чнаго стяжа́хом; но благода́рним се́рдцем і усти́ Бо́гу, толи́каго чудотво́рця в на́ші времена́ дарова́вшему, досто́йно воспі́ти не могу́ще, тебі́, святи́телю і вели́кий уго́дниче Христо́в Дими́тріє, похва́льная дерза́єм приноси́ти си́це:","Ра́дуйся, всім скорб'я́щим прия́тноє попече́ніє;","ра́дуйся, ско́рий от вся́кия болі́зні і безме́здний врачу́.","Ра́дуйся, злих по́мислов прогони́телю;","ра́дуйся, я́ко твої́ми моли́твами сліпи́є прозрі́ша.","Ра́дуйся, я́ко твої́м хода́тайством хроми́є і безно́гіє ходи́ти нача́ша;","ра́дуйся, я́ко тобо́ю от мно́гих бі́сове отгна́шася.","Ра́дуйся, я́ко твої́м заступле́нієм разсла́бленниє ісцілі́ша;","ра́дуйся, ломо́тния і опу́хлия уврачева́вий.","Ра́дуйся, тряса́вичних і огневи́чних болі́зней ціле́бниче;","ра́дуйся, от неісці́льния водяни́я і ка́менния болі́зні здра́ві возста́вивий.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 8","ps":["Стра́нно неду́гом неві́рія одержи́мим ви́діти, ка́ко в ме́ртвенном ті́лі і тлі́нном возмо́жно а́нгельськоє проходи́ти житіє́ непреткнове́нно, і по успе́нії от єди́наго с ві́рою прикоснове́нія к ті́лу, нетлі́нієм почте́нному, ди́вная соверша́ються. Ми же на тебі́, святи́телю Дими́тріє, но́воє чуде́с всемогу́щаго Бо́га соби́тіє сли́шаще і ви́дяще, моли́твами твої́ми врачу́ємі, взива́єм Єму́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь распали́вшись і́скреннею любо́вію к Бо́гу, всего́ себе́ пре́дал єси́ во́лі Єго́, і вся веще́ственная і тлі́нная вміни́в уме́ти би́ти, ду́хом, душе́ю і се́рдцем возжелі́л єси́ наслажда́тися лицезрі́нієм Бо́жиїм. Но ни́ні вся потре́бная тебі́ во ве́чность іспроси́л єси́, не забу́ди і нас, тре́бующих твоєго́ заступле́нія і хода́тайства, да тім па́че похва́льная воспису́єм ті:","Ра́дуйся, Бо́гу соверше́нно угоди́вий;","ра́дуйся, віне́ць безсме́ртія жи́зні получи́вий.","Ра́дуйся, насища́яйся Бо́жия благода́ті;","ра́дуйся, проро́ками за об'ясне́ніє їх писа́ній похвале́нний.","Ра́дуйся, апо́столами за послі́дованіє їх стопа́м ублаже́нний;","ра́дуйся, святи́телями за єдиноми́сленную с ни́ми ре́вность просла́вленний.","Ра́дуйся, му́чениками за списа́ніє страда́ній їх увінча́нний;","ра́дуйся, преподо́бними за подража́ніє їм во вся́ком благоче́стії і чистоті́ посто́м і моли́твою к ли́ку їх причте́нний.","Ра́дуйся, пра́ведниками за височа́йшеє твоє́ смире́ніє і труди́ превознесе́нний;","ра́дуйся, от всіх святи́х ра́достними приве́тствіями усрета́нний.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 9","ps":["Вся́кия біди́, ско́рби і напа́сти ізбавля́й нас, свя́те Дими́тріє, твої́ми к Бо́гу те́плими моли́твами і потщи́ся дарова́ти нам вре́менная блага́я, к жи́зні потре́бная, і ві́чная, да с тобо́ю ку́пно в селе́нії пра́ведних воспоє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не возмо́жеть ізрещи́ дово́льно коли́чество благода́ті Бо́жия, ізлія́нния на тебі́, свя́те Дими́тріє, но любо́вію твоє́ю побіжда́ємі, дерза́єм воспіва́ти тебі́:","Ра́дуйся, насади́телю благи́х;","ра́дуйся, іскорени́телю злих.","Ра́дуйся, чистоти́ селе́ніє;","ра́дуйся, печа́льних утіше́ніє.","Ра́дуйся, отча́янних заступле́ніє;","ра́дуйся, сиро́т пита́телю.","Ра́дуйся, оби́димих предста́телю;","ра́дуйся, преподо́бія і пра́вди і́стинний храни́телю.","Ра́дуйся, пресві́тлий сто́лпе о́блачний, просвіща́яй мно́жеством чуде́с;","ра́дуйся, о́блаче росоно́сний, погаша́яй пла́мень страсте́й.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу, о пло́ті твоє́й неради́л єси́, но посто́м, бді́нієм моли́твами і непреста́нними труда́ми плоть твою́ удручи́л єси́, я́ко в тимпа́ні, во умервщле́нії тілесе́ благоприя́тно Бо́гу вопія́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́, огражда́ющая от всіх бід, усе́рдно тя в по́мощ призива́ющих, святи́телю Дими́тріє, я́ко во всіх страна́х Россі́йськия держа́ви я́сно пропові́дуються оби́льния чудеса́, би́вшая у цільбоно́снаго твоєго́ гро́ба. Сего́ ра́ди ублажа́єм тя си́ми:","Ра́дуйся, ча́ша, істоча́ющая нам єле́й ми́лости Бо́жия;","ра́дуйся, больни́х ісціле́ніє.","Ра́дуйся, немощни́х подкріпле́ніє;","ра́дуйся, стра́ждущих ско́рая по́моще.","Ра́дуйся, претика́ющихся о ка́мень собла́зна наста́вниче;","ра́дуйся, оби́димих засту́пниче.","Ра́дуйся, омраче́нния просвіти́вий;","ра́дуйся, просвіще́нния утверди́вий.","Ра́дуйся, расточе́нная собра́вий;","ра́дуйся, к небе́сному немерца́ющему сві́ту напра́вивий.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 11","ps":["Пі́ніє немо́лчноє прине́сл єси́ Пресвяті́й Тро́йце, свя́те Дими́тріє, о́во ми́слію, о́во гла́сом, о́во сло́вом, о́во благотворе́ніями. І ни́ні предстоя́ престо́лу Боже́ственному, моли́ о воспіва́ющих о тебі́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рноє твоє́ уче́ніє, ум небе́сний явля́ющеє, подтвержда́ємоє ни́ні нетлі́нієм моще́й твої́х і мно́жеством чуде́с, я́вноє і действи́тельнейшеє сре́дство дарова́ Человіколюби́вий Бог на обличе́ніє єрети́чествующих і на утвержде́ніє правосла́вних. Ни́ні святи́м і медото́чним твої́м уче́нієм упоє́нниє, с благода́рним чу́вствієм вопіє́м ті:","Ра́дуйся, учи́телю прему́дрий;","ра́дуйся, па́стирю преди́вний.","Ра́дуйся, іспові́дниче непоколеби́мий;","ра́дуйся, о́ко сліпи́м.","Ра́дуйся, нога́ хроми́м;","ра́дуйся, рука́ безпомо́щним.","Ра́дуйся, главо́, напо́лненная небе́сним уче́нієм;","ра́дуйся, ла́стовице богоглаго́ливая.","Ра́дуйся, істо́чник златостру́йний;","ра́дуйся, цівни́це духо́вная.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 12","ps":["Благода́ть, да́нная ті от Бо́га, ціли́ти неду́ги тіле́сниє і душе́вниє, свя́те Дими́тріє, созива́єть отвсю́ду почита́ющих явле́ніє твоє́ і ча́ющих тобо́ю получи́ти проси́моє от Бо́га. Ті́мже і ми, припа́дая со умиле́нієм мо́лим тя, ізба́ви нас от зол гріхо́вних, да благода́рно Єму́ воспоє́м: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ чудеса́, святи́телю Дими́тріє, восхваля́єм Бо́га, дарова́вшаго тебі́ такови́я си́ли ісціле́ній. Ти же не возгнуша́йся нас, грі́шних і недосто́йних рабо́в Єго́, но усли́ши нас, во умиле́нії вопію́щих тебі́ си́це:","Ра́дуйся, сві́та непристу́пнаго зри́телю;","ра́дуйся, Жениху́ Христу́ сві́тел світи́льник сохрани́вий.","Ра́дуйся, душевре́дноє уни́ніє от себе́ істреби́вий;","ра́дуйся, жесто́ким путе́м ра́йських селе́ній дости́гший.","Ра́дуйся, нището́ю бога́тия стяжа́вий;","ра́дуйся, смире́нієм получи́вий висо́кая.","Ра́дуйся, тісното́ю простра́нство ві́чноє сниска́вий;","ра́дуйся, поноше́нієм Христа́ ра́ди ві́чную с Ним сла́ву прия́вий.","Ра́дуйся, от Святи́я Тро́йці увінча́нний;","ра́дуйся, не гада́нієм, но лице́м к лицю́ Бо́га смотря́яй.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 13","ps":["О, вели́кий святи́телю Дими́тріє, раско́лов і єресе́й іскорени́телю! Прийми́ сіє́ похва́льноє пі́ніє і моли́ Всемогу́щаго умири́ти мир і спасти́ ду́ші на́ша, всіх правосла́вно Трийпоста́сному Бо́гу вопію́щих: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел нра́вом, а́ще і челові́к єстество́м бил єси́, святи́телю Дими́тріє: от са́мих бо млади́х ногте́й ум твой, пренебре́гши земна́я, в небе́сная впери́л єси́, і плоть нося́, о пло́ті неради́л єси́. Ті́мже і всели́ся в тя Пресвяти́й Дух, Єго́же тя обита́лищем би́ти уві́дівше, похва́льная воспису́єм ті:","Ра́дуйся, незло́бієм твої́м А́гнця, прорече́ннаго Іса́їєм, подража́вий;","ра́дуйся, милосе́рдієм ни́щія препита́вий.","Ра́дуйся, воздержа́нієм а́нгелов удиви́вий;","ра́дуйся, посто́м і моли́твою плоть твою́ удручи́вий.","Ра́дуйся, к подвла́стним чадолюби́вим отце́м би́вий;","ра́дуйся, стра́ждущия сердобо́лієм уті́шивий.","Ра́дуйся, вмі́сто тлі́нних нетлі́нная стяжа́вий;","ра́дуйся, небе́сний челові́че.","Ра́дуйся, земни́й а́нгеле;","ра́дуйся, Ду́ха Свята́го сосу́де ізбра́нний.","Ра́дуйся, Правосла́вія ревни́телю;","ра́дуйся, душепа́губних раско́лов іскорени́телю.","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і ізря́дний уго́дниче Христо́в, многоціле́бний чуде́с істо́чниче, неісчерпа́ємия благода́ті хода́таю, те́плий моли́твенниче, вели́кий святи́телю Христо́в Дими́тріє, я́ко імі́яй дерзнове́ніє ко Христу́ Бо́гу на́шему, от вся́ких нас бід свободи́ зову́щих:","Ра́дуйся, Дими́тріє, но́вий і вели́кий чудотво́рче."]},{"h":"Молитва","ps":["О, всеблаже́нний святи́телю Дими́тріє, вели́кий уго́дниче Христо́в, златоу́сте Россі́йський, усли́ши нас, грі́шних, моля́щихся тебі́, і принеси́ моли́тву на́шу к Ми́лостивому і Человіколю́бцю Бо́гу, Єму́же ти ни́ні в ра́дості святи́х і с ли́ки а́нгел предстої́ши. Умоли́ Єго́ благоутро́біє, да не осу́дить нас по беззако́ніям на́шим, но да сотвори́ть с на́ми по ми́лості Своє́й, іспроси́ нам у Христа́ і Бо́га на́шего ми́рноє і безм'яте́жноє житіє́, здра́віє душе́вноє і тіле́сноє, землі́ благопло́діє і во всем вся́коє ізоби́ліє і благоде́нствіє, і да не во зло обрати́м блага́я, да́руємая нам от Ще́драго Бо́га, но в сла́ву Єго́ і в прославле́ніє твоєго́ заступле́нія. Да́руй нам богоуго́дно прейти́ по́прище вре́менния жи́зні, ізба́ви нас возду́шних мита́рств і наста́ви нас на путь, веду́щий в селе́нія пра́ведних, іді́же пра́зднующих глас непреста́нний, зря́щих Бо́жия лиця́ неізрече́нную добро́ту. Це́рков же святу́ю от єресе́й і раско́лов сохрани́, ві́рних укріпи́, заблужда́ющих обрати́ і всім да́руй вся, я́же ко спасе́нію і сла́ві Бо́жієй подоба́ющая. Оте́чество твоє́ сохрани́ от враго́в ненаві́тно, но побора́й ору́жію крестоно́снаго во́їнства, і пода́ждь нам всім твоє́ архипа́стирськоє і свято́є благослове́ніє, да о́ним осіня́ємі, ізба́вимся от ко́зней лука́ваго і ізбі́гнем от вся́кия біди́ і напа́сти. Усли́ши моле́ніє на́ше, о́тче Дими́тріє, і моли́ непреста́нно о нас Всеси́льнаго Бо́га, сла́вимаго і покланя́ємаго в Тріє́х Іпоста́сіх, Єму́же подоба́єть вся́кая сла́ва, честь і держа́ва во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Правосла́вія ревни́телю і раско́ла іскорени́телю, / Россі́йський ціле́бниче, і но́вий к Бо́гу моли́твенниче, / списа́ньми твої́ми бу́їх уцілому́дрил єси́, / цівни́це духо́вная, Дими́тріє блаже́нне, // моли́ Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 8","ps":["Звізду́ Россі́йськую от Ки́єва возсія́вшую, / і чрез Но́вград Сі́верський в Росто́в дости́гшую, / всю же страну́ сію́ уче́ньми і чудеси́ озари́вшую, / ублажи́м златослове́снаго учи́теля Дими́трія, / той бо всім вся написа́, я́же к наставле́нію, / да всіх приобря́щеть, я́коже Па́вел Христу́, // і спасе́ть правові́рієм ду́ші на́ша."]},{"h":"Величання","ps":["Велича́єм тя, / святи́телю о́тче Дими́тріє, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши за нас // Христа́, Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святителю Іоанну Золотоустому","e":"Akathist to St John Chrysostom","secs":[{"h":"Кондак 1","ps":["Возбра́нний вождю́ Це́ркве Христо́ви, златослове́сний учи́телю Іоа́нне! От ю́ности доброді́тельми украси́вся, до́брі потруди́лся єси́, і за і́м'я Христо́во гоне́ніє претерпі́в, во ізгна́нії житіє́ сконча́л єси́: сего́ ра́ди на небесі́х сугу́бо просла́влен єси́, му́дрий чи́на Церко́внаго устрої́телю. Ті́мже і ми умиле́нні чтим тя, зову́ще:","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Ікос 1","ps":["А́нгельський о́браз нося́, во пло́ті а́ки безпло́тен пожи́л єси́, Іоа́нне; во спасе́ніє бо бра́тій мно́гія труди́ под'є́мля, ді́ли до́брими Отця́ Небе́снаго просла́вил єси́. Ті́мже ті глаго́лем:","Ра́дуйся, Це́ркве Правосла́вния украше́ніє;","ра́дуйся, роди́телей імени́тих ча́до благослове́нноє.","Ра́дуйся, єще́ во о́трочестві от ма́тере твоєя́ любо́вію ко сло́ву Бо́жию напоє́нний;","ра́дуйся, от ю́ности ра́зум і́гу Христо́ву покори́вий.","Ра́дуйся, Бо́гові усе́рдно послужи́вий;","ра́дуйся, вселе́нния учи́телю.","Ра́дуйся, христия́н всіх време́н в моли́твах наста́вниче;","ра́дуйся, житія́ і́ночеськаго в Царегра́ді обнови́телю.","Ра́дуйся, го́тфов і ски́фов просвіти́телю;","ра́дуйся, богоукріпле́нний пра́вди ревни́телю.","Ра́дуйся, вше́дий в ра́дость Го́спода твоєго́;","ра́дуйся, усе́рдний о нас предста́телю.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 2","ps":["Ви́дя Христо́с роди́телей твої́х Секу́нда і Анфу́си житіє́ чи́стоє, благоволи́ я просла́вити, і тя, Іоа́нне, і́ма во утіше́ніє дарова́; да ві́рнії, доброді́телі твоя́ помина́юще, превозно́сять чету́ пра́ведную, тя ізрасти́вшую, і, той ревну́юще, пою́ть Бо́гові: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум уче́нієм умудри́вий, се́рдцем же во благоче́стії от мла́дости воспита́нний, ра́дость і утіше́ніє бил єси́, Іоа́нне, ма́тері твоє́й, єгда́ супру́га своєго́ і дще́ре лиши́ся. Ті́мже прино́сим тебі́ хвали́ сицеви́я:","Ра́дуйся, отроко́м звіздо́ благонра́вія;","ра́дуйся, а́нгела храни́теля увеселе́ніє.","Ра́дуйся, я́ко того́ ніколи́же опеча́лил єси́;","ра́дуйся, при́сних люби́миче.","Ра́дуйся, во уче́нії преспіва́вий і тім мудреці́ ми́ра сего́ удиви́вий;","ра́дуйся, я́ко, єще́ учени́к сий, Анфи́мія богоху́льника посрами́л і вразуми́л єси́.","Ра́дуйся, угнете́нних сле́зи го́ркия в суді́х узрі́вий;","ра́дуйся, от творя́щих беззако́нія уклони́вийся.","Ра́дуйся, путі́ незло́бія спаси́тельнаго взиска́вий;","ра́дуйся, по успе́нії ма́тере в пусти́ню заключи́вийся.","Ра́дуйся, та́мо за роди́телі преста́вльшіяся Бо́гові усе́рдно моли́вийся;","ра́дуйся, я́ко ті́ї днесь, со Влади́чицею і святи́ми лику́юще, от земноро́дних велича́ються і хва́ляться.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 3","ps":["Си́ли, во є́же сло́вом і ді́лом Христу́ рабо́тати, стяжа́л єси́, Іоа́нне, а́ки тезоіме́нний ті Предте́ча, в пусти́ні. Та́мо бо, посто́м стра́сті плотські́я умертви́в, моли́твою дух окрили́л єси́ ї, я́ко во́їн, проти́ву кня́зя вла́сті возду́шния во вся ору́жія Бо́жия обле́клся єси́, со упова́нієм поя́ Бо́гу крі́пкому: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я власяни́цю і по́яс усме́н о чре́сліх, Крести́теля Христо́ва ревни́телю, би́лієм пита́лся єси́, Іоа́нне, в пусти́ні, із нея́же, я́ко муж си́ли іспо́лнь, ізше́л єси́. Ті́мже вопіє́м ті:","Ра́дуйся, воздержа́нієм Ілії́ Проро́ку уподо́бивийся;","ра́дуйся, нищети́ Христо́ви подража́телю.","Ра́дуйся, цілому́дрієм неможе́ніє тілесе́ укріпи́вий;","ра́дуйся, богоми́слієм уни́ніє отгна́вий.","Ра́дуйся, па́м'ятію всеві́дінія Бо́жия се́рдце непоро́чно соблюди́й;","ра́дуйся, бді́нієм ко́зні бісо́вськия посрами́вий.","Ра́дуйся, іскуше́нія сам побіди́вий і іни́я посліди́ тому́жде научи́вий;","ра́дуйся, в ді́ланії духо́внім подвиза́ющихся му́дрий укріпи́телю.","Ра́дуйся, дру́га твоєго́ Фео́дора от паде́нія гріхо́внаго удержа́вий;","ра́дуйся, дру́га твоєго́ єпи́скопа Васи́лія во служе́нії утверди́вий.","Ра́дуйся, от ми́ра ізгна́нним приста́нища ти́хаго указа́телю;","ра́дуйся, і́ночеськаго житія́ защи́тниче.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 4","ps":["Бу́рю іскуше́ній но́вую побіди́л єси́, Іоа́нне, в пеще́рі єди́н всели́вся; болі́зні же ра́ди із пусти́ні ізше́д во Антіохі́ю, от свята́го Меле́тія во дия́кона поста́влен бил єси́ і попече́нію о неіму́щих ре́вностно преда́лся єси́. Є́же ви́дяще, ві́рнії ра́достно поя́ху Бо́гові: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шав от ві́рних о тебі́ рі́чі хвале́бния, святи́й Флавія́н по достоя́нію благода́ть свяще́нства низведе́ на тя, Іоа́нне. Ті́мже лю́діє антіохи́йстії веселя́хуся і, труди́ твоя́ пра́ведно чту́ще, та́ко тя велича́ху:","Ра́дуйся, о себі́ попече́ніє вся́коє отве́ргий;","ра́дуйся, убо́гим покро́ве.","Ра́дуйся, те́плоє си́рим прибі́жище;","ра́дуйся, скорбе́й утоли́телю.","Ра́дуйся, о людськи́х неві́жествіїх печа́льниче;","ра́дуйся, ді́вственнаго житія́ сладкогла́сний ублажа́телю.","Ра́дуйся, мно́гі іуде́ї просвіти́вий;","ра́дуйся, іска́вшия спасе́нія пра́вим уче́нієм оглаша́вий.","Ра́дуйся, житіє́м твої́м сего́ уче́нія не посрами́вий;","ра́дуйся, благоче́стія світи́льниче.","Ра́дуйся, апо́столом єдинонра́вниче;","ра́дуйся, я́ко пра́ведно даде́ся ті жре́бій па́стирськаго о душа́х попече́нія.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 5","ps":["Богото́чною кро́вію от ві́чния сме́рти іскупле́нния соблюда́я, єгда́ сан свяще́нства прия́л єси́, Іоа́нне, ді́ло благові́стника трезвя́ся до́брі сотвори́л єси́, облича́я, запреща́я, умоля́я со вся́ким долготерпі́нієм і уче́нієм і поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дя нестроє́нія во гра́ді, скорб'я́ же о сем, поко́я не позна́л єси́, Іоа́нне, неві́рния бо благові́стієм оглаша́л єси́, ві́рния же та́їнстви церко́вними освяща́я і та́йнам ві́ри уча́, досто́йно стяжа́л єси́ і́м'я Злата́я уста́, сли́шав от всіх сицева́я:","Ра́дуйся, па́стирю до́брий;","ра́дуйся, святи́м креще́нієм мно́га ча́да Це́ркві Христо́ві породи́вий.","Ра́дуйся, пома́занієм ми́ра печа́ть да́ра Ду́ха Свята́го тім дарова́вий;","ра́дуйся, святі́йшия Трапе́зи предстоя́телю умиле́нний.","Ра́дуйся, пи́щею нетлі́нія ча́да твоя́ пита́вий;","ра́дуйся, покая́нієм серде́ць очисти́телю.","Ра́дуйся, супру́жеств о Го́споді сочета́телю;","ра́дуйся, єле́я пома́занієм ціли́телю.","Ра́дуйся, сло́ва Бо́жия нело́жний істолкова́телю;","ра́дуйся, єресе́й мо́щний обличи́телю.","Ра́дуйся, глубо́кий кла́дязю і́стиннаго богосло́вія;","ра́дуйся, я́ко притяжа́л єси́ па́стви сердца́, любве́ к тебі́ іспо́лненная.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 6","ps":["Пропові́дник покая́нія найпа́че яви́лся єси́, Іоа́нне, єгда́ лю́діє антіохи́йстії, царя́ подо́біє низве́ргше, гні́ву того́ досто́йно подпадо́ша. Бо́жиїм бо милосе́рдієм утіша́я, ко ісправле́нію житія́ словеси́ твої́ми влекл єси́ вся, во є́же се́рдцем чи́стим пі́ти Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ Антіохи́я ра́достію, єгда́ по словесі́ твоєму́ беззако́нія своя́ опла́кавши, царе́во проще́ніє получи́. Оба́че ско́рбію омрачи́ся вско́рі, с тобо́ю разлуча́єма: во архієпи́скопа бо Царюгра́ду при́зван бил єси́, Іоа́нне. Ті́мже тебе́ вопіє́м:","Ра́дуйся, а́ки Іса́їя, скорбми́ гра́да оте́чеськаго поболі́вий;","ра́дуйся, а́ки Ієреми́я, злонра́віє людсько́є опла́кавий.","Ра́дуйся, а́ки Ієзекі́їль, беззако́нники ко обраще́нію призива́вий;","ра́дуйся, мо́лніє, горди́ню низложи́вшая.","Ра́дуйся, гро́ме, беззако́нно жи́вшия устраши́вий;","ра́дуйся, користолю́бія обличи́телю.","Ра́дуйся, па́губу тщесла́вія показа́вий;","ра́дуйся, сту́днаго е́ллинськаго многобо́жія посрами́телю.","Ра́дуйся, см'яте́нних серде́ць умири́телю;","ра́дуйся, споспі́шниче єпи́скопу Флавія́ну, ста́рцю пра́ведному.","Ра́дуйся, со пустинножи́телі ца́рськия приста́вники на ми́лость преклони́вий;","ра́дуйся, Іо́ні, Ниневі́ю спа́сшему, ра́вний.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 7","ps":["Хотя́ це́рков Царегра́дськую, а́ки неві́сту Христо́ву, досто́йно украси́ти, во благолі́піє вся приве́л єси́, Іоа́нне. Всено́щними бо бді́нії от сбо́рищ арія́нських ві́рния отврати́л єси́ і чин Боже́ственния Литургі́ї му́дре устро́їл єси́, я́ко благово́нноє ми́ро, істочи́в моли́тви, і́миже назида́ющеся, о тебі́ Бо́гові поє́м: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє зна́меніє ми́лости Бо́жия бисть о тебі́, святи́телю: моли́твами бо твої́ми ві́рнії всіх време́н, Бо́гові бесі́дующе, во спасе́ніє умудря́ються. Прийми́ у́бо от нас сицеви́я хвали́:","Ра́дуйся, а́ки Дави́д, словеси́ моли́твенними Це́рков Бо́жию обогати́вий;","ра́дуйся, а́ки брат Бо́жий Іа́ков, чин Боже́ственния Литургі́ї написа́вий.","Ра́дуйся, в то́мже Вели́кому Васи́лію подража́вий;","ра́дуйся, Ду́ха Свята́го прия́телище.","Ра́дуйся, тобо́ю бо Дух Святи́й написа́ словеса́ спаси́тельная;","ра́дуйся, я́ко моли́твами твої́ми, от сна воста́вше, Отця́ благодари́м.","Ра́дуйся, я́ко твої́ми словеси́, ко сну гряду́ще, от Ду́ха Свята́го прегріше́ній оставле́нія про́сим;","ра́дуйся, я́ко усти́ твої́ми Си́на Бо́жия умоля́єм, да не в суд прича́стіє Боже́ственних Та́їн при́ймем.","Ра́дуйся, ра́бе Бо́жий, уничиже́нния на ве́черю Христо́ву глаша́яй;","ра́дуйся, пропові́дниче Расп'я́таго на кресті́ за мирськи́й живо́т і спасе́ніє.","Ра́дуйся, я́ко в сло́во твоє́, а́ки в ри́зи позлаще́ни, та́йни ві́ри оді́яшася;","ра́дуйся, піснотво́рче і виті́я ди́вний.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 8","ps":["Стра́нник во юдо́лі земні́й бив, смире́нія, воздержа́нія і чистоти́ о́браз показа́л єси́, Іоа́нне, житіє́м во ца́рствующем гра́де: та́мо бо оби́телі і́ночеськия обнови́л і созда́л єси́ і уста́ви житія́ мона́шеськаго дал єси́ ді́вам непоро́чним; от ни́хже, а́ки фимія́м благово́нний, вознесе́ся Бо́гові піснь вели́кая: Аллилу́я."]},{"h":"Ікос 8","ps":["Все́ю душе́ю Христо́ві рабо́тая, челові́ком угожда́ти не восхоті́л єси́, Іоа́нне. Імени́тим бо ве́чері устроя́ти преста́в, убо́гим трапе́зи умно́жил єси́, странноприї́мници же і безме́здния враче́бници неду́жним созда́в, научи́л єси́ пі́ти тебі́:","Ра́дуйся, Никола́я, святи́теля Мирлікі́йськаго, соревнова́телю;","ра́дуйся, стяжа́вий смире́нієм висо́кая.","Ра́дуйся, приобріти́й нището́ю бога́тая;","ра́дуйся, си́ми доброді́тельми і́ноком о́браз би́вий.","Ра́дуйся, гла́дних пита́телю;","ра́дуйся, а́ки Авраа́м, стра́нния прийма́вий.","Ра́дуйся, безприю́тних сиро́т прия́телище;","ра́дуйся, безпомо́щних ста́рцев і ста́риць попечи́телю.","Ра́дуйся, ізби́тки своя́ неіму́щим расточи́вий;","ра́дуйся, я́ко коєму́ждо в го́рестіх, а́ки а́нгел уті́шитель, явля́лся єси́.","Ра́дуйся, ру́ки бога́тих на благодія́нія отверза́вий;","ра́дуйся, я́ко о глубині́ милосе́рдія твоєго́ Ма́ти Бо́жия возра́довася.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 9","ps":["Всяк язи́к спасти́ хотя́, пропові́дники Єва́нгелія ко ски́фом, пра́отцем на́шим, посла́л єси́, Іоа́нне, із Константи́на гра́да, в не́мже храм во і́м'я Апо́стола Па́вла созда́л єси́ го́тфом, да і ті́ї, є́ресь а́рієву отве́ргше, правосла́вними усти́ пою́ть Бо́гові: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї правосла́вія к неві́рним посла́в, к це́рквам ві́рних, во Асі́ї су́щим, сам подви́глся єси́, Іоа́нне, і ти́я посіща́я, неради́вия облича́я, усе́рдния же похваля́я, вся смотри́тельні устро́їл єси́. Ті́мже тя сла́вим:","Ра́дуйся, правосла́вія світи́ло;","ра́дуйся, па́стирю до́брий, о заблу́ждших овця́х попеки́йся.","Ра́дуйся, я́ко в землі́ ски́фстій днесь і́м'я твоє́ прославля́ється;","ра́дуйся, я́ко во і́м'я твоє́ це́ркві Бо́жия зді воздвиза́ються.","Ра́дуйся, служе́нія апо́стольськаго прича́стниче;","ра́дуйся, по словесі́ Апо́стола Петра́ ста́до Бо́жиє паси́й.","Ра́дуйся, не ну́ждею, но во́лею і по Бо́зі сіє́ посіща́вий;","ра́дуйся, мздої́мства тве́рдий іскорени́телю.","Ра́дуйся, пра́вил церко́вних нелицеприя́тний блюсти́телю;","ра́дуйся, ліни́вия раби́ пра́ведно ізгна́вий.","Ра́дуйся, я́ко во благо́є труди́вшіїся от тебе́ похвали́шася і укріпи́шася;","ра́дуйся, Це́ркве іспи́танний упра́вителю.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 10","ps":["Спасе́нію па́стви твоєя́ служи́ти не преста́л єси́, Іоа́нне, от Асі́ї в Царгра́д возврати́вся. Єгда́ же цари́ці і імени́тих злонра́вноє житіє́ облича́ти безбоя́зненні нача́л єси́, ско́рбі мно́гі прия́л єси́; тобо́ю бо облича́ємії, не могу́ще а́біє я́ві загради́ти пра́ведная уста́ твоя́, та́йно ко́ви ді́яху, во є́же погуби́ти тя, чи́сті Бо́гові взива́юща: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ неви́нно гони́мим і́ноком яви́лся єси́, Іоа́нне: сего́ ра́ди я́ві обнажи́ся зло́ба ве́лія, ю́же вразі́ на тя імі́яху. Льсти́вий бо Фео́фил со цари́цею нечести́во на собо́рищі оболга́ і низложи́ тя, не пом'яну́в трудо́в твої́х во бла́го оте́чествія. Ми же сія́ благода́рні воспомина́єм, глаго́люще:","Ра́дуйся, ди́вную любо́в ко оте́честву земно́му показа́вий;","ра́дуйся, Царягра́да от ва́рварськаго наше́ствія свободи́телю.","Ра́дуйся, Гаї́ни, гро́знаго вождя́ го́тфськаго, укроти́телю;","ра́дуйся, ми́лостей дре́вніх, Це́ркві царми́ дарова́нних, охрани́телю.","Ра́дуйся, Євтро́пію вла́стному убі́жище церко́вноє от'я́ти не попуска́вий;","ра́дуйся, посліди́ в сем убі́жищі того́жде Євтро́пія гони́ма спаси́й.","Ра́дуйся, огражде́нія ра́ди нитрі́йських і́ноков непра́вди собо́рища беззако́ннаго кро́тці претерпі́вий;","ра́дуйся, я́ко сло́во Писа́нія «люби́ долготерпи́ть», на тебі́ оправда́ся.","Ра́дуйся, ополча́тися за тя при́сним воспрети́вий;","ра́дуйся, меча́ проти́ву враго́в не под'є́мий.","Ра́дуйся, власте́м повину́вийся і сего́ ра́ди во́лею в ру́ки во́їнов но́щію преда́вийся;","ра́дуйся, із оте́чествія пра́вди ра́ди ізгна́нний.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 11","ps":["Пі́нієм ра́достним ізміни́ся вско́рі плач па́стви твоєя́, до́блій страда́льче: во ізгна́ніє бо влеко́му ті, внеза́пу гром возгремі́, мо́лнія возблиста́ і, ві́тром шум'я́щим, земля́ поколеба́ся. Я́же ви́дящи і трепе́щущи, цари́ця раска́яся і че́стне тя возврати́, смире́нно вопію́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́тлую правосла́вія свіщу́, сугу́бо цари́ця возненави́ді тя вско́рі, єгда́ обличи́л єси́ ю, подо́біє своє́ близ хра́ма поста́вльшую: сего́ ра́ди, втори́цею осужде́нний, в Куку́зі, ві́си да́льней і ма́лій, заточе́н бил єси́, Іоа́нне. Прийми́ у́бо от нас сицеви́я хвали́:","Ра́дуйся, по словесі́ Ієремі́їну от ю́ности яре́м Бо́жий под'є́мий;","ра́дуйся, по глаго́лу Христо́ву, ру́ку ді́ланія на ра́ло духо́вноє возложи́вий.","Ра́дуйся, до конця́ всп'ять не отврати́вийся;","ра́дуйся, проти́ву цари́ці злонра́вния возгремі́вий.","Ра́дуйся, то́ю, а́ки Крести́тель Іродия́дою, возненави́дінний;","ра́дуйся, от уби́йць незри́мо а́нгелом спасе́нний.","Ра́дуйся, в дому́ твоє́м любо́вію па́стви твоєя́ храни́мий;","ра́дуйся, клевре́тми непра́ведних суде́й уничиже́нний.","Ра́дуйся, в заточе́ніє со смире́нієм безро́потно ше́дий;","ра́дуйся, ві́рними опла́канний.","Ра́дуйся, за Го́спода расп'я́таго із'язвле́нний і зауше́нний;","ра́дуйся, я́ко му́ченици со Предте́чею на небесі́х о терпі́нії твоє́м ликова́ху.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жия і во ізгна́нії соблюда́ше тя, Іоа́нне, та́мо бо, а́ки Па́вел святи́й во у́зах, финикі́яном і пе́рсом Єва́нгеліє возвіща́л єси́, посла́ньми ві́рния утіша́я. І та́ко упа́сл єси́ Це́рков да́же до дне, во́ньже злата́я уста́ твоя́ ізреко́ша словеса́ послі́дняя: Сла́ва Бо́гу за вся! Душа́ же твоя́ на небеса́ пренесена́ бисть святи́ми А́нгели, побі́дні вопію́щими: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ра́достно, ві́рнії пренесо́ша святи́я мо́щі твоя́, Іоа́нне, в Царгра́д, отню́дуже сла́ва твоя́ про́йде до послі́дніх землі́ і оби́де всю вселе́нную, уча́щи всіх пі́ти тебі́ си́це:","Ра́дуйся, стра́нниче, во оте́чествіє небе́сноє вше́дий;","ра́дуйся, всіх церкве́й моли́твами напу́тствованний.","Ра́дуйся, на путі́ в Пифіу́нт да́льній в Кома́ніх тече́ніє сконча́вий;","ра́дуйся, я́ко кончи́ну ті предрече́ священному́ченик Васили́ск.","Ра́дуйся, от сего́ усли́шавий: Бра́те, зау́тра ку́пно обря́щемся;","ра́дуйся, Святи́х Та́їн прия́тієм к восхожде́нію в рай укріпи́вийся.","Ра́дуйся, я́ко душа́ твоя́ от многотру́днаго тілесе́ ти́хо разлучи́ся;","ра́дуйся, я́ко тлі́ніє не прикосну́ся косте́м твої́м.","Ра́дуйся, я́ко на сих во хра́міх Же́ртва Безкро́вная днесь возно́ситься;","ра́дуйся, небе́сних висо́т обита́телю, сві́том невече́рнім осія́нний.","Ра́дуйся, я́ко со святи́ми Васи́лієм Вели́ким і Григо́рієм Богосло́вом я́влься, восхваля́ти тя ку́пно со о́німи вся научи́л єси́;","ра́дуйся, сла́во Це́ркве вселе́нськия.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 13","ps":["О святи́телю вели́кий Іоа́нне Златоу́сте! При́зри с небе́сних висо́т на ни, до́лу пове́рженния, і приє́м сіє́ от любве́ на́шея приноси́моє ті хвале́ніє, умоли́ Го́спода Бо́га, да ізліє́ть на ни благода́ть Свою́, немощна́я врачу́ющую, су́щия во правосла́вії укріпи́ть, отпа́дшия же от Це́ркве па́ки в ло́но тоя́ приведе́ть, благоутро́бієм Свої́м оскудіва́ющая восполня́я, і всіх сподо́бит с тобо́ю і всі́ми святи́ми пі́ти Єму́ во ві́ки: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгельський о́браз нося́, во пло́ті а́ки безпло́тен пожи́л єси́, Іоа́нне; во спасе́ніє бо бра́тій мно́гія труди́ под'є́мля, ді́ли до́брими Отця́ Небе́снаго просла́вил єси́. Ті́мже ті глаго́лем:","Ра́дуйся, Це́ркве Правосла́вния украше́ніє;","ра́дуйся, роди́телей імени́тих ча́до благослове́нноє.","Ра́дуйся, єще́ во о́трочестві от ма́тере твоєя́ любо́вію ко сло́ву Бо́жию напоє́нний;","ра́дуйся, от ю́ности ра́зум і́гу Христо́ву покори́вий.","Ра́дуйся, Бо́гові усе́рдно послужи́вий;","ра́дуйся, вселе́нния учи́телю.","Ра́дуйся, христия́н всіх време́н в моли́твах наста́вниче;","ра́дуйся, житія́ і́ночеськаго в Царегра́ді обнови́телю.","Ра́дуйся, го́тфов і ски́фов просвіти́телю;","ра́дуйся, богоукріпле́нний пра́вди ревни́телю.","Ра́дуйся, вше́дий в ра́дость Го́спода твоєго́;","ра́дуйся, усе́рдний о нас предста́телю.","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Кондак 1","ps":["Возбра́нний вождю́ Це́ркве Христо́ви, златослове́сний учи́телю Іоа́нне! От ю́ности доброді́тельми украси́вся, до́брі потруди́лся єси́, і за і́м'я Христо́во гоне́ніє претерпі́в, во ізгна́нії житіє́ сконча́л єси́: сего́ ра́ди на небесі́х сугу́бо просла́влен єси́, му́дрий чи́на Церко́внаго устрої́телю. Ті́мже і ми умиле́нні чтим тя, зову́ще:","Ра́дуйся, святи́телю вели́кий Іоа́нне Златоу́сте."]},{"h":"Молитва","ps":["О святи́телю вели́кий Іоа́нне Златоу́сте! Мно́гая і разли́чная дарова́нія от Го́спода прия́л єси́ ї, я́ко раб благи́й і ві́рний, вся да́нния тебі́ тала́нти до́брі умно́жил єси́: сего́ ра́ди воі́стину вселе́нський учи́тель бил єси́, я́ко всяк во́зраст і вся́ко зва́ніє от тебе́ поуча́ється. Ти єси́ отроко́м – послуша́нія о́браз, ю́ним – цілому́дрія світи́ло, муже́м – трудолю́бія наста́вник, ста́рим – незло́бія учи́тель, і́ноком – воздержа́нія пра́вило, моля́щимся – вождь от Бо́га вдохнове́нний, му́дрости і́щущим – ума́ просвіти́тель, виті́ям доброглаго́ливим – сло́ва жива́го істо́чник неісчерпа́ємий, благотворя́щим – милосе́рдія звізда́, нача́льствующим – правле́нія му́драго о́браз, пра́вди ревни́телем – дерзнове́нія вдохнови́тель, пра́вди ра́ди гони́мим – терпі́нія наста́вник: всім вся бил єси́, да вся́ко ні́кия спасе́ши. Над всі́ми же си́ми стяжа́л єси́ любо́в, я́же єсть соу́з соверше́нства, і то́ю, я́ко си́лою Боже́ственною, вся дарова́нія во єди́нім лице́ твоє́м во єди́но совокупи́л єси́ і ту́южде любо́в, разділе́нная примиря́ющую, в толкова́нії слове́с апо́стольських всім ві́рним пропові́дал єси́. Ми же грі́шнії, по єди́ному ки́йждо своє́ дарова́ніє іму́ще, єдине́нія ду́ха в сою́зі ми́ра не і́мами, бива́єм тщесла́вни, друг дру́га раздража́юще, друг дру́гу зави́дяще; сего́ ра́ди дарова́нія на́ша разділе́нная не в мир і спасе́ніє, но во вражду́ і осужде́ніє нам явля́ються. Ті́мже к тебі́, святи́телю Бо́жий, припа́даєм, раздо́ром обурева́ємі, і в сокруше́нії се́рдця про́сим: моли́твами твої́ми отжени́ от серде́ць на́ших вся́ку го́рдость і за́висть, нас разділя́ющия, да во мно́зіх у́діх єди́но ті́ло церко́вноє бу́дем, да по словесі́ твоєму́ моли́твенному возлю́бим друг дру́га і єдиноми́слієм іспові́ми Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 8","ps":["Уст твої́х я́коже сві́тлость огня́ возсія́вши благода́ть, / вселе́нную просвіти́: / не сребролю́бія ми́рові сокро́вища сниска́, / висоту́ нам смиренному́дрія показа́. / Но твої́ми словеси́ наказу́я, о́тче Іоа́нне Златоу́сте, // моли́ Сло́ва Христа́ Бо́га спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 6","ps":["От Небе́с прия́л єси́ Боже́ственную благода́ть / і твої́ми устна́ми вся учи́ши / покланя́тися в Тро́йці єди́ному Бо́гу, / Іоа́нне Златоу́сте, всеблаже́нне преподо́бне, / досто́йно хва́лим тя: // єси́ бо наста́вник, я́ко Боже́ственная явля́я."]},{"h":"Величання","ps":["Велича́єм тя, святи́телю о́тче Іоа́нне, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святим мученицям Вірі, Надії, Любові і матері їхній Софії","e":"Akathist to the Holy Martyrs Faith, Hope, Love and their mother Sophia","secs":[{"h":"Кондак 1","ps":["Ізбра́нним раба́м Го́спода Вседержи́теля, Ві́рі, Наде́жде і Любві́, і му́дрій ма́тері Софі́ї, похва́льная вам пі́нія умиле́нно возно́сим. Ви же, я́ко дерзнове́ніє ко Христу́ Бо́гу іму́ще, моли́тися за ни, во є́же ізба́витися нам гріхо́в і скорбе́й, да благода́рственно вопіє́м вам:","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Ікос 1","ps":["А́нгели на Небесі́ ра́довахуся, доброді́тельноє житіє́ ва́ше зря́ще, є́же провожда́сті в чте́нії Писа́ній Боже́ственних, в труді́х, по́сте, моли́тві і ми́лостині, ма́терію ва́шею непреста́нно су́щи поуча́ємі, да явіте́ся о́бразі живі́ї тріє́х богосло́вських доброді́телей, ї́хже імена́ми наречени́ би́сте. Ми же, такові́й му́дрости ма́тере ва́шея і соверше́нному благоразу́мію ва́шему див'я́щеся, благогові́йно рцем вам:","Ра́дуйтеся, єдиноми́сленния сестри́, тріє́м доброді́телем тезоімени́тия;","ра́дуйтеся, в повинове́нії богому́дрій ма́тері ва́шей на сте́пені соверше́нствованія вше́дшия.","Ра́дуйтеся, а́ки три ра́йськия ві́тві, в злове́рнем Ри́мі возра́сшия;","ра́дуйся, Софі́є, дще́рем твої́м імена́ доброді́телей наре́кшая, я́же ве́щію ісполня́ти научи́ла єси́.","Ра́дуйся, Ві́ро, ві́рою неви́димоє, я́ко ви́димоє, зрі́ти нам помога́ющая;","ра́дуйся, в нетлі́ніє облече́нная.","Ра́дуйся, Наде́ждо, наде́ждою страда́нія на́ша во юдо́лі ско́рби ослабля́ющая і в го́рняя десни́цею указу́ющая;","ра́дуйся, Ца́рствіє Небе́сноє унаслі́довавшая.","Ра́дуйся, Люби́, любо́вію Боже́ственною блаже́нство безсме́ртния жи́зні нам открива́ющая;","ра́дуйся, благода́тію Ду́ха Свята́го осія́нная.","Ра́дуйся, Софі́є, сі́єсть прему́дрость, прему́дре дще́ри твоя́ воспита́вшая;","ра́дуйся, в доброді́теліх ві́ри, наде́жди і любве́ нас утвержда́ющая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 2","ps":["Ви́дящи му́драя Софі́я слуги́, прише́дша зва́ти ю со дще́рми ко царю́ Адрія́ну, і позна́вши вину́ призва́нія своєго́, ста со ча́ди свої́ми на моли́тву, по́мощі Бо́га прося́щи. По моли́тві же, є́мшеся за ру́ці, я́коже віне́ць уплете́нний, ідя́ху вку́пі, пою́ще Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум несумне́нний імі́ли єсте́, святи́я, єгда́ бо в пала́ти ца́рськия введени́ би́сте, царе́ві Адрія́ну предста́сте с лице́м сві́тлим, очеси́ весе́лими і се́рдцем му́жественним. Цар же, зря честна́я лиця́ ва́ша неустраше́нна і му́дрость Софі́ї уві́дів, отложи́ на і́но вре́м'я суд свой і отсла́ ви к ні́коєй благоро́дней жені́, у нея́же преби́сте три дні, ма́тері ва́шей прему́дрей богодухнове́нними словеси́ день і нощ вас поуча́ющей. Ті́мже ублажа́юще вас, взива́єм си́це:","Ра́дуйтеся, три непоро́чния а́гници Христо́ви, віне́ць доброді́телей в себі́ совокупи́вшия;","ра́дуйтеся, три доброді́тельния сестри́, тве́рдую ві́ру, несумні́нную наде́жду і нелицемі́рную любо́в ко Го́споду Бо́гу яви́вшия.","Ра́дуйтеся, не пощади́вшия красоти́ і мла́дости ва́шея, Красні́йшаго ра́ди добро́тою па́че сино́в челові́чеських;","ра́дуйся, Софі́є, ча́да твоя́ возлю́бленная на по́двиг му́ченичеський за Христа́ наставля́вшая.","Ра́дуйся, Ві́ро, муче́нієм за Христа́ ві́ру твою́ іспові́давшая;","ра́дуйся, сестри́ твоя́ крі́пкою ві́рою воздвиза́вшая.","Ра́дуйся, Наде́ждо, тве́рдоє наді́яніє на Христа́ возлага́вшая;","ра́дуйся, сестри́ твоя́ неосла́бною наде́ждою укрепля́вшая.","Ра́дуйся, Люби́, му́ками за Христа́ любо́в твою́ де́йственную показа́вшая;","ра́дуйся, сестри́ твоя́ огне́м любве́ огражда́вшая.","Ра́дуйся, Софі́є, сла́дкая ча́да твоя́ увещава́вшая презрі́ти сла́ву і бога́тство і всю сла́дость ми́ра сего́ тлі́ннаго;","ра́дуйся, до́брия дще́ри твоя́ до кро́ве ста́ти за Го́спода і умре́ти за Него́ усе́рдно учи́вшая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 3","ps":["Си́лою Боже́ственною осенени́ бя́ху му́ченици, я́же доброді́телі іме́н свої́х яви́ша ді́лом в по́двизіх му́ченичеських, воспіва́юще Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще в себі́ святи́я му́ченици столп ві́ри, крилі́ наде́жди і огнь любве́, в сла́дость послу́шающия от слове́с ма́тере своєя́, єди́на другу́ю в долготерпі́нії утвержда́ху і ра́достно ідя́ху, жела́юще честна́го му́ченичества, є́же за Христа́. Тому́ покланя́ющеся, я́ко Бо́гу на́шему, сицеви́ми вас воззва́ньми почита́єм:","Ра́дуйтеся, ні ма́ло не поскорбе́вшия о лише́нії вре́меннаго сего́ живота́ ві́чния ра́ди жи́зні;","ра́дуйтеся, че́сти ра́ди Христо́ви плоть на му́ки преда́вшия.","Ра́дуйтеся, три многоці́нния сосу́ди ві́ри, наде́жди і любве́ Бо́гу в дар прине́сшия;","ра́дуйся, Софі́є, я́ко, любве́ ра́ди презе́льния ко дще́рям твої́м, всім се́рдцем возжелі́ла єси́, да Ца́рствіє Бо́жиє наслі́дують.","Ра́дуйся, Ві́ро, ду́ші на́ша ві́рою озаря́ющая;","ра́дуйся, к ти́хому приста́нищу нас вознося́щая.","Ра́дуйся, Наде́ждо, сердця́ на́ша сла́достію наде́жди оживля́ющая;","ра́дуйся, із пучи́ни отча́янія нас ізвлека́ющая.","Ра́дуйся, Люби́, страда́нія і ско́рби на́ша в ра́дость прелага́ющая;","ра́дуйся, окамене́нная сердця́ на́ша во умиле́ніє преводя́щая.","Ра́дуйся, Софі́є, му́дростію на благо́є нас наставля́ющая;","ра́дуйся, потемне́нноє о́ко душ на́ших просвіща́ющая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 4","ps":["Бу́ря я́рости мучи́телеви нападе́ на тя, свята́я Ві́ро, но не поколеба́ тя. Кто бо возмо́жеть ві́ру неодоли́мую подви́гнути, адама́нта крепча́йшую, я́же ві́рних научи́ла єсть пі́ти с тобо́ю Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шащи му́драя ма́ти дще́ри своя́ пред царе́м небоя́зненно Христа́ іспове́дающия і глаго́лющия, я́ко того́ єди́наго жела́ють, є́же би страда́ти і терпі́ти го́ркия му́ки сла́дкаго ра́ди Ісу́са Христа́, ра́довашеся вельми́ і моля́ше Бо́га, да укріпи́ть я в предлежа́щих му́ках. Сіє́ у́бо ізволе́ніє похваля́юще, пе́рвійшей дще́ри му́дрия ма́тере та́ко воспоє́м:","Ра́дуйся, Ві́ро, немилосе́рдая біє́нія Сладча́йшаго ра́ди Ісу́са сла́дці приє́мшая;","ра́дуйся, уре́занная сосця́ твоя́, а́ки два кри́на чистоти́, в же́ртву Го́споду прине́сшая.","Ра́дуйся, я́ко от я́зви твоєя́ вмі́сто кро́ве млеко́ істече́;","ра́дуйся, я́ко на раскале́нноі желі́зо положе́на била́ єси́.","Ра́дуйся, я́ко в коно́б кип'я́щ вве́ржена су́щи, ні ма́ло не опали́лася єси́, ніже́ вреди́лася єси́;","ра́дуйся, пла́мень страсте́й на́ших небе́сною прохла́дою утиша́ющая.","Ра́дуйся, огнь муче́ній на́ших в болі́зніх угаша́ющая;","ра́дуйся, зна́менієм ві́ри посреді́ напа́стей нас зна́менающая.","Ра́дуйся, щито́м ві́ри во бра́ні со враго́м нас покрива́ющая;","ра́дуйся, честну́ю главу́ твою́ за Главу́ Це́ркве, Христа́ Бо́га, под меч ра́достно прекло́ншая.","Ра́дуйся, я́ко обагре́нієм кро́ве твоєя́, а́ки червлени́цею оді́яна, яви́лася єси́ очесе́м Безсме́ртнаго Жениха́ твоєго́;","ра́дуйся, к жела́нному кра́ю прише́дшая і люби́маго Спа́са і Го́спода узре́вшая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 5","ps":["Богозда́нним звізда́м уподо́билися єсте́, Ві́ро, Наде́ждо і Люби́, всім бо се́рдцем прилепи́вшіяся ко єди́ному ві́чному Животу́ і Красоті́ неізрече́нній, Ісу́су Христу́, ско́ро ше́ствовасте, во є́же умре́ти за Него́ і наслади́тися Боже́ственнаго Єго́ виді́нія, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше добропобі́дния сестри́ святу́ю Ві́ру ра́достно за Христа́ пострада́вшу, і са́мі хотя́ху ду́ші своя́ за Него́ положи́ти: цар же Наде́жду святу́ю нача́ть іспи́товати, і ви́дів ю с сестро́ю єдиноми́сленну су́щу, на му́ки вдаде́ ю, оба́че нічто́же у́спе. Ми же, Наде́жду святу́ю о сицево́м єя́ мудрова́нії ублажа́юще, воспої́м і просла́вим ю:","Ра́дуйся, Наде́ждо, жесто́ко біє́нная, оба́че пресві́тлую наде́жду на Го́спода не потеря́вшая;","ра́дуйся, му́ки твоя́ безро́потно в молча́нії терпе́вшая.","Ра́дуйся, і нам крі́пкоє терпі́ніє подаю́щая;","ра́дуйся, я́ко в разжже́нній пещі́ неопаля́єма би́вши, хвалу́ Бо́гу возсила́ла єси́.","Ра́дуйся, я́ко і нас во страда́ніїх хвали́ти Бо́га науча́єши;","ра́дуйся, я́ко ногтьми́ желі́зними стро́гана била́ єси́.","Ра́дуйся, нас, су́щих в ско́рбіх, луча́ми наде́жди осіява́ющая;","ра́дуйся, я́ко чу́дноє ні́коє благоуха́ніє от язв твої́х ісхожда́ше.","Ра́дуйся, непоколеби́моє упова́ніє на Го́спода Ісу́са неізмі́нно сохра́ншая;","ра́дуйся, безнаде́жность і безси́ліє в сердця́х на́ших істребля́ющая.","Ра́дуйся, ме́чноє посіче́ніє за Христа́ ра́достно приі́мшая;","ра́дуйся, я́сная денни́це, нам, печа́льми земни́ми угнете́нним, мир ві́чний раскрива́ющая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 6","ps":["Пропові́дником і апо́столом богоно́сним подо́бни би́сте, богому́дрия сестри́: доброді́тельми бо ва́шими пропові́дасте всім ві́рним ві́ру, наде́жду і любо́в ко Го́споду, Влади́ці всіх, Тому́ пою́ще: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єси́, а́ки со́лнце, Люби́ свята́я, кто бо си́це за возлю́бленнаго Го́спода своєго́ можа́ше ста́ти, я́коже люби́, поне́же пи́сано єсть: «Кріпка́ я́ко смерть люби́, вода́ мно́га не мо́жеть угаси́ти любве́, і рі́ки не потоп'я́т єя́». Мо́лим ті ся ни́ні, Люби́ свята́я, серафи́мським пла́менем любве́ ко Го́споду горя́щая, обнови́ окамене́нная і ізсо́хшая сердця́ на́ша, возжги́ в нас, оскуде́вших любо́вію, світ любве́, да возлю́бльше Го́спода і вся бли́жнія на́ша, тебі́ я́ко моли́твенницю на́шу, восхва́лим си́це:","Ра́дуйся, Люби́, я́ко любве́ твоєя́ ко Христу́ води́ мно́гі пре́лестей мирськи́х не угаси́ша;","ра́дуйся, я́ко вся ласка́нія і да́ри царе́ви отве́ргши, ду́шу твою́ за Го́спода положи́ла єси́.","Ра́дуйся, я́ко любве́ твоєя́ рі́ки бід і страда́ній не потопи́ша;","ра́дуйся, за Го́спода Ісу́са на колеси́ протя́гнутая, же́злієм біє́нная, све́рдлами прободе́нная і в пещ о́гненную вве́рженная.","Ра́дуйся, я́ко в лю́тих му́ках твої́х си́лою Бо́жиєю укріпля́єма била́ єси́;","ра́дуйся, кро́вію твоє́ю, любве́ ра́ди к Безсме́ртному Жениху́ твоєму́ Христу́ ізлія́нною, в хла́дних сердця́х на́ших любо́во возбужда́ющая.","Ра́дуйся, я́ві показа́вшая нам, я́ко любве́ ра́ди вся муче́нія сла́дці претерпева́ються;","ра́дуйся, яви́вшая нам, я́ко люби́ Боже́ственная приво́дить к животу́ ві́чному.","Ра́дуйся, са́мою ве́щію уві́рившая, я́ко люби́ Боже́ственная открове́ніє єсть безсме́ртія;","ра́дуйся, я́ко ніка́яже мучи́тельства возмого́ша разлучи́ти Любо́в от любве́ Христо́ви.","Ра́дуйся, в му́ках апо́стольськи веща́вшая, я́ко не разлучи́ть тя от любве́ Бо́жия ні скорб, ні тіснота́, ні гоне́ніє, ні глад, ні нагота́, ні біда́, ні меч;","ра́дуйся, любве́ ра́ди Христо́ви мече́м во главу́ усече́нная.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 7","ps":["Хотя́ще скорі́є от ті́ла разлучи́тися і со Христо́м би́ти, святи́я ді́ви, єгда́ на ме́чноє посіче́ніє ідя́ху, єди́на другу́ю і ма́тер свою́ Софі́ю об'є́млюще лобиза́хуся, дру́жеському нас любле́нію поуча́юще, да всі ку́пно поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до показа́ Госпо́дь, єгда́ по́мощ Свою́ посла́ страда́вшим за іспові́даніє і́мене Єго́ толи́ко ю́ним ді́вам: ві́рою бо, наде́ждою і любо́вію укріпля́єми і возноси́ми би́вше, до́блественне по́двиги своя́ сконча́ша. Ми же в єдиноми́слії і єдиноду́шії до конця́ живота́ преби́вших мо́лим вас, да і нам низпо́слете єдиноми́сліє в соверше́нії до́брих діл, умиле́нно велича́ющим вас:","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, єди́нім путе́м муче́ній до врат небе́сних ше́дшия;","ра́дуйтеся, в пресві́тлий черто́г прелюбе́знаго Жениха́ ва́шего во гла́сі ра́дованія вше́дшия.","Ра́дуйтеся, я́ко Ісу́с Христо́с просвіти́, я́коже зві́зди на небесі́, ра́ни на тілесі́х ва́ших;","ра́дуйся, Софі́є, до́блественне на му́ки чад твої́х взира́вшая.","Ра́дуйтеся, я́ко небе́сною красото́ю, єя́же о́ко не ви́ді, украси́ Госпо́дь добро́ту ва́шу, му́ками от'я́тую;","ра́дуйтеся, вінці́ воздая́нія приє́мшія.","Ра́дуйтеся, а́ки три звізди́, Со́лнцем пра́вди озаре́нния;","ра́дуйся, Софі́є, в му́жественнім іспові́данії дще́рми твої́ми і́мене Христо́ва утіше́ніє ве́ліє обрі́тшая.","Ра́дуйтеся, мглу сомні́ній на́ших разсеява́ющия;","ра́дуйтеся, нас удруче́нних страда́ньми душе́вними і тіле́сними, подкрепля́ющия.","Ра́дуйтеся, красото́ю любве́ сердця́ на́ша украша́ющия;","ра́дуйся, Софі́є, крі́посте і утіше́ніє ізнемога́ющих в біда́х і ну́ждах.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 8","ps":["Стра́нноє і непоня́тноє нам немощни́м, в мирськи́х сластеіх погря́знувшим, зрим ді́ло, я́ко Софі́я свята́я, возлю́бленних чад свої́х ви́дящи лю́тия і го́ркия му́ки і сме́рті, ні ма́ло не поскорбе́, но возра́довася зіло́ ду́хом, пою́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся бі во ви́шніх му́драя Софі́я, єгда́ дще́ри своя́ сла́дкими словеси́ і му́дрими увеща́ньми на муче́нія подвиза́ше. А́ще же от єстества́ к слеза́м преклоня́шеся а́біє, от любве́ Христо́ви прелага́шеся на ра́дость, печа́ль бо серде́чную і болі́знь о ча́діх ма́тернюю побіди́ в ней люби́ Бо́жия. Ве́лією у́бо любо́вію дще́ри своя́ лю́б'ящи, па́че всего́ тім Ца́рствія Небе́снаго жела́ше. Сего́ ра́ди, чудя́щеся му́дрості і вели́цій любві́ твоє́й ко дще́рем і сла́в'яще тя, взива́єм:","Ра́дуйся, Софі́є, я́ко возвесели́ся душа́ твоя́ о блаже́нній кончи́ні дще́рей твої́х, свято́є і́м'я Го́спода дерзнове́нно іспові́давших;","ра́дуйся, в му́ченичестім вінча́нії чад твої́х честь і сла́ву прия́вшая.","Ра́дуйся, уча́стія му́ченичеськаго і спребива́нія со дще́рми в небе́сній сла́ві Христа́ Бо́га сподо́бльшаяся;","ра́дуйся, честна́я тілеса́ дще́рей твої́х с ра́достними слеза́ми погре́бшая.","Ра́дуйся, три дні гро́бу їх приседе́вшая і сном сме́рти о Го́споді почи́вшая;","ра́дуйся, а́ще і не пло́тію, оба́че се́рдцем за Христа́ страда́вшая.","Ра́дуйся, я́ко три доброді́тельния дще́ри, си́ми ві́ру, наде́жду, любо́в к Бо́гу яви́вши, в дар Пресвяті́й Тро́йце принесла́ єси́;","ра́дуйся, я́ко чадоро́дія ра́ди спасла́ся єси́.","Ра́дуйся, ди́вная ма́ти, благи́я па́м'яті досто́йная;","ра́дуйся, дще́ри твоя́, да кров свою́ за Христа́ пролію́ть, моли́вшая.","Ра́дуйся, умудря́ющая ни, да блюде́м непрело́жно доброді́телі ві́ри, наде́жди і любве́;","ра́дуйся, Животворя́щей Тро́йці за ни моля́щаяся.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 9","ps":["Всі А́нгели дивля́хуся о страда́ніїх ва́ших, святи́я му́ченици, і побі́ду ва́шу над дия́волом торжеству́юще, ду́ші же ва́ша к Небесі́ провожда́юще, воспіва́ху Христу́ Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї велере́чивії вся страда́нія ва́ша за Христа́ не возмо́гуть ізрещи́, див'я́щеся же толи́ким подвиго́м, во млади́х лі́тіх под'я́тим, немо́тствують. Ми же о честні́й кончи́ні ва́шей Бо́га прославля́юще, велича́єм вас си́це:","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, пою́щия хвалу́ Бо́гу, на не́бо небесе́ возше́дшему;","ра́дуйтеся, щі́те ві́ри, броне́ наде́жди і світи́льниче любве́.","Ра́дуйтеся, зрі́нієм пресві́тлаго лиця́ Бо́жия наслажда́ющіяся;","ра́дуйся, Софі́є, благочести́вия ма́тері на му́дроє воспита́ніє чад їх наставля́ющая.","Ра́дуйтеся, поуча́ющия ни, да взи́щем Го́спода, і жи́ва бу́деть душа́ на́ша;","ра́дуйтеся, с ві́рою, наде́ждою і любо́вію прибіга́ющих к вам те́плия моли́твенниці.","Ра́дуйтеся, вразумля́ющия ни, я́ко вся сла́дость і пре́лесть ми́ра сего́ я́ко дим ізчеза́єть, я́ко прах от ві́тра размета́ється і в персть обраща́ється;","ра́дуйся, Софі́є, всім се́рдцем Го́спода Бо́га возлю́бльшая.","Ра́дуйтеся, а́ки тріє́ сві́тлії ключи́, ко єди́ному Істо́чнику жи́зні прите́кшії;","ра́дуйтеся, а́ки тріє́ благово́ннії цві́ти, на єди́ній благопло́дней ві́тві прозя́бшії.","Ра́дуйтеся, а́ки три зерца́ла, безпреде́льную красоту́ Бо́жию в себі́ отража́ющая;","ра́дуйся, Софі́є, а́ки ма́слина, три ві́тві, отягче́нния ізоби́льними плоди́ даро́в Бо́жиїх, проізра́стшая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ще ду́ші своя́ святи́я му́ченици, любве́ ра́ди Христо́ви ласка́нія царе́ва і бога́тства ми́ра сего́ тлі́ннаго презрі́ша і ра́достно кончи́ну му́ченичеськую за Христа́ прия́ша, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ми ві́ри, наде́жди і любве́ явля́ються святи́я му́ченици всім, прибега́ющим к ним с те́плою і усе́рдною моли́твою і си́це в печа́ліх і напа́стіх к ним взива́ющим:","Ра́дуйтеся, язв гріхо́вних до́брия цели́тельници;","ра́дуйтеся, во тьмі печа́лі на́шея сві́том упова́нія ни озаря́ющия.","Ра́дуйтеся, посреді́ напа́стей і скорбе́й ди́вний поко́й нам посила́ющия;","ра́дуйся, Софі́є, о нас, в злострада́ніїх пове́рженних, му́дроє попече́ніє явля́ющая.","Ра́дуйся, Ві́ро, крест спасе́нія пред на́ми воздвиза́ющая;","ра́дуйся, не́мощі на́ша по моли́твам к тебі́ ізцеля́ющая.","Ра́дуйся, Наде́ждо, я́кор ізбавле́нія нам подаю́щая;","ра́дуйся, уни́ніє серде́ць на́ших бла́гостно от'є́млющая.","Ра́дуйся, Люби́, твої́м ко Го́споду хода́тайством в злій напа́сти от неча́янния сме́рті ни огражда́ющая;","ра́дуйся, ізнемога́ющия си́ли на́ша на бо́дрость возставля́ющая.","Ра́дуйся, Софі́є, прилі́жная о нас к Бо́гу моли́твеннице;","ра́дуйся, в до́бріх ді́ліх на́ших му́драя наста́внице.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 11","ps":["Пі́ніє сіє́ похва́льноє, а́ще би і тьмочи́сленноє приноша́хом вам, святи́я му́ченици, не би довлі́ло ко прославле́нію доброді́телей і по́двигов ва́ших. Оба́че хвалу́ Бо́гу возсила́юще за вся, я́же во святи́х Свої́х нам явля́єть, Тому́ поє́м: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том небе́сним пред Го́сподем горя́щим свіща́м подо́бни Ві́ра, Наде́жда і Люби́, ку́пно с ма́терію їх Софі́єю, к ни́мже припа́даєм, моля́ще, да просвітя́ть ни, омраче́нния печа́льми і із глубини́ серде́ць зову́щия:","Ра́дуйтеся, ри́зи ва́ша в кро́ві А́гнчей на землі́ убели́вшия;","ра́дуйтеся, живота́ ві́чнаго нам хода́тайці.","Ра́дуйтеся, душ, і́щущих поко́я в милосе́рдії Бо́жії, утвержде́ніє і хране́ніє;","ра́дуйся, Софі́є, от суєти́ мирськи́я ни огражда́ющая.","Ра́дуйся, Ві́ро, доброце́нная кади́льнице, фиміа́м хвали́ Бо́гу вознося́щая;","ра́дуйся, нас грі́шних ві́рою просвіща́ющая.","Ра́дуйся, Наде́ждо, в ско́рбі утіше́ніє і прибі́жище на́ше;","ра́дуйся, в печа́ліх на́ших лучеза́рная ве́стнице ізбавле́нія.","Ра́дуйся, Люби́, незло́біє і кро́тость в сердця́ на́ша влива́ющая;","ра́дуйся, та́їнственная звіздо́, от тісноти́ земни́я го́ре ни вознося́щая.","Ра́дуйся, Софі́є, му́драя і пречестна́я детоводи́тельнице;","ра́дуйся, богому́драго житія́ моля́щимся ті устрої́тельнице.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 12","ps":["Благода́ть Бо́жию прия́ти сподо́бившіяся, молі́те о нас, святи́я му́ченици, Пречи́стаго Влади́ку Христа́, да ми́лостив бу́деть к нам грі́шним, с ві́рою, наде́ждою і любо́вію Єму́ Єди́ному, Го́споду і Спа́су на́шему, смире́нно пою́щим: Аллилу́я."]},{"h":"Ікос 12","ps":["Поє́м ва́ша крі́пкия по́двиги, ві́рою, наде́ждею і любо́вію проникнове́нния, почита́єм страда́нія ва́ша презе́льная, хва́лим ди́вноє терпі́ніє ва́ше, ублажа́єм кончи́ну, за Христа́ ва́ми ра́достно под'я́тую, велича́єм необори́моє му́жество ва́ше, святи́я му́ченици Ві́ро, Наде́ждо і Люби́, і му́драя ма́ти Софі́є, і прославля́юще вас, взива́єм си́це:","Ра́дуйтеся, а́ки три струї́ мо́лніїни, от восто́к да́же до за́пад доброді́тельми свої́ми просія́вшия;","ра́дуйтеся, фія́ли ві́ри, наде́жди і любве́, животво́рним питіє́м ду́ші на́ша напая́ющії.","Ра́дуйтеся, тріє́ світоза́рнії путіє́, ко престо́лу сла́ви Госпо́дні нас веду́щії;","ра́дуйся, Софі́є, чад ра́ди твої́х от ли́ка святи́х похвале́нная.","Ра́дуйся, Ві́ро, цві́те ві́ри, па́че сні́га беле́йший;","ра́дуйся, услажде́ніє стра́ждущих.","Ра́дуйся, Наде́ждо, угнете́нних серде́ць возноше́ніє;","ра́дуйся, а́ки пото́к цільбоно́сний, жа́жду скорб'я́щих душ утоля́ющая.","Ра́дуйся, Люби́, ві́нче із ми́ра, ра́дованія і бла́гости соплете́нний;","ра́дуйся, у́мная зарни́це ві́чності.","Ра́дуйся, Софі́є, же́зле си́ли, кро́тці і му́дре ча́да наказу́яй;","ра́дуйся, богові́дінія пресві́тлая луче́, душа́м на́шим возсіява́ющая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 13","ps":["О святи́я і достохва́льния му́ченици Ві́ро, Наде́ждо і Люби́, і му́драя ма́ти Софі́є, ни́ні приє́мше ма́лоє сіє́ моле́ніє на́ше, от вся́ких ни бід, болі́зней і скорбе́й моли́твами ва́шими ізба́віте, да сподо́бльшеся во Ца́рствії Небе́снім зрі́ти безсме́ртнаго Го́спода Ісу́са, с ва́ми вку́пі воспоє́м Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели на Небесі́ ра́довахуся, доброді́тельноє житіє́ ва́ше зря́ще, є́же провожда́сті в чте́нії Писа́ній Боже́ственних, в труді́х, по́сте, моли́тві і ми́лостині, ма́терію ва́шею непреста́нно су́щи поуча́ємі, да явіте́ся о́бразі живі́ї тріє́х богосло́вських доброді́телей, ї́хже імена́ми наречени́ би́сте. Ми же, такові́й му́дрости ма́тере ва́шея і соверше́нному благоразу́мію ва́шему див'я́щеся, благогові́йно рцем вам:","Ра́дуйтеся, єдиноми́сленния сестри́, тріє́м доброді́телем тезоімени́тия;","ра́дуйтеся, в повинове́нії богому́дрій ма́тері ва́шей на сте́пені соверше́нствованія вше́дшия.","Ра́дуйтеся, а́ки три ра́йськия ві́тві, в злове́рнем Ри́мі возра́сшия;","ра́дуйся, Софі́є, дще́рем твої́м імена́ доброді́телей наре́кшая, я́же ве́щію ісполня́ти научи́ла єси́.","Ра́дуйся, Ві́ро, ві́рою неви́димоє, я́ко ви́димоє, зрі́ти нам помога́ющая;","ра́дуйся, в нетлі́ніє облече́нная.","Ра́дуйся, Наде́ждо, наде́ждою страда́нія на́ша во юдо́лі ско́рби ослабля́ющая і в го́рняя десни́цею указу́ющая;","ра́дуйся, Ца́рствіє Небе́сноє унаслі́довавшая.","Ра́дуйся, Люби́, любо́вію Боже́ственною блаже́нство безсме́ртния жи́зні нам открива́ющая;","ра́дуйся, благода́тію Ду́ха Свята́го осія́нная.","Ра́дуйся, Софі́є, сі́єсть прему́дрость, прему́дре дще́ри твоя́ воспита́вшая;","ра́дуйся, в доброді́теліх ві́ри, наде́жди і любве́ нас утвержда́ющая.","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Кондак 1","ps":["Ізбра́нним раба́м Го́спода Вседержи́теля, Ві́рі, Наде́жде і Любві́, і му́дрій ма́тері Софі́ї, похва́льная вам пі́нія умиле́нно возно́сим. Ви же, я́ко дерзнове́ніє ко Христу́ Бо́гу іму́ще, моли́тися за ни, во є́же ізба́витися нам гріхо́в і скорбе́й, да благода́рственно вопіє́м вам:","Ра́дуйтеся, Ві́ро, Наде́ждо і Люби́, ку́пно с Софі́єю, ма́терію ва́шею прему́дрою."]},{"h":"Молитва перша","ps":["О святи́я і достохва́льния му́ченици Ві́ро, Наде́ждо і Люби́, і до́блестних дще́рей му́драя ма́ти Софі́є! К вам ни́ні со усе́рдною моли́твою притека́єм. Что бо па́че возмо́жеть предста́тельствовати за ни пред Го́сподем, а́ще не ві́ра, наде́жда і люби́, три сія́ доброді́телі пребива́ющия, во ї́хже о́браз нарече́нния, са́мою ве́щію о́ния яви́сте? Умолі́те у́бо Го́спода, да в ско́рбіх і напа́стіх неізрече́нною благода́тію Своє́ю покри́єть ни, і сохрани́ть, і Того́ сла́ву, я́ко со́лнце незаходи́моє, зрі́ти да сподо́бит. Споспішеству́йте нам во смире́нних моле́ніїх на́ших, да прости́ть Госпо́дь Бог гріхи́ і беззако́нія на́ша, і да поми́луєть нас грі́шних, і щедро́т Свої́х да сподо́бит нас Христо́с Бог, Єму́же сла́ву возсила́єм, со Безнача́льним Єго́ Отце́м, і Пресвяти́м і Благи́м і Животворя́щим Єго́ Ду́хом, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Молитва друга","ps":["Вас, святи́я му́ченици, Ві́ро, Наде́ждо і Люби́, сла́вим, велича́єм і ублажа́єм, ку́пно с му́дрою ма́терію Софі́єю, є́йже покланя́ємся, я́ко о́браз богому́драго попече́нія явля́ющей. Умоли́, свята́я Ві́ро, Творця́ ви́димих і неви́димих, да ві́ру крі́пку, небла́зненну і неруши́му пода́сть нам. Хода́тайствуй, свята́я Наде́ждо, пред Го́сподем Ісу́сом за нас грі́шних, да упова́ніє на блага́я не отжене́ть от нас і от вся́кия ско́рби і ну́жди да ізба́вить ни. Іспові́ждь, свята́я Люби́, Ду́ху і́стини, Уті́шителю, напа́сти і печа́лі на́ша, да Той сви́ше сла́дость небе́сную ниспо́слеть душа́м на́шим. Помозі́те у́бо в біда́х на́ших, святи́я му́ченици, і ку́пно с му́дрою ма́терію ва́шею Софі́єю, молі́те Царя́ царе́й і Го́спода госпо́дствующих, да сохрани́ть под покро́вом Це́рков Свою́ святу́ю. Со слеза́ми умиле́нно припа́дающе к вам, ва́шего те́плаго предста́тельства пред Бо́гом усе́рдно мо́лим, да ку́пно с ва́ми і со всі́ми святи́ми превознесе́м і препросла́вим пресвято́є і вели́коє і́м'я Отця́ і Си́на і Свята́го Ду́ха Бо́га, Предві́чнаго Влади́ки і благи́х Соді́теля, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Торжеству́єть Це́рков перворо́дних, / і свесели́ться приє́мля ма́тер о ча́діх веселя́щуюся, / я́же я́ко му́дрости тезоімени́тая / тро́йственним богосло́вським доброді́телем равночи́сленния породи́. / Ти́я с му́дрими ді́вами зрить уневе́стившіяся Жениху́ Бо́гу Сло́ву, / с не́ю і ми духо́вні в па́м'яті їх свеселі́мся, глаго́люще: / Тро́йці побо́рници, / Ві́ро, Любве́ і Наде́ждо, // во ві́рі, любві́ і наде́жде утвержда́йте нас."]},{"h":"Кондак, глас 1","ps":["Софі́ї честни́я свяще́ннейшия ві́тві, / Ві́ра і Наде́жда і Любо́в, показа́вшеся, / му́дрость обуї́ша є́ллинськую благода́тію, / і пострада́вше, і побідоно́сиці яви́вшеся, // вінце́м нетлі́нним от всіх Влади́ки Христа́ ув'язо́шася."]},{"h":"Величання","ps":["Велича́єм вас, святи́я му́ченици, Ві́ро, Наде́ждо, Любве́ і Софі́є, і чтим святи́я страда́нія ва́ша, я́же за Христа́ претерпі́ли є́сте."]}],"notes":[]},{"u":"Акафіст священномученику Антипі, єпископу Пергамському","e":"Akathist to the Hieromartyr Antipas, Bishop of Pergamum","secs":[{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і ізря́дний неду́гов ціле́бниче, по да́нній ті от Го́спода благода́ті, я́ко імі́яй дерзнове́ніє к Пода́телю здра́вія, от вся́ких нас бід і неду́гов свободи́, да зове́м ті:","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Ікос 1","ps":["А́нгелов і всея́ тва́рі Соді́тель, яви́вий тя Це́ркве Святі́й всесві́тлаго світи́льника ві́ри і за ві́ру тверді́йшаго адама́нта священному́ченика, науча́єть нас восхваля́ти по́двиги твоя́ і воспіва́ти тя, священному́чениче Анти́по, си́це:","Ра́дуйся, богому́дрий наста́вниче правосла́вния ві́ри;","ра́дуйся, я́ко істочи́л єси́ ріки́ уче́нія, ві́рних напаяющия.","Ра́дуйся, я́ко му́тния води́ многобо́жія потреби́л єси́;","ра́дуйся, я́ко де́моном служа́щия чествова́ти Бо́га І́стиннаго научи́л єси́.","Ра́дуйся, я́ко із глубини́ безбо́жия ізвле́кл єси́ заблу́ждшия челові́ки і наста́вил єси́ їх на путь спасе́нія;","ра́дуйся, я́ко дрема́нієм нече́стія одержи́мия возбуди́л єси́ к ра́зуму і́стиннаго Богові́дінія.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 2","ps":["Ви́дя лю́тоє гоне́ніє непра́ведних на благочести́вия христия́ни, не убоя́лся єси́ преще́нія їх і мучи́тельства, богоізбра́нне но дерзнове́нно пред лице́м їх і́стиннаго Бо́га іспові́дал єси́, вразумля́я тіх обрати́тися от су́єтних і́дол ко Христу́ Спаси́телю і ви́ну пі́ти Єму́: Аллилу́я."]},{"h":"Ікос 2","ps":["Среди́ язи́к, сидящих во тьмі і сі́ні сме́ртній, сохрани́в непоро́чность житія́ твоєго́, свя́те Анти́по, А́нгелом сожи́тель би́ти сподо́бился єси́ і с ни́ми воспіва́ти Тро́їчеськую піснь Бо́гу на Небесі́. Усли́ши нас, пою́щих ті на землі́ похва́льная пі́нія сія́:","Ра́дуйся, житію́ безпло́тних поревнова́вий;","ра́дуйся, чистото́ю А́нгелом уподо́бивийся.","Ра́дуйся, во пло́ті яви́вийся а́ки безпло́тен;","ра́дуйся, в ті́лі пожи́вий духо́вно, на землі́ небе́сно.","Ра́дуйся, небе́сний челові́че;","ра́дуйся, земни́й А́нгеле.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 3","ps":["Си́лою благода́ті Бо́жієй, єще́ сий в тілесі́ возсія́л єси́ я́ко со́лнце, всіх просвіща́я і разгоня́я глубо́кую нощ безбо́жия. Сего́ ра́ди почита́я тя я́ко сопресто́льника Апо́столов і ціле́б пода́теля воспіва́єм Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я неуси́пноє попече́ніє о спасе́нії душ во тьмі ідолослуже́нія погиба́ющих, богому́дре Анти́по, не престава́л єси́ призива́ти тіх к Богоуго́дній жи́зні, подава́я собо́ю примі́р соверше́ннаго благоче́стія христия́нськаго; сего́ ра́ди усе́рдно прино́сим ті похвали́ сія́:","Ра́дуйся, о́бразе житія́ пра́веднаго;","ра́дуйся, указа́телю неві́рним стезі́, веду́щей к Небесі́.","Ра́дуйся, ві́рним ко спасе́нію путеводи́телю;","ра́дуйся, приле́жний вразуми́телю заблу́ждших.","Ра́дуйся, во обраще́нії ідолопокло́нников к ві́рі во Христа́ яви́вий самоотверже́ніє всеці́лоє;","ра́дуйся, архієре́ю Бо́жий, до́брі упасший слове́сноє ста́до твоє́.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 4","ps":["Ве́лія бу́ря я́рости Дометія́на, ди́шущаго уби́йством, восшуме на храм душі́ твоєя́, свя́те Анти́по, но того́ не возмо́же поколеба́ти, основа́н бо бі на тве́рдом ві́ри Христо́ви ка́мені, на не́мже ти, богоізбра́нне, неподви́жно пребива́я, укріпля́ющему тя Го́споду Ісу́су воспіва́л єси́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше от тебе́ нечести́вий іге́мон і жреци́ і́дольстії словеса́ прему́дрости, распиха́хуся на тя зло́бою, па́че же єгда́ рекл єси́: «Єди́но то віждь, о іге́моне, я́ко христия́нин аз єсьм, ца́рському же велі́нію безу́мному і нечести́вому повину́тися отню́дь не ізволя́ю». Сіє́ у́бо воспомина́я, взива́єм ті си́це:","Ра́дуйся, ві́ру во Христа́ до сме́рти сохрани́вий до́брі;","ра́дуйся, си́лою сви́ше на брань проти́ву мучи́телей препоя́санний.","Ра́дуйся, побідоно́сною сла́вою от Христа́ Побіди́теля облече́нний;","ра́дуйся, Апо́столов во іспові́данії Христа́ подража́телю.","Ра́дуйся, страсте́м Христо́вим соприча́стниче;","ра́дуйся, кро́вію своє́ю утверди́вий правові́ріє.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 5","ps":["Богото́чний істо́чник ди́вних чуде́с яви́лся єси́, достосла́вне Анти́по: прия́л єси́ от Го́спода дар неду́ги врачева́ти, да позна́ють неверующиє Бо́га, я́ві тобо́ю чудодействующа, і воспою́ть Єму́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше лю́діє гра́да Перга́ма, я́ко даде́ся ті благода́ть немощни́х ісціля́ти, і от вся́ких тіле́сних і душе́вних скорбе́й ізбавля́ти, удиви́шася. Ми же за мно́гая ісціле́нія тобо́ю на ни ізлива́ємая, ублажа́єм тя похвала́ми си́ми:","Ра́дуйся, боля́щих ісціле́ніє;","ра́дуйся, расслабленних укріпле́ніє.","Ра́дуйся, неду́гующих врачу́ благода́тний;","ра́дуйся, скорб'я́щим непости́дноє прибі́жище.","Ра́дуйся, я́ко тобо́ю от мно́гих ран грі́шнії ісціля́ються;","ра́дуйся, я́ко тобо́ю от вся́ких болі́зней с ві́рою призива́ющії тя ізбавля́ються.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 6","ps":["Пропові́дником і́стини, Христо́вим Апо́столом поревнова́в, не убоя́лся єси́ звіронра́вних мучи́телей, не ужасну́лся єси́ преще́нія, но со дерзнове́нієм пропові́дал єси́ їм Христа́ Бо́га, Єго́ же ра́ди в разже́н сосу́д мі́дян вве́ржен бил єси́, да просла́виться тебе́ ра́ди ди́вний во святи́х Госпо́дь, Єму́же ти і в огні́ взива́л єси́: Аллилу́я."]},{"h":"Ікос 6","ps":["Імі́я ве́лію ре́вность о лю́діх Бо́жиїх, ти болі́зновал єси́ о погря́зших в бе́здні ідолопоклонства, і ра́ди спасе́нія неві́рних гото́в бил єси́, я́коже боже́ственний Па́вел, сам отлуче́н би́ти от Христа́, возлю́бленнаго тобо́ю. Сего́ ра́ди со умиле́нієм взива́єм ті си́це:","Ра́дуйся, отцю́ ві́рующих Авраа́му в ходатайстві о грі́шниціх подража́вий;","ра́дуйся, Богови́дцю Мойсе́ю в пла́менней моли́тві о спасе́нії неві́рующих поревнова́вий.","Ра́дуйся, но́вий Самуї́ле, в моли́тві о беззаконниціх глаго́лавий: «Не бу́ди мні, є́же не вопи́ти о вас с моле́нієм ко Го́споду»;","ра́дуйся, подража́телю архідия́кона Стефа́на, во вре́м'я страда́нія в медяном во́лі о мучителіх сотвори́вий сицеву́ю моли́тву: «Го́споди! Не поста́ви їм гріха́ сего́».","Ра́дуйся, я́ко незло́бив сий, за убива́ющих тя моли́лся єси́, я́ко за благотворцев;","ра́дуйся, па́стирю любвеобильний, положи́вий ду́шу свою́ за слове́сния о́вці твоя́.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 7","ps":["Хотя́щу беззако́нному мучи́телю ле́стними словеси́ отврати́ти тя, Анти́по, от І́стиннаго Бо́га ко і́долом безду́шним, ти, богому́дре, отвіща́л єси́: прише́д в послі́днюю ста́рость і к сме́рті прибли́жився, не ізміню́ ві́ри моєя́ в Ісу́са Христа́, Бо́га моєго́, Єму́же со Отце́м і Святи́м Ду́хом при́сно пою́ і во ві́ки віко́в і́мам пі́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє чу́до показа́ Госпо́дь тобо́ю, єгда́ ти по велі́нію злочести́ваго мучи́теля вве́ржен бил єси́ в разже́н мі́дян коно́б, в не́мже я́ко хліб сла́дкий іспеклся єси́ і во воню́ благоуха́нія Святі́й Тро́йці прине́слся єси́. Благогові́йні у́бо воспомина́я сіє́ преве́ліє терпі́ніє твоє́, блажи́м тя похвала́ми си́ми:","Ра́дуйся, позорищним вверженієм в разженний сосу́д горди́ню мучи́теля низложи́вий;","ра́дуйся, я́ко огнь любве́ к Бо́гу в се́рдці твоє́м до конця́ жи́зні сохрани́вий.","Ра́дуйся, я́ко Христа́ ра́ди огне́м кончи́ну прия́вий;","ра́дуйся, тве́рдіє ка́мене в терпі́нії яви́вийся.","Ра́дуйся, я́ко укріпля́ємий Христо́м Бо́гом, пресла́вно жизнь на землі́ сконча́л єси́;","ра́дуйся, пресві́тлому му́ченичеському ли́ку сопричтенний.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 8","ps":["Стра́нно бі ви́діти язи́ком, неві́дущим Бо́жієй си́ли, ка́ко в слабом старчеськом ті́лі возмо́гл єси́, святи́телю Анти́по, претерпі́ти за Христа́ люті́йшия муки́. Ми же, благодаря́ о сем Бо́га, дарова́вшаго ті такову́ю крі́пость, с любо́вію взива́єм: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь пре́дан бил єси́ Ісу́су Пресла́дкому, святи́телю Анти́по, і сла́дці Єго́ ра́ди го́ркія муки́ в огні́ претерпі́л єси́, глаго́лал бо єси́: «Ча́шу страда́ній, ю́же даде́ мі Госпо́дь, не і́мам ли пи́ти»; ті́мже і сам показа́лся єси́ а́ки ча́ша, сла́дость чуде́сних ісціле́ній ізлива́ющая всім вопію́щим к тебі́ такова́я:","Ра́дуйся, все́ю душе́ю возлюби́вий Ісу́са Пресла́дкаго;","ра́дуйся, па́стирю, слове́сним овця́м во Свята́я святи́х путь показа́вий.","Ра́дуйся, ріко́, ороша́ющая мир вода́ми благода́ті Бо́жієй;","ра́дуйся, неісчерпа́ємий істо́чниче чуде́сних ісціле́ній.","Ра́дуйся, сосу́де, на вся неду́ги врачева́нія неоску́дно ізливающий;","ра́дуйся, я́ко Госпо́дь сил ди́вная на тебі́ яви́л єсть.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 9","ps":["Вся́кую стяжа́л єси́ чудоді́йствія си́лу благода́тію ди́внаго во святи́х Свої́х Бо́га, святи́телю Анти́по: не то́кмо бо моли́твами твої́ми устраши́л єси́ бі́си, но і соверше́нно із гра́да Перга́ма ізгна́л єси́ я. Воспомина́я сію́ побі́ду твою́ над зли́ми ду́хи, благода́рні вопіє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не довлі́єть ізрещи́, коли́кую прия́л єси́, свя́те Анти́по, от Го́спода власть ізгоня́ти от люде́й дия́вола с лука́вими де́мони, за є́же ми восхваля́єм тя си́це:","Ра́дуйся, вся́чеських ко́зней дия́вола разруши́телю;","ра́дуйся, сатани́ посрами́телю.","Ра́дуйся, стужа́ємих от бісо́в свободи́телю;","ра́дуйся, де́монов отгнателю. Ра́дуйся, те́мних а́дських сил устрашителю;","ра́дуйся, от него́же ду́хи зло́би, я́коже дим, ісчеза́ють.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу твою́, презрі́л єси́ плоть і не убоя́лся єси́ от убива́ющих ті́ло, свя́те Анти́по, єгда́ бо усли́шал єси́ осужде́ніє на сожже́ніє в медяном во́лі, ти ра́достно прия́л єси́ о́ноє, воспіва́я Го́сподеві: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ огражда́ющая от вся́ких зол усе́рдно тя в по́мощ призива́ющих, свя́те Анти́по, не то́кмо бо во Асі́ї живу́щим, но і во всіх мі́стіх су́щим христия́ном твоє́ю ді́йственною моли́твою подає́ши духо́вная дарова́нія; ї́хже ра́ди і ми, о́тче святи́й, ублажа́єм тя си́це:","Ра́дуйся, сосу́де, істоча́яй єле́й Бо́жия милосе́рдія;","ра́дуйся, живоно́сний істо́чниче, струї́ ісціле́ній ізливающий нам.","Ра́дуйся, ско́рий возставителю здра́вія в не́мощі лежа́щих;","ра́дуйся, всіх лю́тих болі́зней, па́че же лю́тия зубни́я болі́зні, ціли́телю.","Ра́дуйся, безме́здний врачу́ болі́зні душе́вния і тіле́сния;","ра́дуйся, пода́телю врачева́ній всім, притекающим к тебі́ с ві́рою.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 11","ps":["Пі́ніє благоприя́тноє Пресвяті́й Тро́йце прине́сл єси́, досто́йний преє́мниче Апо́столов, Анти́по, не то́чію умо́м, сло́вом і ду́хом, но живи́м всего́ себ'я́ в же́ртву принесе́нієм. Тім же, а́ще і не дово́льни єсьми́ к похвале́нію такови́х твої́х по́двигов, оба́че благода́рні су́щи, поє́м ди́вному во святи́х Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник, от І́стиннаго Сві́та озаря́ємий, су́щим на землі́ явля́єшися, равноапостольний Анти́по, просвіща́єши бо се́рдця ві́рних і к ра́зуму Боже́ственному вся наставля́єши, поуча́я і нас со умиле́нієм взива́ти:","Ра́дуйся, заре́ Бо́жия сві́та;","ра́дуйся, денни́це Со́лнця Пра́вди.","Ра́дуйся, сія́ніє Єва́нгельськаго уче́нія;","ра́дуйся, світи́ло небе́снаго блиста́нія.","Ра́дуйся, просвіща́яй душі́ ві́рних;","ра́дуйся, озаря́яй се́рдця і́щущих пра́вди.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную ті от Бо́га ві́дуще, ра́достно і́м'я твоє́ воспомина́єм, святи́телю Анти́по, і с те́плим моле́нієм к всечестно́му о́бразу твоєму́ притека́юще, прилі́жно мо́лим тя: пода́ждь цільбу́ стра́ждущим лю́тою зубною болі́знію і ізба́ви всіх нас от вся́кия ну́жди і печа́лі, да поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Сла́вную кончи́ну твою́ пою́ще, архієре́ю Бо́жий, і те́плую моли́тву твою́ к Бо́гу о христия́нах воспомина́юще, восхваля́єм Го́спода Сил, ди́вная на тебі́ сотво́ршаго; ти же усли́ши нас, уми́льно вопію́щих ті:","Ра́дуйся, те́плий пред Го́сподем о нас моли́твенниче;","ра́дуйся, при́сний пред Бо́гом наш засту́пниче.","Ра́дуйся, до́брий наш наста́вниче;","ра́дуйся, о спасе́нії нас грі́шних си́льний хода́таю.","Ра́дуйся, Царя́ Небе́снаго ско́рий умилостиви́телю;","ра́дуйся, благосе́рдий помо́щниче всіх благоче́стно соверша́ющих па́м'ять твою́.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 13","ps":["О, пресла́вний і всехва́льний священному́чениче Анти́по! Прийми́ сіє́ похва́льноє пі́ніє от нас недосто́йних во умиле́нії тебі́ приноси́моє, і богоприя́тним твої́м хода́тайством умоли́ Го́спода дарова́ти боля́щим здра́віє душе́вноє і тіле́сноє, ізба́вити всіх нас от бід і напа́стей в жи́зні сей, по сме́ртном же успе́нії на́шем, в день Стра́шнаго Суда́ одесну́ю Пра́веднаго Судії́ ста́ти і в Ца́рствії Сла́ви Єму́ воспіва́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов і всея́ тва́рі Соді́тель, яви́вий тя Це́ркве Святі́й всесві́тлаго світи́льника ві́ри і за ві́ру тверді́йшаго адама́нта священному́ченика, науча́єть нас восхваля́ти по́двиги твоя́ і воспіва́ти тя, священному́чениче Анти́по, си́це:","Ра́дуйся, богому́дрий наста́вниче правосла́вния ві́ри;","ра́дуйся, я́ко істочи́л єси́ ріки́ уче́нія, ві́рних напаяющия.","Ра́дуйся, я́ко му́тния води́ многобо́жія потреби́л єси́;","ра́дуйся, я́ко де́моном служа́щия чествова́ти Бо́га І́стиннаго научи́л єси́.","Ра́дуйся, я́ко із глубини́ безбо́жия ізвле́кл єси́ заблу́ждшия челові́ки і наста́вил єси́ їх на путь спасе́нія;","ра́дуйся, я́ко дрема́нієм нече́стія одержи́мия возбуди́л єси́ к ра́зуму і́стиннаго Богові́дінія.","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Кондак 1","ps":["Возбра́нний чудотво́рче і ізря́дний неду́гов ціле́бниче, по да́нній ті от Го́спода благода́ті, я́ко імі́яй дерзнове́ніє к Пода́телю здра́вія, от вся́ких нас бід і неду́гов свободи́, да зове́м ті:","Ра́дуйся, Анти́по, ско́рий помо́щниче в болі́зніх на́ших."]},{"h":"Молитва","ps":["О, пресла́вний священному́чениче Анти́по, ско́рий помо́щниче христия́ном в болі́зніх! Ві́рую от всея́ душі́ і помишле́нія, я́ко даде́ся тебі́ от Го́спода дар боля́щия ісціля́ти, неду́гующия врачева́ти і разсла́бленния укріпля́ти. Сего́ ра́ди к тебі́, я́ко благода́тному врачу́ болі́зней, аз немощни́й [не́мощная] прибіга́ю і твой досточти́мий о́браз с благогові́нієм лобиза́я, молю́ся: твої́м предста́тельством у Царя́ Небе́снаго іспроси́ мні боля́щему [боля́щей] ісціле́ніє от удруча́ющия м'я зубни́я болі́зні, а́ще бо і недосто́їн [недосто́йна] єсьм тебі́, благостнійшаго отця́ і при́снаго засту́пника моєго́, но ти, бив подража́тель человіколю́бія Бо́жия, сотвори́ м'я досто́йна [досто́йну] твоєго́ заступле́нія чрез моє́ обраще́ніє от злих діл к благо́му житію́, уврачу́й оби́льно дарова́нною тебі́ благода́тію я́зви і стру́пи душі́ і ті́ла моєго́, да́руй мі здра́віє і спасе́ніє і во всем благо́є поспіше́ніє, да та́ко ти́хоє і безмо́лвноє житіє́ пожи́во во вся́ком благоче́стії і чистоті́, сподо́блюся со всі́ми святи́ми сла́вити всесвято́є і́м'я Отця́ і Си́на і Свята́го Ду́ха. Амі́нь."]},{"h":"Тропар, глас 4","ps":["І́дольськия ле́сти упраздни́л єси́, Анти́по, / і, дия́вольськую попра́в си́лу, / пред богобо́рці дерзнове́нно Христа́ іспові́дал єси́. / Ті́мже со А́нгельськими чи́ни во Ви́шніх водворя́яся, / Влади́ці всіх славосло́віє принося́, / і о нас моле́бноє благодаре́ніє предлага́єши, / благода́ть цільби́ да́руя. / Сего́ ра́ди тя чтим, / священному́чениче Анти́по, / моли́ Христа́ Бо́га, // да спасе́ть ду́ші на́ша."]},{"h":"Кондак, глас 4","ps":["Апо́столов сопресто́льник і святи́телей украше́ніє / бил єси́, блаже́нне, / му́ченичеськи просла́вився, / возсія́л єси́, я́коже со́лнце, всіх просвіща́я, / Анти́по свяще́нне, / разруши́л єси́ безбо́жия нощ глубо́кую. / Сего́ ра́ди тя почита́єм, / я́ко Боже́ственнаго су́ща священному́ченика // і ціле́б пода́теля."]},{"h":"Величання","ps":["Велича́єм тя, / священному́чениче Анти́по, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст блаженній Валентині Мінській","e":"Akathist to the Blessed Valentina of Minsk","secs":[{"h":"Кондак 1","ps":["Ізбра́нной Бо́гом на сохране́ніє ві́ри Правосла́вния во дні гоне́ній на землі́ Оте́чества на́шего, хвале́бноє прино́сим ті пі́ніє, блаже́нная ма́ти на́ша Валентино. Ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, ізба́ви нас от зол душе́вних і тіле́сних, да со умиле́нієм зове́м ті:","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Ікос 1","ps":["А́нгела ди́вна Белой Русі́ яви́ тя всея́ тва́рі Созда́тель, обрати́ ті лю́ди заблу́ждшия на путь покая́нія і призва́ти їх на служе́ніє І́стині. Ті́мже і ми, благодаря́ще Бо́га, прославля́єм тя, я́ко просвіти́тельницю і засту́пницю на́шу, і усе́рдно вопіє́м ті:","Ра́дуйся, пречу́дная ізбраннице Про́мисла Боже́ственнаго.","Ра́дуйся, звіздо́ прекра́сная небосвода церко́внаго.","Ра́дуйся, землі́ белоруськия сла́вноє украше́ніє.","Ра́дуйся, душа́м на́шим пресла́дкоє утіше́ніє.","Ра́дуйся, в ходатайствах о нас неусипа́ющая.","Ра́дуйся, пла́меню моли́тви неугаса́ющий.","Ра́дуйся, Ма́тер Бо́жию непреста́нно велича́ющая.","Ра́дуйся, люби́ти всіх нелицемі́рно Є́ю науче́нная.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 2","ps":["Созерцала єси́ ра́достно, блаже́нная ма́ти, красоту́ ми́ра Бо́жия, і любо́в премно́гую к лю́дем імі́ла єси́, от літ ді́тських о всем благодаря́щи Бо́га а́нгельською пі́снію: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум іму́щи Боже́ственний, уго́днице Бо́жия Валентино, от рожде́нія твоєго́ тща́лася єси́ угожда́ти Го́споду трудо́м, ві́рою і моли́твою. Єще́ младе́нець су́щи, єль насади́ла єси́, я́же возрасте́ в дре́во крі́пкоє во о́бразі Креста́. Ми же, ви́дяще зна́меніє благослове́нія Бо́жия на труді́х твої́х, гла́си хвале́бними взива́єм си́це:","Ра́дуйся, блага́я о́трасле ко́рене благочести́ваго.","Ра́дуйся, сестри́ імі́вши нра́ва молчалйваго.","Ра́дуйся, отця́ ієрейськими моли́твами во ві́рі утвержде́нная.","Ра́дуйся, ма́терію в любві́ к Бо́гу, святи́м і бли́жнім умудренная.","Ра́дуйся, сла́дость ра́йськую чте́нієм Сло́ва Бо́жия вкусившая.","Ра́дуйся, нежность і пре́данность сро́дникам ще́дро дарившая.","Ра́дуйся, за́повідь послуша́нія роди́телем кро́тко іспо́лнившая.","Ра́дуйся, і нас ко ісполне́нію велі́ній Бо́жиїх призива́ющая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 3","ps":["Си́лою Ви́шняго укрепленной, в путеше́ствії с роди́телем твої́м во град Кронштадт яви́ся ті святи́й Пантелеймон і рече́: \"Моли́ся непреста́нно!\" І а́біє вознесла́ єси́ к Бо́гу чи́стия ді́тськия моли́тви твоя́, і ізба́влен бисть кора́бль от потопле́нія, челові́ци же воспі́ша Творцю́ і Спа́су благода́рно: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи ре́вность мно́гую о Го́споді, к па́стирю Кроншта́дтському притекла́ єси́, блаже́нная, і́же прови́дя в тебі́ ізбра́нний сосу́д Бо́жий, благослови́ тя, до́брую отрокови́цю, і бесі́доваше с тобо́ю. Ми же, зря́ще духо́вноє восхожде́ніє твоє́ от си́ли в си́лу, со благогові́нієм тебі́ взива́єм:","Ра́дуйся, с младе́нства ієре́ї окормляємая.","Ра́дуйся, от честни́х пресви́теров свя́то почита́ємая.","Ра́дуйся, ізмла́да моли́тву возлюби́вшая.","Ра́дуйся, непреста́нно Го́споду трудившаяся.","Ра́дуйся, неради́вих і ліни́вих ісправля́ющая.","Ра́дуйся, к ді́лом во сла́ву Бо́жию побужда́ющая.","Ра́дуйся, от Христа́ дар врачева́нія приє́мшая.","Ра́дуйся, чудотворе́ньми Бо́га прославлявшая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 4","ps":["Бу́рі страсте́й ізбіжа́вши, свята́я Валентино, і приє́мши благослове́ніє Бо́жиє і честни́х роди́телей, любо́вію і смире́нієм созидала єси́ ма́лую це́рков семи благочести́вия, подаю́щи всім примі́р доброді́тельния і кро́ткия жени́, му́жу помога́ющи і пою́щи Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавши Христоподражательную жизнь богоно́сних і вели́ких отце́в, со смире́нієм і упова́нієм на ми́лость Бо́жию сретила єси́ юдо́ль плаче́вную земну́ю - утрату сро́дников і до́браго супру́га твоєго́. Чад по пло́ті не даде́ ті Госпо́дь, оба́че ча́да духо́вная во мно́жестві обріто́шася ті смотре́нієм Бо́жиїм, і́же тебе́, духо́вной ма́тері своє́й, усе́рдно восклиця́ють:","Ра́дуйся, благоче́стія учи́тельнице.","Ра́дуйся, та́йних согріше́ній обличи́тельнице.","Ра́дуйся, многодетних семе́й покрови́тельнице.","Ра́дуйся, горделивих жен пред супругами смирительнице.","Ра́дуйся, жени́ непра́здния от гріха́ спаса́ющая.","Ра́дуйся, младе́нцев во чре́ві ма́тернем сохраня́ющая.","Ра́дуйся, гнів Бо́жий моли́твами твої́ми утоля́ющая.","Ра́дуйся, уми́ і се́рдця на́ша к Небесі́ устремляющая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́ уподо́билася єси́, ма́ти Валентино: по́двигу Ксе́нії блаже́нния подража́ющи, удосто́їлася ти блаже́нства ра́йськаго за вели́коє смире́ніє твоє́ і терпі́ніє скорбе́й. Ни́ні же в ли́ці святи́х воспіва́єши Бо́гу хвалу́: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше тя лю́діє, я́ко А́нгела Бо́жия, блаже́нства єва́нгельськая всім се́рдцем возлюби́вшую, притека́ху к тебі́, не могу́щей ходи́ти, моли́тв от тебе́ і́щуще. Ти же по глаго́лу Христо́ву приходивших к тебі́ не отгоняла єси́, но спасе́нію челові́чеському ре́вностно служи́ла єси́. Научи́ у́бо і нас чи́стим се́рдцем сла́вити Го́спода, тебі́ взива́ющих:","Ра́дуйся, свя́тость твою́ при́тчами скривавшая.","Ра́дуйся, на та́йния вопроси я́вно отвещавшая.","Ра́дуйся, жадних і скупих м'ягко облича́ющая.","Ра́дуйся, в добротворе́нії ві́рних утвержда́ющая.","Ра́дуйся, цві́ти і пояскй с моли́твою сплетавшая.","Ра́дуйся, сія́ всім приходившим раздаявшая.","Ра́дуйся, со Ксе́нією блаже́нною в єди́н день величаємая.","Ра́дуйся, с Матро́ною свято́ю богобо́рці посрамля́ющая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 6","ps":["Пропові́днице ві́ри Христо́ви і благоче́стія христия́нськаго, пра́ведная Валентино, бу́ри богоборчеськия не устраши́лася єси́, но по́двиг іспові́дничества под'ємши, душі́ мно́гих скорб'я́щих і во мра́ці отча́янія пребива́ющих укрепляла єси́, Го́споду пою́щи: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ла єсй в немощной пло́ті сві́том небе́сним, свята́я Валентино, єгда́ мудрі́йшим юро́дством, терпі́нієм і страда́нієм Христу́ послі́довала єси́. Сего́ ра́ди яви́ тя Госпо́дь істо́чник благода́ті стра́ждущим лю́дем, єгда́ разоре́ни би́ша хра́ми землі́ Ми́нськия. Ми же ублажа́єм тя зва́нії си́ми:","Ра́дуйся, в не́мощі челові́чеськой си́лу Бо́жию яви́вшая.","Ра́дуйся, спасе́нію наро́да белоруськаго послужи́вшая.","Ра́дуйся, за ісціле́нія мзду не приймавшая.","Ра́дуйся, чи́стим се́рдцем Го́спода созерцавшая.","Ра́дуйся, гоне́нія за І́стину по́двигом юро́дства попра́вшая.","Ра́дуйся, в мирстей жи́зні висоту́ і́ночества показа́вшая.","Ра́дуйся, во́лі Бо́жієй себі́ преда́вшая.","Ра́дуйся, Госпо́дню во́лю открива́ющая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 7","ps":["Хотя́ преблаги́й Госпо́дь страну́ на́шу благода́тію обогати́ти і да́ти о́браз хотя́щим спасти́ся, подви́же тя Ду́хом Святи́м на вельми́ ско́рбноє і богоуго́дноє житіє́, і́мже удиви́ла єси́ не то́кмо челові́ков на землі́, но і А́нгелов на Небесі́. Каждодневно тяготи́ людські́я носи́вшая безро́потно, услади́ любо́вію і на́ші душі́, да поє́м с тобо́ю Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую ви́дяще тя ізбранницю Бо́жию, іздале́ча теча́ху к тебі́ і пресві́тери церко́внії, обріта́юще в тебі́ кла́дезь му́дрості і Боже́ственних открове́ній. Просвіти́ у́бо і нас, с ві́рою в по́мощ твою́ благода́тную вопію́щих си́це:","Ра́дуйся, честно́є Це́ркве похвале́ніє.","Ра́дуйся, А́нгела храни́теля увеселе́ніє.","Ра́дуйся, в ді́ланії духо́вном подвиза́ющихся му́дро укріпля́ющая.","Ра́дуйся, Го́спода чи́сто славосло́вить певчих науча́ющая.","Ра́дуйся, строї́телем хра́мов Бо́жиїх неоскудіва́ємо помога́ющая.","Ра́дуйся, мольба́ми твої́ми от суєти́ і страсте́й нас ізбавля́ющая.","Ра́дуйся, в недоумі́нний час печа́лі поле́зния по́мисли ниспосилающая.","Ра́дуйся, предстоя́щих тебі́ і моля́щихся от бід соблюда́ющая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 8","ps":["Стра́нники су́щия на землі́ сей, при́сно нас враг іскуша́єть, да не дости́гнем Оте́чества небе́снаго. Помози́ нам, очи́сти ни от вся́кия скве́рни, да іспра́в'яться путіє́ жи́зні на́шея, да не постидить нас Судія́ на нелицемерном і стра́шном Суді́ Своє́м. Моли́ся о нас, Валентино всеблаже́нная, да с тобо́ю возра́дуємся: Аллилу́я."]},{"h":"Ікос 8","ps":["Все́ю ми́слію у Го́спода водворялася єси́, оба́че і Ма́тері Ми́лующей, Цари́це Небе́сній, приноси́ла єси́ пі́ніє умиле́нноє, ака́фисти че́сти пред іко́нами Єя́ всіх наставля́ющи. Ті́мже тебе́, теплой моли́твеннице о нас к Преблагословенной, взива́єм, пра́ведная Валентино:","Ра́дуйся, сла́ву Присноді́ви на всяк день воспіва́ющая.","Ра́дуйся, чудотво́рния іко́ни Пречи́стия свя́то почитающая.","Ра́дуйся, о́бразом Ахтирським дом твой благогові́йно украси́вшая.","Ра́дуйся, Богоро́диці моли́твами тридесятолетнєє лежа́ніє поне́сшая.","Ра́дуйся, а́нгельськима крило́ма в болі́зні утешенная.","Ра́дуйся, на землй небе́снаго посіще́нія удостоєнная.","Ра́дуйся, на ло́же твоє́м а́нгельською чистото́ю сіявшая.","Ра́дуйся, с терпі́нієм неістощимим боля́щим помогавшая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 9","ps":["Все єстество́ а́нгельськоє удиви́ся по́двигу ди́внаго лежанія твоєго́: на одрі́ твоє́м, я́ко на висо́ком столпі́, ду́хом к Небесі́ воспаряющи, от Ду́ха прориця́ющи і цільби́ си́лою Бо́жиєю подаю́щи, нікого́же от себе́ тща і неутешена отпущала єси́. Ми же, таково́му житію́ твоєму́ див'я́щеся, поє́м Всеси́льному Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния не возмо́гуть воспі́ти крі́пость любве́ твоєя́, блаже́нная, яви́лася бо єси́ чадолюби́вая ма́ти скорб'я́щим в тя́жкую годи́ну во́йни, моли́тви возносила єси́ за во́їнство на́ше, по́мощі і заступле́нія у Го́спода прося́щи. І ни́ні умоли́ Єго́ в ми́рі страни́ сохраня́ти, се́рдця на́ша любо́вію наполня́ти, да благода́рно зове́м ті:","Ра́дуйся, жизнь і смерть во́їнов, защитников на́ших, прозревающая.","Ра́дуйся, ко усердной моли́тві за усо́пших сро́дников подвизающая.","Ра́дуйся, мир Христо́во в малові́рния душі́ вселя́ющая.","Ра́дуйся, диха́ніє жи́зні храни́ти науча́ющая.","Ра́дуйся, любо́в ко Оте́честву земно́му показа́вшая.","Ра́дуйся, вели́чієм по́двига твоєго́ всіх удиви́вшая.","Ра́дуйся, ві́ру апо́стольськую пропові́давшая.","Ра́дуйся, милосе́рдієм Ца́рствіє стяжа́вшая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 10","ps":["Спасти́ся хотя́ще от разли́чних напа́стей ми́ра сего́, тя, пра́ведная Валентино, многомощную моли́твенницю к Бо́гу призива́єм: бу́ди нам необори́мая защи́тниця от враг ви́димих і неви́димих і помо́щниця в ну́ждах і ско́рбіх, ізба́ви же нас хода́тайством твої́м от лю́тих бід і іскуше́ній, да сла́вим Бо́га побі́дною пі́снію: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ крі́пкая била́ єси́ всім во дні житія́ твоєго́, блаже́нная Валентино. Того́ ра́ди і мі́сто погребе́нія твоєго́ прибі́жище духо́вноє бисть ча́ющим утіше́нія в скорбном ми́рі сем. Ціле́бницю благода́тную тя ві́дуще, прихо́дим ни́ні ко свято́му гро́бу твоєму́, і от него́ цільби́ безме́здния душа́м і тілесе́м на́шим приє́млюще, благода́рственноє воздає́м ті пі́ніє:","Ра́дуйся, луча́ми пресла́вних чуде́с сві́тло облиста́ющая.","Ра́дуйся, сліпи́м о́чі преди́вно отверза́ющая.","Ра́дуйся, лише́нних сми́сла здра́вим умо́м снабдіва́ющая.","Ра́дуйся, беснующимся ізбавле́ніє подава́ющая.","Ра́дуйся, вся неду́ги лю́тия врачу́ющая.","Ра́дуйся, цілому́дрію ді́ти на́ша науча́ющая.","Ра́дуйся, се́рдця ожесточе́нная ум'ягча́ющая.","Ра́дуйся, от сіте́й вра́жиїх свобожда́ющая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 11","ps":["Пі́нієм акафистним велича́єм тя, наста́вницю на́шу, сві́тло пра́зднующи святу́ю па́м'ять твою́. Ти же ми́лостивно усли́ши ма́лоє моле́ніє сіє́, да і нас к ли́ку му́дрих дів сопричте́ть Госпо́дь Ісу́с Христо́с, ра́достно пою́щих Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світи́льниче духо́вний, єле́єм благода́ті іспо́лненний, под спу́дом не сокритий, свята́я Валентино, да прославля́ємо бу́деть о тебі́ і́м'я Госпо́днє! Освіти́ і нам путь ко спасе́нію, во ві́рі і наде́жде укріпи́, ра́зума і благоче́стія от Бо́га іспроси́, да с любо́вію зове́м ті:","Ра́дуйся, о́бразе і́стиннаго смире́нія.","Ра́дуйся, зерца́ло самоотреченія.","Ра́дуйся, во псалмопеніїх ду́хом к Не́бу воспарявшая.","Ра́дуйся, ра́дость пасхальную в прославле́нії твоє́м дарова́вшая.","Ра́дуйся, страда́нія вре́менная ні во что же вміня́ющая.","Ра́дуйся, ізнемога́ющих во бра́ні укріпля́ющая.","Ра́дуйся, росо́ю Ду́ха ду́шу твою́ омившая.","Ра́дуйся, цві́тник духо́вний ди́вно возраставшая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 12","ps":["Благода́ть Свята́го Ду́ха іспроси́ нам, блаже́нная Валентино, да і ми, любо́вію Христо́вою окормля́ємі, возмо́жем до́брі ходи́ти во сві́ті за́повідей Бо́жиїх, да бу́дем ча́да єди́ния Святи́я, Собо́рния і Апо́стольськія Це́ркве, ві́ру чи́сту соблюда́юще, єди́ним же се́рдцем і єди́ними усти́ Бо́гу воспіва́юще: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ преміогая благодія́нія і страда́нія, ублажа́єм твоє́ непостижи́моє терпі́ніє, ма́ти Валентино, і чту́ще святу́ю па́м'ять твою́, мо́лимся тебі́: укріпи́ дух люде́й правосла́вних, да́руй соверше́нную побі́ду сві́та богові́дінія над тьмо́ю безбо́жия і прийми́ похва́льная сія́:","Ра́дуйся, ві́ру Правосла́вную тве́рдо содержа́ти наставля́ющая.","Ра́дуйся, раскол і суєві́рія іскореня́ющая.","Ра́дуйся, теплото́ю Боже́ственния любве́ душі́ согріва́ющая.","Ра́дуйся, спаса́тися і́менем Ісу́совим вразумляющая.","Ра́дуйся, душі́ і тілеса́ на́ша благода́тно ісціля́ющая.","Ра́дуйся, о прославля́ющих тя Го́спода моля́щая.","Ра́дуйся, ревни́телей крестних ходов сугу́бо награждающая.","Ра́дуйся, наде́ждою на спасе́ніє се́рдця ві́рних увеселя́ющая.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 13","ps":["О преди́вная і пресла́вная уго́днице Бо́жия, блаже́нная ма́ти на́ша Валентино, духо́вним со́лнцем Русі́ Белой возсія́вшая! Прийми́ сіє́ благода́рственноє моле́ніє на́ше, і предстоя́щи ни́ні Престо́лу Го́спода на́шего Ісу́са Христа́, умоли́ Єго́ дарова́ти нам тіле́сноє здра́віє, найпа́че же душе́вноє спасе́ніє, да в день су́дний ра́достно воспоє́м Єму́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгела ди́вна Белой Русі́ яви́ тя всея́ тва́рі Созда́тель, обрати́ ті лю́ди заблу́ждшия на путь покая́нія і призва́ти їх на служе́ніє І́стині. Ті́мже і ми, благодаря́ще Бо́га, прославля́єм тя, я́ко просвіти́тельницю і засту́пницю на́шу, і усе́рдно вопіє́м ті:","Ра́дуйся, пречу́дная ізбраннице Про́мисла Боже́ственнаго.","Ра́дуйся, звіздо́ прекра́сная небосвода церко́внаго.","Ра́дуйся, землі́ белоруськия сла́вноє украше́ніє.","Ра́дуйся, душа́м на́шим пресла́дкоє утіше́ніє.","Ра́дуйся, в ходатайствах о нас неусипа́ющая.","Ра́дуйся, пла́меню моли́тви неугаса́ющий.","Ра́дуйся, Ма́тер Бо́жию непреста́нно велича́ющая.","Ра́дуйся, люби́ти всіх нелицемі́рно Є́ю науче́нная.","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Кондак 1","ps":["Ізбранної Бо́гом на сохране́ніє ві́ри Правосла́вний во дні гоне́ній на землі́ Оте́чества на́шего, хвале́бноє прино́сим ті пі́ніє, блаже́нная ма́ти на́ша Валентино. Ти же, я́ко іму́щая дерзнове́ніє ко Го́споду, ізба́ви нас от зол душе́вних і тіле́сних, да со умиле́нієм зове́м ті:","Ра́дуйся, блаже́нная Валентино, всіх приходя́щих к тебі́ ско́ро утіша́ющая."]},{"h":"Молитва","ps":["О блаже́нная ма́ти на́ша Валентино! Я́коже і во дні земни́я жи́зні твоєя́, с любо́вію принимала єси́ всіх стра́ждущих і немощству́ющих, всіх в ско́рбіх і болі́зніх су́щих, і моли́твами твої́ми целила неду́ги їх. Та́кожде і ни́ні всім, с ві́рою і умиле́нієм приходящим к тебі́, у Го́спода ісціле́нія іспроси́, найпа́че же от паде́ній гріхо́вних сохрани́ і на путь спасе́нія наста́ви. Усли́ши нас недосто́йних, блаже́нная Валентино, і принеси́ на́ша моле́нія ко Престо́лу Всеви́шняго, да с ра́достію восхва́лим Пресвяту́ю Тро́йцю: Отця́ і Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["От младе́нства восприя́вши ві́ру Христо́ву в се́рдці твоє́, я́ко му́драя ді́ва пронесла єси́ чрез все житіє́ плоди́ єя́, ті́мже і Христо́с дарова́ ті си́лу, ціли́ти неду́ги немощству́ющих і коле́блющихся. Ми же прославля́юще тя, блаже́нная ма́ти Валентино, вопіє́м: сла́ва Да́вшему тебі́ крі́пость, сла́ва Просла́вльшему тя, сла́ва Спаса́ющему всіх призива́ющих тя."]},{"h":"Кондак, глас 5","ps":["Хода́тайця за немощству́ющих яви́лася єси́, / на землі́ Минстей блаже́нная Валентино, / в ско́рбіх, біда́х і напа́стіх всіх ві́рних утешающи, / прозріва́ющи болі́зні і неду́ги приходя́щих к тебі́, / про́сим же і ми недосто́йнії, / твоєго́ предста́тельства пред Престо́лом Всеви́шняго, // дарова́ти нам мир і спасе́ніє душ на́ших."]},{"h":"Величання","ps":["Велича́єм тя, свята́я блаже́нная ма́ти на́ша Валенти́на, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст святому Апостолу Варфоломію","e":"Akathist to the Holy Apostle Bartholomew","secs":[{"h":"Кондак 1","ps":["Ізбра́нному от люде́й ізра́їлевих во Христо́ва Апо́стола на уловле́ніє челові́ков, чу́дному Варфоломею, пі́нія похва́льная принесе́м, ві́рнії, я́ко оста́вльшему дом свой, нищету́ Христо́ву возлюби́вшему і Христо́во уче́ніє па́че уче́нія євре́йських кни́жников ізбра́вшему. Ти же, святи́й Апо́столе, всіх нас, па́м'ять твою́ честну́ю пра́зднующих, не оста́ви свої́м предста́тельством і заступле́нієм, да благода́рними устна́ми вопіє́м ті:","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Ікос 1","ps":["А́нгелов Госпо́дь і Спаси́тель всего́ ро́да челові́ча, прови́дів чистоту́ душі́ твоєя́, святи́й Варфоломе́є, благоволи́ ізбра́ти тя во єди́наго от обоюна́десяте і нарещи́ Апо́столом Свої́м. Ми же, див'я́щеся духо́вним дарованіям твої́м, прославля́єм тя си́це:","Ра́дуйся, Варфоломе́є, вели́кий Христо́в Апо́столе.","Ра́дуйся, учениче́ Христо́в усе́рднійший.","Ра́дуйся, я́ко се́рдце своє́ непоро́чно імі́л єси́.","Ра́дуйся, я́ко лука́вия наставле́нія ста́рцев євре́йських отве́ргл єси́.","Ра́дуйся, я́ко всім се́рдцем свої́м Христу́ приліпи́лся єси́.","Ра́дуйся, я́ко вся мирськи́я бла́га ні во что́же вміни́л єси́.","Ра́дуйся, я́ко отця́ і ма́тер, бра́тію і сестри́ своя́ ра́ди Го́спода оста́вил єси́.","Ра́дуйся, я́ко во следованії за Христо́м і́стинноє блаже́нство восприя́л єси́.","Ра́дуйся, уче́нієм Христо́вим пленивийся.","Ра́дуйся, в путі́ Христо́вом бла́го Ца́рствія Небе́снаго предвкуси́вий.","Ра́дуйся, благогласнейший пропові́дниче Христо́ва уче́нія.","Ра́дуйся, ві́рний слуго́ Госпо́день.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 2","ps":["Ви́дя чу́дная діла́ Го́спода своєго́ і Учи́теля і сли́ша із уст Єго́ ісходя́щеє небе́сноє уче́ніє, я́сно уразумі́л єси́, святи́й Варфоломе́є, со Апо́столом Петро́м і про́чими Апо́столи вку́пі, я́ко глаго́ли живота́ ві́чнаго Учи́тель ваш і́мать, і я́ко Он єсть воі́стину Син Бо́га Жива́го, Єму́же вся земля́ єди́ними усти́ взива́ти науча́ється: Аллилу́я."]},{"h":"Ікос 2","ps":["Разу́мному Со́лнцю Пра́вди вседушевно восхоті́л єси́, святи́й Апо́столе Варфоломе́є, порабо́тати і ра́достно прия́л єси́ за́повідь Го́спода о про́повіді овця́м погибшим до́му Ізра́їлева; сего́ ра́ди потща́лся єси́ со всі́ми Апо́столи по весям і градо́м Ізра́їлевим ходя́ще, боля́щия ісціля́ти, прокаже́нния очища́ти, ме́ртвия воскреша́ти, бі́си ізгоня́ти і всім пропові́дати і віща́ти, я́ко прибли́зися Ца́рствіє Небе́сноє. Воспомина́юще апо́стольськія труди́ твоя́, сія́ похва́льная воспису́єм ті:","Ра́дуйся, усе́рдний за́повідей Христо́вих ісполни́телю.","Ра́дуйся, всего́ себе́ Го́сподеві послушно поработи́вий.","Ра́дуйся, я́ко не стяжа́л єси́ ні зла́та, ні сребра́, ні мі́ди при по́ясі своє́м.","Ра́дуйся, я́ко ні пи́ри в путь, ні двою́ ри́зу, ні жезла́ с собо́ю, по за́повіді Христа́, не брал єси́.","Ра́дуйся, я́ко мир Христо́во в до́ми вносил єси́.","Ра́дуйся, я́ко с до́брими до́брі пребива́л єси́.","Ра́дуйся, я́ко от неприявших ми́ра Христо́ва па́ки себі́ мир прийма́л єси́.","Ра́дуйся, я́ко уче́ніє Го́спода своєго́ усе́рдно пропові́дал єси́.","Ра́дуйся, ти бо, по сло́ву Христо́ву, я́ко овча́ посреді́ волко́в с Єва́нгелієм ше́ствовал єси́.","Ра́дуйся, я́ко болі́зні неісці́льния целил єси́.","Ра́дуйся, я́ко духо́в лука́вих ізгонял єси́.","Ра́дуйся, я́ко прокаже́нния очища́л єси́ і ме́ртвия воскрешал єси́.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 3","ps":["Си́ла духо́вная Боже́ственнаго уче́нія всесоверше́нно пліни́ тя, сла́вний Варфоломе́є, сего́ ра́ди никояже сла́дости ми́ра сего́ восхоті́л єси́ вкуша́ти, то́кмо єди́наго і́стиннаго бла́га жела́л єси́ при́сно наслажда́тися, во є́же слу́шати словеса́ Учи́теля своєго́, созерца́ти сла́дкий лик Го́спода своєго́, зрі́ти ди́вноє служе́ніє Єго́ скорб'я́щим і обремене́нним і во ві́ки со всі́ми ізбра́нними Єго́ взива́ти Єму́ а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я бога́тство неізрече́нния бла́гости, Спас ми́ра і Госпо́дь, ві́дий, я́ко при́йде Єму́ час, да пре́йдеть от ми́ра сего́ ко Отцю́, тайноводствова Своя́, су́щия в ми́рі, ученики́, показу́я їм пре́жде Креста́ Своєго́ путь добрі́йший смире́нія, нача́ть умива́ти но́зі друго́м Свої́м і отира́ти ле́нтієм; та́же хліб і вино́ благослови́ Госпо́дь і Та́їнство Причаще́нія в Це́ркві Своє́й на ві́ки утверди́. Сія́ ви́дів святи́й Варфоломе́й с про́чими Апо́столи, всім се́рдцем свої́м вожделі́ Учи́телю своєму́ подража́ти і, в Єго́ воспомина́ніє, Свято́є Та́їнство Причаще́нія при́сно соверша́ти. За таково́є твоєго́ се́рдця благо́є ізволе́ніє ублажа́єм тя, святи́й Апо́столе, восхваленіями си́ми:","Ра́дуйся, до́брий і послушний Христо́в учениче́.","Ра́дуйся, благогові́йний ісполни́телю Христо́вих за́повідей.","Ра́дуйся, я́ко сподо́бился єси́ прия́ти омове́ніє ног свої́х от Го́спода твоєго́ і Учи́теля.","Ра́дуйся, я́ко на Та́йной Ве́чері Ті́ла і Кро́ві Христо́вих приобщи́лся єси́.","Ра́дуйся, Христо́ву тайново́дству научи́вийся.","Ра́дуйся, за́повідь но́вую от Го́спода прия́вий, во є́же ду́шу свою́ положи́ти за дру́ги своя́.","Ра́дуйся, смире́нія Христо́ва і́стинний служи́телю.","Ра́дуйся, сло́вом Христо́вим очище́нний.","Ра́дуйся, за Го́спода і Христа́ жизнь свою́ положи́ти обіща́вий.","Ра́дуйся, любве́ Христо́ви пропові́дниче.","Ра́дуйся, о всем ми́рі те́плий к Бо́гу моли́твенниче.","Ра́дуйся, всіх скорб'я́щих і обремене́нних засту́пниче.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 4","ps":["Бу́ря ве́ліїх смуще́ній на́йде на тя, святи́й Апо́столе, єгда́ ви́діл єси́ Го́спода своєго́ і Учи́теля от преда́теля ле́стію лобзаннаго, в ру́ці лю́тих і беззако́нних суде́й пре́даннаго і на смерть позорную осужде́ннаго; єгда́ же усли́шал єси́ святи́х жен мироно́сиць, ра́достную вість о Воскресе́нії прине́сших, і єгда́ свої́ма очи́ма сподо́бился єси́ зрі́ти воскре́сшаго Го́спода, я́зви Своя́ на пречи́стім ті́лі Своє́м показу́ющаго, тогда́ со всі́ми Апо́столи, печа́ль свою́ на ра́дость преложи́в, воззва́л єси́ велегла́сно Го́споду Христу́, із ме́ртвих воскре́сшему: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шал єси́, сла́вний Варфоломе́є, Боже́ственния глаго́ли Го́спода, по воскресе́нії Своє́м отве́рзшаго Апо́столом ум разумі́ти Писа́нія, я́ко та́ко подоба́ше пострада́ти Христу́ і воскре́снути із ме́ртвих в тре́тій день; ви́діл єси́ Го́спода своєго́ с гори́ Єлео́нськия во сла́ві возне́сшагося і с ра́достію ве́лією возврати́лся єси́ во Ієрусали́м, хваля́ і благослов'я́ Бо́га. За таково́є твоє́ ра́достноє прославле́ніє Го́спода, па́ки во сла́ві гряду́щаго суди́ти живи́м і ме́ртвим, воспіва́єм ті, святи́й Апо́столе, похвали́ сицеви́я:","Ра́дуйся, воскре́сшаго Го́спода ви́діти сподо́бивийся.","Ра́дуйся, гвоздиним я́звам на пречи́стім ті́лі Єго́ усе́рдно поклони́вийся.","Ра́дуйся, я́ко во Христо́вом воскресе́нії уві́рился єси́.","Ра́дуйся, я́ко явле́нієм Єго́ всесладким му́дрості і ра́зума іспо́лнился єси́.","Ра́дуйся, со Христо́м, по воскресе́нії Єго́, о́бщія трапе́зи наслади́вийся.","Ра́дуйся, от Него́ Писа́нія проро́чеськая разумі́ти научи́вийся.","Ра́дуйся, на горі́ Єлео́нстій, я́ко в преддве́рії небе́снім, со Учи́телем свої́м обріти́йся.","Ра́дуйся, благослове́ніє Госпо́днє получи́ти сподо́бивийся.","Ра́дуйся, Боже́ственнаго вознесе́нія свиді́телю.","Ра́дуйся, сві́тлих небожи́телей собесі́дниче.","Ра́дуйся, вели́кия благода́тния ра́дости в день вознесе́нія прича́стниче.","Ра́дуйся, хвали́ і прославле́нія Го́спода сві́тлий істо́чниче.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 5","ps":["Богоглаго́ливий Лу́ка я́вственно всей вселе́нній повіству́єть, я́ко со́бранним во Ієрусали́мі всім ученико́м Христо́вим, внеза́пу бисть шум с небесе́, я́ко носи́му диха́нію бу́рну, і іспо́лни весь дом, іді́же ученици́ Єго́ бя́ху сідя́ще, і яви́шася їм разділе́ни язи́ци, я́ко о́гненнії, сі́де же на єди́ном ко́ємждо їх, і іспо́лнишася всі Ду́ха Свя́та, і нача́ша глаго́лати іни́ми язи́ки, я́коже Дух дая́ше їм провіщава́ти. С про́чими святи́ми Апо́столи Христо́вими в Сіо́нстій го́рниці і ти бил єси́, блаже́нне Варфоломе́є, і да́ра язи́ка сподо́бился єси́ получи́ти, і с ве́лією ра́достію і крі́пким дерзнове́нієм, Ду́хом Святи́м води́мий, научи́лся єси́ іни́ми язи́ки в Тро́йці сла́вимому Бо́гу непреста́нно взива́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Уви́діл єси́, святи́й Апо́столе Варфоломе́є, в павшем ті жре́бії пропові́дати Христо́во Єва́нгеліє в Сирі́ї, Асі́ї і про́чих сосі́дніх страна́х со Апо́столом Филиппом вку́пі, повелі́ніє Самаго́ Го́спода. Сего́ ра́ди тягостних путе́й апо́стольських не убоя́лся єси́, страда́ній за Го́спода Христа́ не устраши́лся єси́ і, ку́пно с Филиппом, єди́наго Го́спода в сих страна́х пропові́дал єси́; тогда́ і Лиді́йськия і Мизійськия гра́ди і ве́сі оглаше́ни би́ша про́повідію апо́стольською. Див'я́щися сим благовестничеським трудо́м твої́м, си́це ра́достно тебі́ глаго́лем:","Ра́дуйся, нелі́ностний ісполни́телю заві́тов Христо́вих.","Ра́дуйся, безбоя́зненний пропові́дниче Христо́ва Єва́нгелія.","Ра́дуйся, я́ко со Апо́столом Филиппом і сестро́ю єго́ Маріямною по градам і весям Асійським і Лидійським с благові́стієм ше́ствовал єси́.","Ра́дуйся, я́ко со Апо́столом Іоа́нном Богосло́вом благода́тними утіше́нії наслажда́лся єси́.","Ра́дуйся, неуста́нний к Бо́гу моли́твенниче.","Ра́дуйся, да́ра любве́ к Бо́гу і лю́дем усе́рдний приумножителю.","Ра́дуйся, покая́нія учи́телю.","Ра́дуйся, смире́нія наста́вниче.","Ра́дуйся, і́долов сокрушителю.","Ра́дуйся, вели́ких Та́їн Бо́жиїх провозві́стниче.","Ра́дуйся, о́гненними словеси́ свої́ми слух язи́чеських люде́й огласи́вий.","Ра́дуйся, ко Христу́ детоводителю їх приле́жний.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 6","ps":["Пропові́дници уче́нія Христо́ва усерднейшії яви́шася святі́ї Варфоломе́й, Фили́пп і блаже́нная Марія́мна, єгда́ со Христо́вим Єва́нгелієм внидо́ша во град фригійський Ієрапо́ль, і́же бі іспо́лнен ме́рзьких і́долов, осліпле́ннії же лю́діє єго́ боготвориша змії́ і єхи́дни. Пе́рвіє святі́ї Апо́столи, со Іоа́нном Богосло́вом вку́пі, ве́лію ехидну моли́твою своє́ю побіди́ша і копіє́м умертви́ша; по́сліжде же день і нощ ко сла́ві Бо́жієй тружда́ющеся, научи́ша мно́гія воспіва́ти ку́пно с ни́ми піснь хвале́бную Го́сподеві: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ оби́льно світ уче́нія Христо́ва во гра́ді Ієраполе, єгда́ святи́й Варфололей, с Филиппом і Маріямною вку́пі, отверзо́ша о́чі ні́коєму Стахію, чети́редесят літ слепотствующему, жену́ Анфипа́та Ієрапо́льськаго, зміє́м угризенную, от одра́ сме́ртнаго воздвиго́ша, єще́ же і мно́гі неду́жния ісціли́ша і бі́сния уврачеваша. Анфипа́ть же злий, я́рости іспо́лнися, єгда́ усли́ша, я́ко жена́ єго́ ві́ру Христо́ву прия́т, повелі́ святи́х Апо́столов лю́тим му́кам преда́ти. Ми же, воспомина́я сія́ сла́вния страда́нія і по́двиги во сла́ву Христа́, восхваля́єм свята́го Апо́стола Варфоломе́я всеусе́рдно:","Ра́дуйся, Ду́ха Свята́го сосу́де вседрагий.","Ра́дуйся, ве́ліїх чуде́с соверши́телю.","Ра́дуйся, сліпи́м зрі́ніє дарова́вий.","Ра́дуйся, хроми́м благошествіє устро́ївий.","Ра́дуйся, от укушенія ядови́тих змій ціли́телю.","Ра́дуйся, бісо́в прогони́телю.","Ра́дуйся, неустраши́мий іспові́дниче всесла́дкаго і́мене Христо́ва.","Ра́дуйся, ку́пно с Филиппом на смерть осужде́нний.","Ра́дуйся, на стіні́ і́дольськаго ка́пища расп'я́тий.","Ра́дуйся, си́лою Бо́жиєю невреди́м сохранивийся.","Ра́дуйся, чудеси́ свої́ми мно́гі ко Христу́ обрати́вий.","Ра́дуйся, Стахия во єпи́скопа Ієрапо́льськаго поста́вивий.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 7","ps":["Хотя́ всі конці́ вселе́нния уче́нієм Христо́вим огласи́ти, святи́й Варфоломе́й, от лю́тих гоне́ній Анфипа́та Ієрапо́льськаго ізба́вленний, с про́повідію Христо́вою, Ду́ха Свята́го повелі́нієм, при́йде во Інді́йськия страни́, іді́же во сла́ву Христо́ву нима́ло вре́мені потруди́ся, ше́ствуя із гра́да во град, із ві́си во весь, благосвествуя мир Христо́в, ісціля́я болі́зні неісці́льния і науча́я лю́ди стран Індійських оста́вити і́доли безсту́дния, єди́ному же Бо́гу, благоді́ющему всім, взива́ти: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вноє благопопеченіє о лю́діх стран Індійських яви́л єси́, святи́й Апо́столе, єгда́ насе́льники стран сих просвіти́в і Це́рков та́мо устро́їв, Єва́нгеліє от свята́го Матфе́я, с собо́ю носи́моє, на язи́к їх преложи́, і са́моє то Єва́нгеліє, от Матфе́я напи́санноє, у ни́хже оста́ви. Сего́ ра́ди просвіще́ннії тобо́ю лю́діє стран Індійських благода́рно воспіва́ху ті, святи́й Варфоломе́є, та́ко:","Ра́дуйся, вели́кий наш Апо́столе.","Ра́дуйся, во Христі́ оте́ць наш чадолюби́вий.","Ра́дуйся, му́ками рожде́нія о нас болезновавий.","Ра́дуйся, Христа́ Го́спода в нас вообрази́вий.","Ра́дуйся, і́дольськую лесть обличи́вий.","Ра́дуйся, ко і́стинному сві́ту вся ни наста́вивий.","Ра́дуйся, словеса́ Єва́нгелія Христо́ва нам оста́вивий.","Ра́дуйся, Це́ркве Бо́жия устрої́телю.","Ра́дуйся, неуста́нний о нас пред Престо́лом Бо́жиїм предстоя́телю.","Ра́дуйся, о всем ми́рі те́плий пред Бо́гом хода́таю.","Ра́дуйся, крі́пкоє на́ше упова́ніє.","Ра́дуйся, о на́шем спасе́нії ізря́дний попечи́телю.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 8","ps":["Стра́нно єсть неверующим сли́шати, ка́ко святи́й Апо́стол Варфоломе́й, сві́том і́стини Христо́ви осія́вий страни́ Інді́йськия, па́ки но́вую ни́ву, Христо́вим уче́нієм невозделанную, обрі́те, і на коне́ць житія́ своєго́ во Вели́кую Арме́нію устреми́ся, да просвіти́ть і зді лю́ди, во тьмі і сі́ні сме́ртній сідя́щия, і да научи́ть їх єди́ному Творцю́ і Го́споду благода́рними усти́ воспіва́ти: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь ду́хом го́ря о сла́ві Госпо́дней, при́йде святи́й Апо́стол Варфоломе́й во Вели́кую Арме́нію і усе́рдно воззва́ в моли́тві своє́й ко Го́споду, да посра́млени бу́дуть бі́си, во і́доліх страни́ тоя́ обита́вшия, і да бу́дуть ниспровергнути безду́шнії і́доли; і не тща бі моли́тва свята́го Апо́стола: бі́си умолко́ша, і́доли падо́ша, лю́діє же сего́ бісо́вськаго мучи́тельства і безу́мія ізба́вльшеся, восхваля́ху свята́го просвіти́теля своєго́ сицеви́ми ра́достними воззва́нії:","Ра́дуйся, Апо́столе, кра́сними нога́ми свої́ми зе́млю на́шу освяти́вий.","Ра́дуйся, святу́ю і́стинную ві́ру всім нам возвісти́вий.","Ра́дуйся, бісо́в ізгонителю.","Ра́дуйся, і́долов сокрушителю.","Ра́дуйся, в моли́тві і дерзнове́нії пламені́ющий.","Ра́дуйся, во святі́м служе́нії Го́споду до́брий примі́р нам показу́ющий.","Ра́дуйся, ди́вний Христо́в благові́стниче.","Ра́дуйся, пресла́вний чудотво́рче.","Ра́дуйся, болі́зні на́ша врачу́ющий.","Ра́дуйся, ско́рби на́ша разгоня́ющий.","Ра́дуйся, всіх нас і́стинно возлюби́вий.","Ра́дуйся, всім нам путь ко спасе́нію показа́вий.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 9","ps":["Всі лю́діє Вели́кия Арме́нії зіло́ удивля́хуся, зря́ще чудеса́ і зна́менія тобо́ю, святи́й Апо́столе, соверша́ємая; єгда́ же ви́діша і́доли па́дшия, ду́хи нечи́стия ізгонимия, сла́вляху Бо́га, ди́внаго во святи́х Свої́х, і воспіва́ху Єму́ благода́рними усти́: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йствующий язи́к челові́чеський не возмо́жеть досто́йно восхвали́ти болі́зні і труди́ твоя́, зна́менія і чудеса́, святи́й Апо́столе, во Вели́цій Арме́нії би́вшая; си́ла же зна́меній сих да́же до царе́ва до́му дости́же, єгда́ із дще́ре царе́вой моли́твою твоє́ю біс ізгна́ся. Єгда́ же цар і всі лю́діє твою́ во Христі́ нелицемі́рную нищету́ узрі́вше, обрати́шася ко Христу́, тогда́ вся Вели́кая Арменія от царе́ва до́му і до обита́лища бі́дних огласи́ся сицеви́ми ра́достними і хвале́бними пі́нії тебі́, вели́кому Апо́столу і чудотво́рцю:","Ра́дуйся, чудотво́рче преди́вний.","Ра́дуйся, всіх боля́щих врачу́ безме́здний.","Ра́дуйся, сла́ву Христо́ву па́че земни́х сокро́вищ возлюби́вий.","Ра́дуйся, о спасе́нії душ челові́чеських прилежавий.","Ра́дуйся, царя́ Полимія, цари́цю і дщер їх ко Христу́ обрати́вий.","Ра́дуйся, і царедворці знатния, і от прости́х люде́й нима́ло святи́м Креще́нієм просвіти́вий.","Ра́дуйся, нищету́ духо́вную і тіле́сную возлюби́вий.","Ра́дуйся, сла́вний безсребрениче.","Ра́дуйся, Вели́кия Арме́нії просвіти́телю.","Ра́дуйся, о́тче наш чадолюби́вий.","Ра́дуйся, ра́йськія две́рі нам отверза́ющий.","Ра́дуйся, от путі́ поги́бельнаго нас ісхищающий.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 10","ps":["Спасе́нію но́вих і но́вих люде́й рабо́тая, дости́гл єси́, святи́й Апо́столе Варфоломе́є, блаже́ннаго конця́ житія́ своєго́: жреци́ бо і́дольстії во Вели́цій Арме́нії ви́дяще, я́ко препитанія своєго́ лишахуся, научи́ша царе́ва бра́та, лю́таго Астіяга, да погуби́ть тя, святи́й Апо́столе. Сей же, неі́стовий, преда́в тебі́ во гра́ді Альбане мно́гим му́кам, повелі́ на кресті́ стремгла́в расп'я́ти тя, да преста́нуть уста́ твоя́ віща́ти уче́ніє Христа́ расп'я́таго; ти же, Апо́столе, і на кресті́ ра́достно взива́л єси́ Го́сподеві: Аллилу́я."]},{"h":"Ікос 10","ps":["Царя́ і Го́спода не преста́л єси́ пропові́дати, святи́й Апо́столе, усти́ свої́ми і ви́ся стремгла́в на кресті́: учи́л бо єси́ со́бранния на позо́р сей лю́ди тве́рдо за ві́ру Христо́ву стоя́ти, согла́сно за́повідем Єва́нгельським жи́ти і неві́рния ко Христу́ привлека́ти. Ми же, див'я́щеся укрепляющей тя си́лі Бо́жієй і твоєму́, святи́й Апо́столе, му́жеству, в похвалу́ тебі́ си́це глаго́лем:","Ра́дуйся, сла́вний Христо́в му́чениче.","Ра́дуйся, Христо́ва уче́нія іспові́дниче дерзнове́нний.","Ра́дуйся, уста́ми свої́ми да́же до сме́рти і́стину Бо́жию пропові́давий.","Ра́дуйся, терпі́нієм свої́м всю вселе́нную удиви́вий.","Ра́дуйся, в сме́ртний час твой ти́сящи люде́й ко Христу́ привлеки́й.","Ра́дуйся, я́вний благода́тния си́ли Христо́ви свиді́телю.","Ра́дуйся, позо́р крестния сме́рті, я́ко побі́дний віне́ць, ра́достно поне́сший.","Ра́дуйся, в час сме́ртних муче́ній свої́х с Го́сподем в єдине́нії преби́вий.","Ра́дуйся, в сме́ртном часі́ ра́йськия сла́дости на землі́ предвкуси́вий.","Ра́дуйся, в сей ра́йстій сла́дости Боже́ственнаго єстества́ і́стинний прича́стниче.","Ра́дуйся, терпі́нія усе́рдний учи́телю.","Ра́дуйся, вся́ких доброді́телей вмісти́лище.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 11","ps":["Пі́ніє всеумиле́нноє прино́сим тебі́, сла́вний Апо́столе Христо́во Варфоломе́є, сме́ртний твой час на дре́ві кре́стнім воспомина́юще, диві́мся твоєму́ свяще́нному за Христа́ заколе́нію, со слеза́ми ублажа́єм твою́ кончи́ну, єгда́ мучи́тель лю́тий повелі́ і ко́жу с твоєго́ честна́го ті́ла содрати; ти же, святи́й Апо́столе, не преста́л єси́ Го́спода восхваля́ти до того́ блаже́ннаго часа́, єгда́ с ко́жею твоє́ю глава́ твоя́, велі́нієм мучи́теля, усі́чена бисть, чи́стая же душа́ твоя́, святи́й Апо́столе, восхище́на бисть на небеса́ воздава́ти сла́ву Го́сподеві і со сві́тлими небожители во ві́ки взива́ти Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світ ве́лій во ісціле́ніє не́мощей челові́чеських возсія́ от честни́х моще́й твої́х, сла́вний Апо́столе, во гра́ді Альбане, єгда́ ві́рнії, взе́мше по кончи́ні твоє́й со креста́ честно́є ті́ло твоє́, во олов'янней ра́ці благогові́йно, вку́пі с главо́ю і ко́жею, положи́ша. Єгда́ же неві́рнії бісо́в служи́теліє узрі́ша, я́ко мно́зі в той страні́ от неві́рних ко Христо́вой Це́ркві прилага́хуся, вверго́ша в мо́ре честни́я мо́щі твоя́: ті́ї же во олов'янней ра́ці, а́ки в легцей ладії́, по вода́м понесошася, до́ндеже пристаху ко о́строву Липару, іді́же єпи́скоп Агафо́н, по Бо́жию открове́нію, с наро́дом і кли́ром с ра́достію сія́ прия́т і во хра́мі благогові́йно поста́ви, воспіва́я тебі́ си́це:","Ра́дуйся, сла́вний Апо́столе Христо́в.","Ра́дуйся, ві́рний самови́дче Бо́га Сло́ва і слуго́ Єго́.","Ра́дуйся, му́дрий Єва́нгелія Христо́ва пропові́дниче.","Ра́дуйся, чуде́с неістощи́мий істо́чниче.","Ра́дуйся, я́ко мо́щі твоя́ от восто́ка і до за́пада і́м'я Госпо́днє восхвали́ша.","Ра́дуйся, я́ко ше́ствієм моще́й твої́х мо́ре освяти́ся.","Ра́дуйся, Сирі́ї і Асі́ї просвіти́телю.","Ра́дуйся, Ієраполя фригійськаго Апо́столе.","Ра́дуйся, я́ко с про́повідію Христо́вою да́же до Інді́ї доше́л єси́.","Ра́дуйся, я́ко насельников брего́в мо́ря Хвалинськаго сві́том Христо́ва уче́нія просвіти́л єси́.","Ра́дуйся, я́ко Вели́кую Арме́нію ко Христу́ приве́л єси́.","Ра́дуйся, я́ко і нас прише́ствієм моще́й твої́х сла́достно уті́шил єси́.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 12","ps":["Благода́ть от Го́спода досто́йно подража́ти житію́ твоєму́ і прославля́ти болі́зні і труди́ твоя́, пода́ждь нам, святи́й Апо́столе, я́коже іногда́ Іо́сифу Піснопи́сцю, єгда́ в на́вечеріє пра́здника твоєго́ яви́лся єси́ єму́ во олтари́ і святи́м Єва́нгелієм благослови́л єси́ єго́, да і ми моли́твами твої́ми, благода́тію Бо́жиєю озареннії, ку́пно со все́ю вселенною Го́сподеві со умиле́нієм взива́єм: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоє́ за Христо́м послі́дованіє, восхваля́єм ди́вная апо́стольськія труди́ твоя́, благогові́йно чтим двукратноє твоє́ за Христа́ расп'я́тіє, ублажа́єм честни́я твоєя́ глави́ отсіче́ніє, сла́вим неісче́тная чудеса́ от честни́х моще́й твої́х і в похвалу́ велегла́сно тебі́ глаго́лем:","Ра́дуйся, про́повідію твоє́ю мно́гі конці́ вселе́нния огласи́вий.","Ра́дуйся, мно́гія лю́ди ко Христу́ приведи́й.","Ра́дуйся, му́дрий Єва́нгелія Христо́ва пропові́дниче.","Ра́дуйся, Христо́вих за́повідей тве́рдий ісполни́телю.","Ра́дуйся, я́ко жи́теліє о́строва Липара і гра́да Беневента, іді́же мо́щі твоя́ почива́ють, я́ко своєго́ Апо́стола тя почита́ють.","Ра́дуйся, я́ко по́двигам твої́м вся вселе́нная диви́ться.","Ра́дуйся, во Христі́ оте́ць наш многопопечительний.","Ра́дуйся, Апо́столе, о на́шем спасе́нії зіло́ рачительний.","Ра́дуйся, я́ко в день Стра́шнаго Суда́ Христо́ва возсядиши на єди́нім от обоюна́десяте престо́лов, да су́диши со Христо́м всю вселе́нную.","Ра́дуйся, я́ко за пра́ведников хода́таєм пред єди́ним Судіє́ю і Го́сподем в той час яви́шися.","Ра́дуйся, сла́вних діл Бо́жиїх возвісти́телю.","Ра́дуйся, злих ко́зней сатани́нських сокрушителю.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 13","ps":["О святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є! Прийми́ сіє́ от нас, недосто́йних, приноси́моє тебі́ хвале́бноє пі́ніє, і я́коже ти сам всім се́рдцем, душе́ю і ті́лом пре́дал єси́ себе́ на служе́ніє Го́сподеві своєму́ і Учи́телю, та́ко і нас, моли́твами твої́ми, сподо́би жизнь свою́ во сла́ву Госпо́дню устроя́ти, вся от Него́ посила́ємая со благодаре́нієм прийма́ти, і та́ко тебі́ подража́юще, ві́чноє Ца́рствіє наслі́довати і Го́сподеві, Творцю́ на́шему і Промисли́телю, с тобо́ю і всі́ми святи́ми во ві́ки воспіва́ти: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Госпо́дь і Спаси́тель всего́ ро́да челові́ча, прови́дів чистоту́ душі́ твоєя́, святи́й Варфоломе́є, благоволи́ ізбра́ти тя во єди́наго от обоюна́десяте і нарещи́ Апо́столом Свої́м. Ми же, див'я́щеся духо́вним дарованіям твої́м, прославля́єм тя си́це:","Ра́дуйся, Варфоломе́є, вели́кий Христо́в Апо́столе.","Ра́дуйся, учениче́ Христо́в усе́рднійший.","Ра́дуйся, я́ко се́рдце своє́ непоро́чно імі́л єси́.","Ра́дуйся, я́ко лука́вия наставле́нія ста́рцев євре́йських отве́ргл єси́.","Ра́дуйся, я́ко всім се́рдцем свої́м Христу́ приліпи́лся єси́.","Ра́дуйся, я́ко вся мирськи́я бла́га ні во что́же вміни́л єси́.","Ра́дуйся, я́ко отця́ і ма́тер, бра́тію і сестри́ своя́ ра́ди Го́спода оста́вил єси́.","Ра́дуйся, я́ко во следованії за Христо́м і́стинноє блаже́нство восприя́л єси́.","Ра́дуйся, уче́нієм Христо́вим пленивийся.","Ра́дуйся, в путі́ Христо́вом бла́го Ца́рствія Небе́снаго предвкуси́вий.","Ра́дуйся, благогласнейший пропові́дниче Христо́ва уче́нія.","Ра́дуйся, ві́рний слуго́ Госпо́день.","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Кондак 1","ps":["Ізбра́нному от люде́й ізра́їлевих во Христо́ва Апо́стола на уловле́ніє челові́ков, чу́дному Варфоломею, пі́нія похва́льная принесе́м, ві́рнії, я́ко оста́вльшему дом свой, нищету́ Христо́ву возлюби́вшему і Христо́во уче́ніє па́че уче́нія євре́йських кни́жников ізбра́вшему. Ти же, святи́й Апо́столе, всіх нас, па́м'ять твою́ честну́ю пра́зднующих, не оста́ви свої́м предста́тельством і заступле́нієм, да благода́рними устна́ми вопіє́м ті:","Ра́дуйся, святи́й сла́вний і всехва́льний Апо́столе Варфоломе́є."]},{"h":"Молитва","ps":["О пресла́вний Апо́столе Христо́во Варфоломе́є, ду́шу за Христа́ предавший і кро́вію твоє́ю па́жить Єго́ удобривший! Усли́ши чад твої́х моли́тви і воздиха́нія, се́рдцем сокруше́нним ни́ні приноси́мия. Се бо беззако́ньми омрачи́хомся, і того́ ра́ди біда́ми, я́коже ту́чами, обложи́хомся, єле́я же до́браго житія́ обнища́хом зіло́, і не возмо́жем проти́витися волко́м хи́щним, і́же расхища́ти наслі́діє Бо́жиє де́рзостно тща́ться. О, си́льний! Понеси́ не́мощі на́ша, не отлуча́йся ду́хом от нас, да не разлучи́мся в коне́ць от любве́ Бо́жия, но крі́пким заступле́нієм твої́м нас защити́, да поми́луєть Госпо́дь всіх нас моли́тв твої́х ра́ди, да істреби́ть же рукописа́ніє безмі́рних гріхо́в на́ших, і да сподо́бит со всі́ми Святи́ми блаже́ннаго Ца́рствія і бра́ка А́гнця Своєго́, Єму́же честь і сла́ва, і благодаре́ніє і поклоне́ніє во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 3","ps":["Апо́столе святи́й Варфоломе́є, / моли́ Ми́лостиваго Бо́га, / да прегріше́ній оставле́ніє // пода́сть душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Яви́лся єси́ ве́ліє со́лнце Це́ркві / уче́ній сія́нієм і чудеси́ стра́шними // просвіща́я пою́щия тя, Варфоломе́є, Госпо́день апо́столе."]},{"h":"Величання","ps":["Велича́єм тя, / апо́столе Христо́во Варфоломе́є, / і чтим болі́зні і труди́ твоя́, ї́миже труди́лся єси́ // во благові́сти Христо́ві."]}],"notes":[]},{"u":"Акафіст святим сорока мученикам Севастійським","e":"Akathist to the Holy Forty Martyrs of Sebaste","secs":[{"h":"Кондак 1","ps":["Ізбра́ннії страстоте́рпці Христо́ви четиреде́сяте, во гра́ді Севасти́йстім чрез огнь і во́ду проше́дшії і в поко́й ві́чний вше́дшії, пі́сньми восхваля́єм вас, засту́пников на́ших. Ви же, я́ко іму́щії ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́те, любо́вію вам зову́щих:","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Ікос 1","ps":["А́нгели Бо́жії, храни́теліє ро́да челові́чеськаго, зря́ще пред мучи́телем дерзновенноє ва́ше іспові́даніє Христа́, на по́двиг страда́льчеський неви́димо вас укріпля́ху. Ми же, ві́дуще вас, по́двиг сей до́брі соверши́вших, ра́достно взива́єм:","Ра́дуйтеся, дерзнове́нним іспові́данієм Христа́ возвеселившії А́нгели;","ра́дуйтеся, ди́вним терпі́нієм ва́шим мучи́телей удиви́вшії.","Ра́дуйтеся, страда́нії ва́шими дия́вола посрами́вшії;","ра́дуйтеся, непобіди́мою си́лою Христо́вою проти́ву неви́димаго врага́ вооружившіїся і вся злохитрости того́ на ви і ко́зні побіди́вшії.","Ра́дуйтеся, неісче́тнаго му́ченичеськаго ли́ка украше́ніє;","ра́дуйтеся, земни́я воїнствующия Це́ркве си́льнії помо́щници.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 2","ps":["Ви́дя зверонравний мучи́тель ві́ру му́чеников, заключи́ їх в темни́цю, Госпо́дь же благоутро́бний я́ві посіти́ Своя́ раби́, похваля́я нача́ток по́двига їх і увіщева́я неосла́бно о́ний соверши́ти. Я́ко то́кмо претерпі́вий до конця́ вінча́ється в Ца́рствії Небе́снім і сподобля́ється со А́нгели пі́ти: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум боже́ственний от я́вльшагося вам Христа́ приі́мше, утверди́стіся в страдальчеськом по́двизі, святі́ї страстоте́рпці, і укори́зну Агриколая мучи́теля в похвалу́ себі́ вміни́сте. Сего́ ра́ди хвале́бно вам вопіє́м:","Ра́дуйтеся, ра́зум пра́вий богові́дінія стяжа́вшії і во́лю свою́ во́лі Бо́жієй всеці́ло преда́вшії;","ра́дуйтеся, вся пре́лести мирськи́я і сла́ву воїнськую ра́ди Христа́ ні во что вміни́вшії.","Ра́дуйтеся, ласка́ній мучи́теля не послу́шавшії і грозних того́ преще́ній не убоявшієся;","ра́дуйтеся, темни́чноє заключе́ніє ра́ди Христа́ претерпі́вшії.","Ра́дуйтеся, Спаси́телем ми́ра во у́зах посещеннії, благи́ми словеси́ от Него́ уті́шеннії і на по́двиг укрепленнії;","ра́дуйтеся, я́ко с ві́рою вас почита́ющих в ско́рбіх утіша́єте і от бід ізбавля́єте.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго соді́ла вас, страстоте́рпці святі́ї, си́льних в сло́ві пред нечести́вими, ті́мже не терп'я́ дерзнове́нія ва́шего, го́рдий мучи́тель па́ки в темни́цю вас вве́рже, в ню́же ра́достно теко́сте, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́ще, страстоте́рпці, в темни́ці сострада́льця ва́шего Киріона бла́га себі́ учи́теля, укреплястеся во ві́рі Христо́вой і по днех осми́х веде́ні би́вше на суди́щі, безбоя́зненно предста́сте Лисі́ю-кня́зю і Агриколаю-воєво́ді, му́дре обличи́сте їх нече́стіє. За таково́є ва́ше дерзнове́ніє прино́сим вам сицеви́я хвали́:","Ра́дуйтеся, в броню́ ві́ри Христо́вой облече́ннії і щито́м благода́ті Єго́ покрове́ннії;","ра́дуйтеся, єди́наго Христа́ па́че всіх возлюби́вшії і ра́ди Єго́ повелі́нія беззако́нная мучи́телей презрі́вшії.","Ра́дуйтеся, си́лу Христо́ву пред нечести́вими пропові́давшії і всемогущество Бо́жиє я́ві показа́вшії;","ра́дуйтеся, я́ко і ка́менная мета́нія вам не прикаса́хуся.","Ра́дуйтеся, я́ко та си́лою Бо́жиєю на метающих я возвраща́хуся;","ра́дуйтеся, я́ко і ни́ні моли́твами ва́шими к Бо́гу вра́жия стрі́ли от нас отражаєте.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 4","ps":["Бу́рею зло́би проти́ву Христа́ диша́, го́рдий Лисій трети́цею вве́рже страда́льцев в темни́цю, в не́йже па́ки Христо́с яви́ся, утіша́я, ободряя їх і нетлі́нния вінці́ в Ца́рствії Небе́снім обіщава́я, они́ же сія́ сли́шавше, ра́достно поя́ху Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше мучи́теліє тве́рдоє страстоте́рпцев Христа́ іспові́даніє, осуди́ша я на всенощноє в хладнем є́зері стоя́ніє, они́ же огнь любве́ Боже́ственния в сердця́х іму́ще, не убояхуся лю́таго мра́за, но, єдиноду́шно сла́в'яще Бо́га, ідо́ша на страда́ніє. Ми же, терпі́нію сих чудя́щеся, зове́м си́це:","Ра́дуйтеся, добропобі́днії Христо́ви іспові́дниці;","ра́дуйтеся, кумирослуженія низложителіє.","Ра́дуйтеся, терпі́нієм лю́таго муче́нія в поко́й ві́чний вше́дшії;","ра́дуйтеся, болі́зньми страда́ній обрі́тшії неізрече́нная бла́га.","Ра́дуйтеся, драгії і крепції четиреде́сяте ка́меніє;","ра́дуйтеся, Це́рков Христо́ву собо́ю укрепляющії і осіявающії.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 5","ps":["Боготечнії зві́зди Христо́ви яви́стеся, святі́ї, в нощні́м хла́ді во є́зері Севасти́йстім сія́ющії, ї́хже не прельсти́ те́плая ба́ня собла́зна, но со А́нгели Бо́гу поя́ху: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше святі́ї, я́ко єди́н от них отпаде́, убоя́вся мра́за нощна́го, і скри́ся в теплой ба́не і а́біє у́мре, те́плі взива́ху ко Го́споду, да їх укріпи́ть в по́двизі страда́нія і просла́вить і́м'я Своє́. Ми же зове́м вам си́це:","Ра́дуйтеся, сла́внії побідоно́сці, вся ко́зні сопроти́вних побіди́вшії;","ра́дуйтеся, всю нощ на́зі во є́зері стоявшії.","Ра́дуйтеся, єдиноду́шно та́мо Го́спода призивавшії;","ра́дуйтеся, я́ко в терпі́нії ва́шем по́мощ ско́рую Госпо́дь низпосла́ вам.","Ра́дуйтеся, я́ко світ Боже́ственний осія́ вас;","ра́дуйтеся, вінці́ пресві́тлії с Небесе́ приявшії.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 6","ps":["Пропові́дници ди́внаго чудесе́, стра́жіє, в ба́ні би́вшії, пові́даша, ка́ко в нощі́ світ Небе́сний во є́зері облиста́ му́ченики, лед растопи́ і хлад в теплоту́ преложи́, є́же сли́шавше, мучи́теліє па́че зло́бою распаляхуся, не ві́дуще Бо́гу пі́ти: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́вшу во є́зері сві́ту Небе́сному, возсія́ і в се́рдці єди́наго от страже́й благода́ть Бо́жия, я́ко той совле́кше ри́зи своя́, вве́ржеся во є́зеро ко святи́м му́чеником, восполня́я мі́сто отпа́дшаго; і та́ко посрами́ся князь тьми, ликовавий о ума́ленії ли́ка страда́льцев, і́мже ми ни́ні вопіє́м такова́я:","Ра́дуйтеся, Христо́ви страстоте́рпці, моли́твами і терпі́нієм ва́шим весе́ліє дия́вола в печа́ль обрати́вшії;","ра́дуйтеся, от зло́би і кова́рства єго́ ві́рния ізбавля́ющії.","Ра́дуйтеся, в хла́ді води́ благода́тію Свята́го Ду́ха просвіти́вшіїся;","ра́дуйтеся, стоя́нієм ва́шим во є́зері ми́сленнаго змі́я главу́ сокруши́вшії.","Ра́дуйтеся, по́лная четиредеся́тниці, Христу́ бо́дренно предста́вшії;","ра́дуйтеся, ві́рою і страда́нієм ра́ди Христа́ блаже́нство ра́йськоє унаследовавшії.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 7","ps":["Хотя́ще чу́днії страда́льці ві́ру во Христа́ непоро́чно сохрани́ти, сла́ву воїнськую і ласка́нія мучи́телей ні во что́же вміни́сте, і вся лю́тая муче́нія, а́ки безпло́тнії, претерпі́сте, пою́ще Бо́гу: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́воє і послі́днєє святі́ї прия́ша муче́ніє, я́ко го́лени їх сокруше́ни млата́ми би́ша, і та́ко сконча́ша по́двиг страда́нія, прия́ша от Бо́га нетлі́нния вінці́. Ті́мже возглаша́єм в похвалу́ їм си́це:","Ра́дуйтеся, прекра́снії лі́торасли са́да Ісу́сова, не сіки́рами, но мла́том посеченнії;","ра́дуйтеся, сосу́ди благода́ті Бо́жієй за і́м'я Христо́во сокруше́ннії.","Ра́дуйтеся, страда́льчеський по́двиг сла́вно сконча́вшії;","ра́дуйтеся, от лико́в А́нгельських в сожи́тельство приятиє.","Ра́дуйтеся, от проро́к і апо́стол, я́ко тіх послі́дователіє, прелюбе́зно сретенниє;","ра́дуйтеся, ро́да христия́нськаго сла́ва вели́кая.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 8","ps":["Стра́нную до́блесть показа́ чу́дная ма́тер свята́го Мелитона, ви́дяще бо тілеса́ му́чеников везома на сожже́ніє, своєго́ же си́на єще́ жива́ су́ща, взя на ра́мена своя́, і той іспусти́ дух свой Бо́гу, поя́: Аллилу́я."]},{"h":"Ікос 8","ps":["Все зверонравіє прояви́ша мучи́телі, єгда́ повелі́ша святи́я тілеса́ му́ченик сожещи́ огне́м і прах їх в реку́ воврещи́, да істреби́ться от землі́ па́м'ять їх, оба́че посрами́шася; Госпо́дь же в ро́ди ві́чния просла́ви я пред А́нгели і челові́ки; сего́ ра́ди зове́м їм:","Ра́дуйтеся, по словесі́ псалмопевця чрез огнь і во́ду проше́дшії;","ра́дуйтеся, страсте́м Христо́вим о́бщници.","Ра́дуйтеся, враго́в Христа́ низложителіє;","ра́дуйтеся, ко Го́споду за христия́ни предста́теліє.","Ра́дуйтеся, ві́рния во правові́рії утверди́вшії;","ра́дуйтеся, неусипния моли́твенниці за род христия́нський.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 9","ps":["Всі христия́не зіло́ удиви́шася, я́ко ко́сті святи́х му́ченик чуде́сно но́щію в ріці́ я́ко зві́зди просія́ша, і, че́стно со́брани, по повелі́нію святи́х, неоску́дния ві́рним ісціле́нія подаю́ть, да поє́м Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́я дре́вній проро́чеськи, Бо́жиїм Ду́хом озаре́нний, о кончи́ні ві́рних во псалти́ри поя́ше: «Проідо́хом сквозі́ огнь і во́ду, і ізве́л ни єси́ в поко́й». Ви же, святі́ї му́ченици, ді́лом сіє́ іспо́лниша. Сего́ ра́ди приймі́те от нас похвали́ сицеви́я:","Ра́дуйтеся, соблю́дшії до конця́ ві́ру Христо́ву;","ра́дуйтеся, страда́нії ва́шими, я́ко зла́то в горни́лі, очистившіїся.","Ра́дуйтеся, предста́теліє великії к Бо́гу, от бід нас спасающії;","ра́дуйтеся, в ско́рбіх нам помога́ющії.","Ра́дуйтеся, ко спасе́нію душ нас наставля́ющії.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 10","ps":["Спасе́нію на́шему споспі́шници єсте́, святі́ї страстоте́рпці, ті́мже усе́рдно к вам прибіга́єм: помозі́те нам ва́шим предста́тельством ко Го́споду остаю́щеє вре́м'я на́шего житія́ в покая́нії проводи́ти і всегда́ благода́рно Бо́гу взива́ти: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіно́ю моли́тв ва́ших оградите́ нас, святі́ї му́ченици, от вся́ких зол і ко́зней вра́жиїх, да охраня́ємі ва́ми, ублажа́єм вас си́це:","Ра́дуйтеся, Киріоне, Кандиде і До́мне, Боже́ственнаго Писа́нія наста́вници;","ра́дуйтеся, Агнине і Ає́тіє сла́внії, на Не́бо ду́хом возлетевшії.","Ра́дуйтеся, Афана́сіє, Аглаїє, Вивія́не і Горго́ніє, Христа́ Бо́га возлюби́вшії;","ра́дуйтеся, Єкдіте, Га́їє, Євноїкіє, Євти́хіє, Дометія́не і Іоа́нне, душі́ своя́ за Христа́ положи́вшії.","Ра́дуйтеся, Іси́хіє, Іра́кліє, Кири́лле, Кла́вдіє, Лисима́хе і Лео́нтіє, небе́сная бла́га получи́вшії;","ра́дуйтеся, Ілія́не і Іліє́, проро́ку Іліє́ поревновавшії.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 11","ps":["Пі́ніє хвале́бноє прино́сим вам, святі́ї му́ченици, я́ко любве́ ра́ди Христо́ви пло́ті своєя́ не пощадисте. Ті́мже і па́м'ять ва́ша, я́ко пресві́тлий світи́льник в Це́ркві сія́єть, ві́рних ду́хом озаря́я, пою́щих Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Сві́том небе́сним осіянних зрим вас, пресла́внії страстоте́рпці Христо́ви, Престо́лу бо Пресвяти́я Тро́йці ви́ну предстоїте́ і о ми́рі моли́тви со дерзнове́нієм прино́сіте; ті́мже хвале́бная вам взива́єм:","Ра́дуйтеся, страстоте́рпці Христо́ви Нико́лає, При́ске, Смара́где, Сакердо́не, Северія́не і Сиси́ніє, зло́би вра́жия побіди́теліє;","ра́дуйтеся, Филоктимоне і Фео́филе, любве́ Боже́ственния соверши́теліє.","Ра́дуйтеся, Худіоне, Ксанфі́є і Фла́віє, во́їни Христо́ви прему́дрії;","ра́дуйтеся, Мелито́не, Феоду́ле і Валенте, раби́ Бо́га пресла́внії.","Ра́дуйтеся, Христо́ви му́ченици Валеріє, Алекса́ндре і Ака́кіє;","ра́дуйтеся, весеннею па́м'ятію ва́шею нам ве́сну Христо́ву возвещающії.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 12","ps":["Благода́тію оби́льно ісполня́ється оби́тель Ксиропотамськая, іму́щи честни́я оста́нки ва́ша, пресла́внії му́ченици і чудотво́рці, ті́мже і нас, па́м'ять ва́шу сві́тло соверша́ющих, благода́ті Бо́жия моли́твами ва́шими ісполняйте, да поє́м чуде́с пода́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще честна́я страда́нія ва́ша, святі́ї му́ченици, прославля́єм Го́спода, вас укріпи́вшаго і вінці́ нетлі́нними вінча́вшаго, і я́ко те́плих засту́пников і хода́таєв за род христия́нський, ублажа́єм си́це:","Ра́дуйтеся, зві́зди Небе́сния от Севасті́ї возсія́вшії;","ра́дуйтеся, я́ко луна́ духо́вная, на Не́бо от землі́ возше́дшії.","Ра́дуйтеся, я́ко со́лнце ми́сленноє, на́ша ско́рби просвіща́єте;","ра́дуйтеся, я́ко в труді́х поста́ і моли́тви нас утіша́єте.","Ра́дуйтеся, четиреде́сяте крепції столпи́ Христо́ви Це́ркве;","ра́дуйтеся, всіх ві́рних храни́теліє і защи́тници.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 13","ps":["О святі́ї страстоте́рпці Севастийстії, ле́сти лука́ваго сла́внії побідоно́сці, предста́тельством ва́шим у Го́спода іспросі́те нам побі́ду на душевре́дния стра́сті і го́рдость жите́йськую, да в покая́нії пожи́вше, Небе́снаго Ца́рствія сподо́бимся, пою́ще Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгели Бо́жії, храни́теліє ро́да челові́чеськаго, зря́ще пред мучи́телем дерзновенноє ва́ше іспові́даніє Христа́, на по́двиг страда́льчеський неви́димо вас укріпля́ху. Ми же, ві́дуще вас, по́двиг сей до́брі соверши́вших, ра́достно взива́єм:","Ра́дуйтеся, дерзнове́нним іспові́данієм Христа́ возвеселившії А́нгели;","ра́дуйтеся, ди́вним терпі́нієм ва́шим мучи́телей удиви́вшії.","Ра́дуйтеся, страда́нії ва́шими дия́вола посрами́вшії;","ра́дуйтеся, непобіди́мою си́лою Христо́вою проти́ву неви́димаго врага́ вооружившіїся і вся злохитрости того́ на ви і ко́зні побіди́вшії.","Ра́дуйтеся, неісче́тнаго му́ченичеськаго ли́ка украше́ніє;","ра́дуйтеся, земни́я воїнствующия Це́ркве си́льнії помо́щници.","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Кондак 1","ps":["Ізбра́ннії страстоте́рпці Христо́ви четиреде́сяте, во гра́ді Севасти́йстім чрез огнь і во́ду проше́дшії і в поко́й ві́чний вше́дшії, пі́сньми восхваля́єм вас, засту́пников на́ших. Ви же, я́ко іму́щії ве́ліє дерзнове́ніє ко Го́споду, от вся́ких нас бід свободи́те, любо́вію вам зову́щих:","Ра́дуйтеся, святі́ї четиреде́сяте му́ченици Севастийстії, пресла́внії чудотво́рці."]},{"h":"Молитва","ps":["О, святі́ї, сла́внії страстоте́рпці Христо́ви, четиреде́сяте, во гра́ді Севасті́ї Христа́ ра́ди му́жественно пострада́вшії, чрез огнь бо і во́ду проідо́сте і, я́ко дру́зі Христо́ви, в поко́й Небе́снаго Ца́рствія вше́дше, і́мате ве́ліє дерзнове́ніє ко пресвяті́й Тро́йце ходатайствовать о ро́ді христия́нськом, найпа́че же о почита́ющих святу́ю па́м'ять ва́шу і с ві́рою і любо́вію вас призива́ющих. Іспросі́те у Всеще́драго Бо́га проще́ніє согріше́ній на́ших і житія́ на́шего ісправле́ніє, да, в покая́нії і нелицемерной любві́ друг ко дру́гу пожи́вше, со дерзнове́нієм предста́нем Стра́шному Суди́щу Христо́ву і ва́шим предста́тельством одесну́ю Пра́веднаго Судії́ предста́нем. Єй, уго́дниці Бо́жії, бу́діте нам защи́тници от всіх враг, ви́димих і неви́димих, да под кро́вом святи́х ва́ших моли́тв ізба́вимся от всіх бід, зол і напа́стей до послі́дняго дне жи́зні на́шея і та́ко просла́вим вели́коє і достопоклоняємоє І́м'я Вседі́тельния Тро́йці, Отця́, Си́на і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 1","ps":["Болі́зньми святи́х, ї́миже о Тебі́ пострада́ша, / умоле́н бу́ди, Го́споди, / і вся на́ша болі́зні ісціли́, // Человіколю́бче, мо́лимся."]},{"h":"Інший тропар, глас 3","ps":["Страстоте́рпці Христо́ви чети́редесяте, / во гра́ді Севасти́йстім му́жественно пострада́вшії, / чрез огнь і во́ду проше́дшії, / в поко́й ві́чний вше́дшії, / молі́теся о нас ко Го́споду / да жизнь ми́рну сохрани́ть // і ду́ші на́ша спасе́ть, я́ко Человіколю́бець."]},{"h":"Кондак, глас 6","ps":["Все во́їнство ми́ра оста́вльше, / на Небесі́х Влади́ці приліпи́стеся, / страстоте́рпці Госпо́дні чети́редесять, / сквозі́ огнь бо і во́ду проше́дше, блаже́ннії, / досто́йно восприя́сте сла́ву с Небе́с // і вінце́в мно́жество."]},{"h":"Величання","ps":["Велича́єм вас, / страстоте́рпці святі́ї чети́редесяте, / і чтим честна́я страда́нія ва́ша, / я́же за Христа́ // претерпі́ли єсте́."]}],"notes":[]},{"u":"Акафіст священномученику Іоанну (Поммеру), архієпископу Ризькому","e":"Akathist to the Hieromartyr John (Pommer), Archbishop of Riga","secs":[{"h":"Кондак 1","ps":["Ізбра́нний архієре́ю, преди́вний уго́дниче Христо́в, Це́ркві Правосла́вний крі́пкоє огражде́ніє, страни́ на́шея хода́таю і засту́пниче, прославля́я просла́вльшаго тя Го́спода, похва́льноє пі́ніє воспису́єм ті; я́ко же імі́яй ве́ліє дерзнове́ніє ко Святі́й Тро́йці, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче і Влади́ко всіх, восхоті́в Це́рков Латвійськую в годи́ну гоне́ній сохрани́ти і лю́дем стра́ждущим утіше́ніє дарова́ти, предизбра, освяти́ і поста́ви тя, святи́телю Іоа́нне, архипа́стиря і пропові́дника Пра́вди оте́честву твоєму́, ми же вопіє́м ті:","Ра́дуйся, землі́ Латвійськия прозябе́ніє свято́є;","ра́дуйся, роди́телей благочести́вих о́трасль пречестна́я.","Ра́дуйся, доброді́телі роди́телей твої́х унаслі́дивий;","ра́дуйся, послуша́нію і трудолю́бію і́ми науче́нний.","Ра́дуйся, от ю́ности ра́зум соверше́нний яви́вий;","ра́дуйся, ізмла́да Христа́ возлюби́вий.","Ра́дуйся, вся за́повіді Госпо́дні непоро́чно сохрани́вий;","ра́дуйся, ве́лій плод духо́вний о Христі́ сотвори́вий.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 2","ps":["Ви́ді суєту́ ми́ра сего́ тлі́ннаго, всім се́рдцем возжелі́л єси́, о́тче Іоа́нне, мир сей оста́вити і во і́ночестві Бо́гу і Це́ркве послужи́ти. Благослове́нієм же і моли́твами свята́го пра́веднаго Іоа́нна Кроншта́дтськаго утвержде́нний, усе́рдно восприя́л сіє́ благо́є і ле́гкоє і́го Христо́во, воспіва́я Творцю́ всіх а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богопросвіще́нний твой ви́ді, Влади́ка Госпо́дь благоволи́ поста́вити тя нача́льника во вертогра́діх духо́вних, да правосла́вния о́троки Богому́дрію і христия́нському благоче́стію научи́ши, собла́зном же богоборчества коле́блемих в разумі́ церковнім утверди́ши. Ми же, от слове́с твої́х і ни́ні вразумля́ємі, вопіє́м ті си́це:","Ра́дуйся, світи́льниче всесветний;","ра́дуйся, пропові́дниче ізя́щний.","Ра́дуйся, і́стиннаго богосло́вія златослове́сний учи́телю;","ра́дуйся, ю́них до́брий наказа́телю і попечи́телю.","Ра́дуйся, страх Бо́жий і нача́ло прему́дрости в сердця́х пасо́мих насади́вий;","ра́дуйся, пра́ведния жи́зні о́браз ві́рним показа́вий.","Ра́дуйся, я́ко твої́м к Бо́гу моле́нієм от врага́ оградивий;","ра́дуйся, твої́м предста́тельством на путь спасе́нія возставля́яй.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 3","ps":["Си́ла благода́ті Бо́жия осіни́ тя, о́тче Іоа́нне, єгда́ святи́тель Михаї́л, болі́знію отягче́н, возжела́ імі́ти тя помо́щника себі́ в труді́х апо́стольських. Ті́мже, собо́р святи́телей возведе́ тя, блаже́нне, в сан єпи́скопський в Ла́врі свята́го благові́рнаго кня́зя Не́вскаго Алекса́ндра. Ти же жезл архипа́стирський, я́ко крест прия́л єси́, к по́двигу ра́ди Христа́ себі́ уготовля́я і поя́ ізбра́вшему тя Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́я в се́рдці своє́м огнь любве́ Боже́ственния, спасе́нія ра́ди душ челові́чеських па́стирськи подвиза́лся єси́, святи́телю Іоа́нне, на кафедрах богоспаса́ємих градо́в Таганрога, Тве́рі і Пензи. Єгда́ же Бо́жиїм попуще́нієм при́йде на Це́рков гоне́ніє лю́тоє, му́жеськи противоста́л єси́ враго́м Христо́вим, нача́ло ісповедничеству своєму́ полага́я. Сего́ ра́ди пі́сньми похва́льними ублажа́єм тя си́це:","Ра́дуйся, Це́ркве Христо́ви ізбра́нний служи́телю;","ра́дуйся, єресе́й, смуть і непра́вди іскорени́телю.","Ра́дуйся, апо́столом поревнова́вий;","ра́дуйся, сосу́де Ду́ха Свята́го.","Ра́дуйся, злострада́нія темничная за Христа́ претерпі́вий;","ра́дуйся, о заблу́ждших от путі́ і́стиннаго мно́го скорбі́вий.","Ра́дуйся, милосе́рдія і долготерпі́нія учи́телю;","ра́дуйся, су́щим в біда́х ско́рий помо́щниче.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 4","ps":["Бу́ря гоне́ній от богобо́рцев возшуме́ на тя, богому́дре Іоа́нне. Ти же, сли́ша в се́рдці твоє́м глаго́л Госпо́день: блаже́нні єсте́, єгда́ поно́сять ви і іждену́ть, і реку́ть всяк зол глаго́л на ви лжу́ще Мене́ ра́ди, в ра́дості ду́ха, пред судія́ми непра́ведними Христа́ му́жеськи іспові́дал єси́, і темни́чноє заключе́ніє, уничиже́ніє і на смерть осужде́ніє без ро́пота претерпі́л єси́, жи́зні ві́чния взиску́я. Ни́ні же со всі́ми святи́ми поє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́ша о тебі́, святи́телю Іоа́нне, правосла́внії лю́діє землі́ твоєя́ оте́чеськия і ві́дяще тя, я́ко святи́теля богоно́сна і па́стиря прему́дра, проси́ша Первосвяти́теля Ти́хона отпусти́ти тя на ка́федру гра́да Рижськаго, волна́ми нестроє́ній обурева́ємую, да іді́же рожде́н єси́ пло́тію, та́мо і духо́вную па́ству обря́щеши от Пастиренача́льника Христа́. Ми же в сем во́лю Бо́жию уразумевающе, вопіє́м ті такова́я:","Ра́дуйся, утіше́ніє всіх градо́в і ве́сей, і́же сподо́бишася тя ви́діти і о тебі́ благослови́тися;","ра́дуйся, всего́ себе́ прине́сша в же́ртву живу́, свя́ту і благоуго́дну Бо́гові.","Ра́дуйся, пра́вди ре́вностний блюсти́телю;","ра́дуйся, благолі́пія церко́внаго усе́рдний рачи́телю.","Ра́дуйся, па́ству твою́ моли́твенно назираяй;","ра́дуйся, с ві́рою к тебі́ притека́ющих проше́нія ісполня́яй.","Ра́дуйся, пасо́мих храни́телю неотсту́пний;","ра́дуйся, всея́ Латвійськия землі́ предста́телю, Бо́гом да́нний.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 5","ps":["Боготе́чной звізді́, возсія́вшей на тве́рди церко́вній, подо́бен бил єси́, досточу́дне о́тче наш Іоа́нне, єгда́ смотре́нієм Бо́жиїм поста́влен бил єси́ на святи́тельстім престо́ле Це́ркві, явля́я в себі́ о́браз му́жа соверше́нна, дара́ми благода́ті Ду́ха, доброді́тельми і ісповедничеством укра́шена. Правосла́внії же лю́діє таково́є о них Промишле́ніє Бо́жиє зря́ще, с ра́достію ве́лією сріта́ху тя, благода́рно пою́ще: Аллилу́я."]},{"h":"Ікос 5","ps":["Внегда́ поста́влен бил єси́, богому́дре о́тче Іоа́нне, на сві́щниці служе́нія святи́тельськаго землі́ оте́чеськия, потща́лся Це́рков правосла́вную, ві́тром гоне́ній коле́блемую, сохрани́ти і утверди́ти; і востину не вотще́ подвиза́лся єси́, я́ко труда́ми твої́ми і ни́ні живе́м і дви́жемся і єсьми́. Сего́ ра́ди ублажа́єм тя, зову́ще:","Ра́дуйся, у корми́ла Це́ркве тве́рдо стоявий;","ра́дуйся, світ Христо́во ві́рним возсія́вий.","Ра́дуйся, душетлі́нному зві́рю ста́до твоє́ расхища́ти не попусти́вий;","ра́дуйся, Це́рков, в гоне́нії су́щую, верной Христу́ сохрани́вий.","Ра́дуйся, ієра́рше му́дрий і благода́тний;","ра́дуйся, пра́вди Бо́жия пропові́дниче велегла́сний.","Ра́дуйся, ді́лателю виногра́да Христо́ва нелі́ностний;","ра́дуйся, моли́твенниче о па́стві твоє́й неуси́пний.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 6","ps":["Пропові́дник слове́с Єва́нгельських: є́же не скрива́ти себі́ сокро́вищ на землі́, не сло́вом то́чію, но і ді́лом яви́лся єси́, святи́телю о́тче наш Іоа́нне, єгда́ в подклеті ка́меннім собо́рнаго хра́ма Рождества́ Христо́ва, а́ки в пеще́рі, в тісноті́ і ску́дости подвиза́лся єси́, смире́нієм висо́кая стяжа́вий і нищету́ і́ночеськую соблюди́й. Ни́ні же в черто́зіх Небе́сних со А́нгели лику́єши, поя́ Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ земле́ на́шей всера́достний світ доброді́телей твої́х, святи́телю о́тче Іоа́нне; труди́ ко трудо́м прилага́я, па́ству твою́ нелі́ностно поуча́л єси́ в і́стинній ві́рі пребива́ти і за́повіді Госпо́дні храни́ти. І ни́ні сві́том богому́дрих поуче́ній твої́х озаря́єши душі́ ві́рних, вопію́щих ті такова́я:","Ра́дуйся, світи́льниче Боже́ственнаго сві́та;","ра́дуйся, моли́тви благово́нноє кади́ло.","Ра́дуйся, ві́рних непрело́жноє утвержде́ніє;","ра́дуйся, неві́рних богому́дроє обличе́ніє.","Ра́дуйся, апо́стольських преда́ній ві́рний храни́телю;","ра́дуйся, Тайн Бо́жиїх і́стинний строї́телю.","Ра́дуйся, я́ко моли́твами твої́ми ко́зні вра́жия низлага́ються;","ра́дуйся, я́ко хода́тайством твої́м боля́щия ісціля́ються.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 7","ps":["Хоті́ніє єди́но імі́л єси́, святи́телю Христо́в, я́же Бо́гу благоугожда́ти і спасе́нію люде́й твої́х служи́ти. Ти же, красоту́ церко́вную возлюби́в, о устроє́нії і обновле́нії хра́мов святи́х, безбожною вла́стію разоренних, і о благоче́стії всеусе́рдно приліжа́л єси́. Пода́ждь і нам, святи́телю Бо́жий, благода́тния си́ли нелі́ностно Бо́гу рабо́тати і Це́ркве Святі́й неуста́нно служи́ти, да вку́пі с тобо́ю сподо́бимся пі́ти Го́споду Сил: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́ваго тя апо́стола і ди́внаго строї́теля Це́ркве Латвійськия ві́ми, святи́телю о́тче Іоа́нне, я́ко во дні сму́ти і разделеній, благовіствова́л мир да́льним і бли́жнім: поуча́я, я́ко во Христі́ Ісу́се ність іуде́й, ні е́ллин, но всі єди́но єсте́. Сего́ ра́ди помози́ і нам, грі́шним, єди́нство ду́ха в сою́зі ми́ра імі́ти, да совоку́плени любо́вію, тебі́ поє́м:","Ра́дуйся, см'яте́нних серде́ць умири́телю;","ра́дуйся, смире́нія і терпі́нія учи́телю.","Ра́дуйся, нача́льствующим правле́нія му́драго о́браз;","ра́дуйся, архієре́єв правосла́вних похвало́.","Ра́дуйся, любо́вію твоє́ю разділе́нная примиря́яй;","ра́дуйся, незло́бієм твої́м строптивия се́рдця покоряяй.","Ра́дуйся, о́тче благосе́рдий, о спасе́нії мно́гих поревнова́вий;","ра́дуйся, не свої́х си, но бли́жняго іска́вий.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 8","ps":["Ве́лію ре́вность о святі́й пра́вді імі́яй, преблаже́нне, противоста́л враго́м Христо́вим; о́гненная словеса́ іспуща́яй, хитросплетенія богобо́рцев разруши́л єси́, заблудшия на путь і́стини наста́вил єси́, Це́рков Правосла́вную от клевети́ і поноше́ній огради́л єси́. Сего́ ра́ди і муже́м борби́ от Патріа́рха Ти́хона нарече́н бил єси́. Ми же, зря́ще такови́є труди́ і по́двиги твоя́, со удивле́нієм вопіє́м о тебі́: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь в Бо́зі бив, дар любве́ боже́ственния стяжа́л єси́, в ней бо ми́лость і і́стина сріто́стіся, пра́вда і мир облобиза́стася, ско́рби же челові́честії єле́єм милосе́рдія твоєго́ утоли́шася. Ми же, неради́вії, мно́гим печа́лем і неду́гом досто́йні яви́хомся, ві́дуще тя помо́щника неуси́пна, умиле́нно вопіє́м ті:","Ра́дуйся, всіх скорб'я́щих і обремене́нних засту́пниче;","ра́дуйся, боля́щих і от нечи́стих духо́в стра́ждущих благода́тний врачева́телю.","Ра́дуйся, ни́щих корми́телю і а́лчущих пита́телю;","ра́дуйся, си́рих защи́тниче і оби́димих предста́телю.","Ра́дуйся, в мо́ре жите́йстім обурева́ємих ти́хоє приста́нище;","ра́дуйся, я́ко душе́вні і тіле́сні ізнемога́ющим о по́мощі к Бо́гу хода́таю.","Ра́дуйся, спаси́тельних благ земни́х і небе́сних ще́дрий пода́телю;","ра́дуйся, от враг ви́димих і неви́димих наде́жний ізба́вителю.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 9","ps":["Всім, в гоне́ніїх і напа́стіх су́щим, о́браз долготерпі́нія і му́жества яви́лся єси́, святи́телю о́тче наш Іоа́нне. Пра́вду Бо́жию защища́я, столп зло́би богопроти́вния обличи́л єси́, ско́рби і клевети́ приє́мля: беззако́нних собо́рище, не могу́ще загради́ти пра́ведная уста́ твоя́, та́йно ко́ви ді́яху, погуби́ти тя поуча́хуся. Ти же, на Го́спода упова́ніє возложи́в, вопія́л: Аллилу́я."]},{"h":"Ікос 9","ps":["Віті́я многовіща́нния не возмо́гуть по достоя́нію ізрещи́ твоєго́ к падшим милосе́рдія, святи́телю Бо́жий, і́бо мно́гажди от люде́й злих нападе́нія і ско́рби претерпіва́я, не ожесточи́л єси́ се́рдце твоє́. Єгда́ же ні́ції от них впадаху в ру́ці твоя́, і́бо крі́постію тіле́сною і ве́лією си́лою от Бо́га наделен бив єси́, ти́я спаси́тельні наказу́я і, кающіяся, с любо́вію прийма́л єси́. Помина́юще у́бо таково́є твоє́ к согрешающим благоснизхожденіє, вопіє́м ті сицева́я:","Ра́дуйся, в кро́тости і смире́нії твоє́м Христу́ Бо́гу подража́вий;","ра́дуйся, незло́бієм твої́м ду́ха зло́би побіди́вий.","Ра́дуйся, крі́пкаго терпі́нія адама́нте;","ра́дуйся, соверше́ннаго му́жа о́бразе.","Ра́дуйся, во́їне Христо́в непоколеби́мий;","ра́дуйся, Крест Христо́во во ору́жіє побі́ди приє́мий.","Ра́дуйся, я́ко сострада́нієм твої́м ско́рби і печа́лі на́ша утоля́яй;","ра́дуйся, я́ко моли́твами твої́ми кающієся грі́шници Ца́рствію Небе́сному приуготовля́ються.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 10","ps":["Спаси́тельнаго твоєго́ по́двига сконча́ніє предзря́, святи́телю Христо́в Іоа́нне, всего́ себе́ в ру́ці Бо́жії пре́дал єси́, наде́жду спасе́нія своєго́ на Него́ Єди́наго возлага́я. І́бо умножившимся враго́м твої́м, бли́жнії твої́ отдале́че тебі́ ста́ша. Ти же, блаже́нне, жертвенною любо́вію Подвигополо́жнику на́шему Ісу́су Христу́ послі́дуя, возше́л єси́ на голго́фу страда́ній твої́х, взива́я побі́дную піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ тве́рда бисть ві́ра і люби́ твоя́ ко Го́споду, богоно́сне о́тче наш Іоа́нне, в ней же утверди́ся се́рдце твоє́, єгда́ лю́діє нечести́вії, ра́зум помраче́нний неві́рієм імі́яху і зло́бою ди́шуще, но́щію в до́му твоє́м ру́ці убийственная на тя возложи́вше, біє́нієм і ра́нами уязвля́ху і огне́м опаляху многострада́льноє ті́ло твоє́, я́ко не би́ти на нем мі́ста ці́ла і неуя́звлена; оба́че му́жества душі́ твоєя́ поколеба́ти не возмого́ша. Див'я́щеся у́бо вели́честву терпі́нія твоєго́, зове́м ті:","Ра́дуйся, страда́нієм іспові́даніє соверши́вий;","ра́дуйся, кро́ве обагре́нієм ри́зу твою́ святи́тельськую украси́вий.","Ра́дуйся, со му́ченики в ра́дость Го́спода твоєго́ вше́дий;","ра́дуйся, і́м'я Христо́во кончи́ною твоє́ю просла́вивий.","Ра́дуйся, за о́вці твоя́ слове́сния ду́шу свою́ положи́вий;","ра́дуйся, град наш Ригу ізлія́нієм кро́ве Твоєя́ освяти́вий.","Ра́дуйся, і по сме́рті лю́б'ящих і чту́щих тя не оста́вивий;","ра́дуйся, о спасе́нії на́шем Бо́га ви́ну умоля́яй.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 11","ps":["Пі́ніє Пресвяті́й Тро́йце па́че іни́х возда́л єси́, священному́чениче Іоа́нне, не сло́вом то́чію і умо́м, но живи́м всего́ себе́ в же́ртву принесе́нієм; подража́я бо расп'я́тому за ни непоро́чному А́гнцю Христу́, положи́л єси́ ду́шу за па́ству твою́; огне́м бо всесожже́гся, во оби́телі го́рняя душе́ю возше́д, со А́нгели поє́ши Бо́гу: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рную свіщу́ во мра́ці житія́ су́щим, зрим тя, Бо́гом прославле́ніє, о́тче наш Іоа́нне, ти бо побідоно́сно путь страда́ній проше́д, от Христа́ увінча́лся єси́. І ни́ні на Небесі́х, у Престо́ла Бо́жия, в со́нмі святи́х о нас при́сно хода́тайствуєши. Ми же, земні́ї, по достоя́нію просла́вити тя не могу́ще і недоумі́нієм об'яти би́вше, вопіє́м ті:","Ра́дуйся, о тебі́ же возра́довашеся А́нгели;","ра́дуйся, єму́же удиви́шася челові́ци.","Ра́дуйся, кова́рства вра́жия обличи́телю;","ра́дуйся, слуг а́дових посрами́телю.","Ра́дуйся, по Бо́зі і Пресвяті́й Богоро́дице все на́ше упова́ніє;","ра́дуйся, во юдо́лі сей земно́й на́ше утіше́ніє.","Ра́дуйся, му́ченичеськаго пресві́тлаго собо́ра сія́ющая звіздо́;","ра́дуйся, Це́ркве Христо́вой ди́вноє украше́ніє.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 12","ps":["Благода́ть ве́лію і щедро́т оби́ліє яви́ Человіколю́бець Госпо́дь Святі́й Це́ркве на́шей, я́ко дарова́ нам тебе́, чудотво́рця но́ваго і моли́твенника богоприя́тнаго, чуде́с благода́ть істоча́юща і неду́ги на́ша врачу́юща. Ті́мже благодари́м тобо́ю благоді́ющаго нам Го́спода і ра́ку моще́й твої́х собо́рні обстоя́ще, с любо́вію к ним притека́юще і Христу́ зову́ще: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще по́двиги твоя́, священному́чениче Іоа́нне, і святи́х моще́й твої́х нетлі́нних обрі́теніє, помина́єм, я́ко єще́ ті живу́ су́щу ізре́к єси́ жела́ніє: по кончи́ні своє́й би́ти погребенним в убозей своє́й пеще́рі в подклеті собо́рнаго хра́ма. Ни́ні же позна́хом, я́ко си́ми словеси́ предре́кл єси́ сла́вноє своє́ прославле́ніє і в собо́р пренесе́ніє. Сего́ ра́ди со умиле́нієм вопіє́м ті:","Ра́дуйся, Пресвяти́я Тро́йці ві́рний іспові́дниче;","ра́дуйся, Пречи́стия Богоро́диці досто́йний ізбра́нниче.","Ра́дуйся, А́нгельських во́їнств собесі́дниче;","ра́дуйся, всіх святи́х свойственниче.","Ра́дуйся, же́ртва Бо́гу благоуха́нная;","ра́дуйся, со сла́вою і че́стію во хра́мі Бо́жиєм положе́нний.","Ра́дуйся, нетлі́нієм просла́вленний;","ра́дуйся, за по́двиги твоя́ на Небесі́ вінча́нний.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 13","ps":["О, вели́кий уго́дниче Бо́жий, священному́чениче Христо́в Іоа́нне, Це́ркві Христо́вой пресві́тлий світи́льниче і те́плий о нас к Бо́гу моли́твенниче! Прийми́ сіє́ хвале́бноє пі́ніє і умоли́ Христа́ Бо́га на́шего Це́рков Святу́ю в ми́рі і благоче́стії сохрани́ти, нам же от вся́ких бід ізба́витися і Небе́снаго Ца́рствія сподо́битися, да с тобо́ю на землі́ живи́х воспоє́м Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелов Тво́рче і Влади́ко всіх, восхоті́в Це́рков Латвійськую в годи́ну гоне́ній сохрани́ти і лю́дем стра́ждущим утіше́ніє дарова́ти, предизбра, освяти́ і поста́ви тя, святи́телю Іоа́нне, архипа́стиря і пропові́дника Пра́вди оте́честву твоєму́, ми же вопіє́м ті:","Ра́дуйся, землі́ Латвійськия прозябе́ніє свято́є;","ра́дуйся, роди́телей благочести́вих о́трасль пречестна́я.","Ра́дуйся, доброді́телі роди́телей твої́х унаслі́дивий;","ра́дуйся, послуша́нію і трудолю́бію і́ми науче́нний.","Ра́дуйся, от ю́ности ра́зум соверше́нний яви́вий;","ра́дуйся, ізмла́да Христа́ возлюби́вий.","Ра́дуйся, вся за́повіді Госпо́дні непоро́чно сохрани́вий;","ра́дуйся, ве́лій плод духо́вний о Христі́ сотвори́вий.","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Кондак 1","ps":["Ізбра́нний архієре́ю, преди́вний уго́дниче Христо́в, Це́ркві Правосла́вний крі́пкоє огражде́ніє, страни́ на́шея хода́таю і засту́пниче, прославля́я просла́вльшаго тя Го́спода, похва́льноє пі́ніє воспису́єм ті; я́ко же імі́яй ве́ліє дерзнове́ніє ко Святі́й Тро́йці, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, священному́чениче Іоа́нне, ско́рий помо́щниче і те́плий к Бо́гу предста́телю."]},{"h":"Молитва","ps":["О, всеблаже́нне святи́й священному́чениче святи́телю о́тче наш Іоа́нне, пра́вди Бо́жия побо́рниче і святи́я правосла́вния ві́ри Христо́вой защи́тниче, хули́телей Святи́я Це́ркве обличи́телю, враго́в прогони́телю, оби́димим покрови́телю і всіх ві́рних христия́н те́плий предста́телю. Ти все́ю душе́ю от ю́ности за́повіді Христо́ви возлюби́л єси́. І во дні гоне́нія лю́таго на ві́ру Правосла́вную, я́ко і́стинний па́стир яви́лся єси́, кре́стний путь проше́д: поруга́ніє, заточе́ніє, оклевета́ніє претерпі́вий і та́ко му́ченичеський віне́ць восприя́л єси́, обрі́тши благода́ть Го́споду моли́тися за ни. Ві́ми, я́ко ти, предстоя́ Престо́лу Вседержи́теля, і́маши ве́ліє дерзнове́ніє в моли́твах пред Го́сподем. І ни́ні смире́нно припа́даєм і усе́рдно мо́лимся: о, ско́рий засту́пниче наш, святи́телю священному́чениче о́тче Іоа́нне, усли́ши нас грі́шних і недосто́йних чад твої́х: умоли́ Всеми́лостиваго Го́спода і Пречи́стую Єго́ Ма́тер Пресвяту́ю Богоро́дицю ві́ру правосла́вную соблюсти́, Святу́ю на́шу Це́рков укріпи́ти в єди́нстві ми́ра і любві́, отпадшия от Святи́я Це́ркве па́ки возврати́ти, страну́ на́шу Латвійськую в ми́рі, христия́нських доброді́теліх і благоде́нствії сохрани́ти. Помози́ нам і ра́зум наш пита́ти не су́єтною му́дростію челові́чеською, но смире́нним позна́нієм во́лі Бо́жия. О, святи́й уго́дниче Бо́жий, не пре́зри нас моля́щихся тебі́: не то́кмо от бід і скорбе́й ізбавле́нія про́сим, но си́ли і тве́рдости, великоду́шія і любве́, даби́ претерпі́ти о́ния напа́сти восстающия на ни. Іспроси́ нам неосла́бноє терпі́ніє до конця́ житія́ на́шего, мир с Го́сподем і гріхо́в на́ших проще́ніє. Єй, святи́й священному́чениче, моли́ Го́спода Бо́га і Спа́са на́шего Ісу́са Христа́ Си́на Бо́жия ізба́витися нам от вся́каго зла і сохрани́ти храм сей, і град, і страну́ на́шу, і лю́ди благоче́стно чтущия тя от вся́кия напа́сти, от болі́зней, гла́да, пото́па, огня́, меча́, наше́ствія іноплеме́нников і междоусо́бния бра́ні, от клевети́ і вся́каго зла́го обстоя́нія. Моли́твами твої́ми святи́ми рассеянния собери́, заблудшия на путь пра́вий наста́ви, ста́рость поддержи́, ю́ния вразуми́, младе́нці воспита́й і всіх нас с любо́вію почита́ющих тя утверди́, да пребу́дем в любве́ друг ко дру́гу, єдиноми́сленно іспові́дуя Отця́ і Си́на і Свята́го Ду́ха, Тро́йцю Єдиносу́щную і Неразді́льную, і та́ко да сподо́бимся Небе́снаго Ца́рствія, іді́же сла́виться Пречестно́є і Великолі́поє І́м'я Пресвято́й і Живонача́льной і Нераздельной Тро́йці. Амі́нь."]},{"h":"Тропар, глас 4","ps":["І нра́вом прича́стник, / і престо́лом намі́стник апо́столом бив, / дія́ніє обрі́л єси́, Богодухнове́нне, / во виді́нія восхо́д, / сего́ ра́ди сло́во і́стини ісправля́я, / і ві́ри ра́ди пострада́л єси́ да́же до кро́ве, / священному́чениче Іоа́нне, / моли́ Христа́ Бо́га // спасти́ся душа́м на́шим."]},{"h":"Кондак, глас 4","ps":["Во святи́теліх благоче́стно пожи́в, / і муче́нія путь проше́д, / і́дольськия угаси́л єси́ же́ртви, / і побо́рник бив твоєму́ ста́ду Богому́дре. / Ті́мже тя почита́юще та́йно вопіє́м ті: / от бід ізба́ви ни при́сно твої́ми моли́твами, // о́тче наш Іоа́нне."]},{"h":"Величання","ps":["Велича́єм тя, / священному́чениче Іоа́нне, / і чтим святу́ю па́м'ять твою́, / ти бо мо́лиши о нас // Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст праведному Симеону Верхотурському","e":"Akathist to the Righteous Symeon of Verkhoturye","secs":[{"h":"Кондак 1","ps":["Ізбра́нному і ди́вному но́вому сиби́рськия страни́ чудотво́рцю всера́достно ни́ні прино́сим ті, свя́те Симео́не, хвале́бная пі́нія; ти же, я́ко імі́яй дерзнове́ніє ко Христу́ Бо́гу, от вся́ких нас бід свободи́, да зове́м ті: Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті і небе́сний челові́к яви́лся єси́, блаже́нний Симео́не, а́нгельськи бо в ми́рі сем пожи́л єси́, ті́мже і а́нгельстії чи́ни удиви́шася непоро́чности твоєго́ житія́ і, по преставле́нії твоє́м, с весе́лієм прия́та пра́ведную твою́ ду́шу; сего́ ра́ди і ми, чудя́щеся висоті́ твоєя́ доброді́телі, прославля́єм тя си́це:","Ра́дуйся, я́ко свя́то і богоуго́дно на землі́ пожи́л єси́;","Ра́дуйся, я́ко по́двигом до́брим зді подвиза́вся, тече́ніє своє́ пра́ведно сконча́л єси́;","Ра́дуйся, я́ко ни́ні пресели́лся єси́ в поко́їща небе́сная;","Ра́дуйся, я́ко в оби́теліх преми́рних, я́же угото́ва Бог лю́б'ящим Єго́, на несконча́ємия ві́ки водворя́єшися;","Ра́дуйся, я́ко Цар ца́рствующих прия́т тя в Небе́сноє Ца́рствіє;","Ра́дуйся, я́ко при́сно со а́нгели в небесі́ обита́єши;","Ра́дуйся, я́ко с проро́ки і апо́столи вселя́єшися;","Ра́дуйся, я́ко с по́стники і преподо́бними торжествова́ти сподо́бился єси́;","Ра́дуйся, я́ко предстої́ши ни́ні со всі́ми святи́ми Престо́лу Бо́жию;","Ра́дуйся, я́ко Пресвяту́ю Тро́йцю несре́дственне зрі́ти сподобля́єшися;","Ра́дуйся, я́ко неізрече́нную сла́ву Госпо́дню я́вственні созерца́єши;","Ра́дуйся, я́ко тоя́ прича́стника би́ти удосто́ї тя Госпо́дь;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 2","ps":["Ви́дя вдови́цю зіло́ плачущую, я́коже бо тогда́ умилосе́рдився, і ізнемо́гшу ті́лом і би́вшу близ коне́чнаго іздиха́нія і очи́ма нима́ло зрі́ти могу́щу, яви́вся ісціли́л єси́, си́це і о мні умилосе́рдися, уго́дниче Бо́жий, і от мно́гих гріхопаде́ній немощствующеє ті́ло моє́ ісціли́ і ду́шу мою́ ко спасе́нію наста́ви, да в ра́дості воззову́ к Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Разумі́ти хотя́щу архієре́ю сиби́рськия страни́ і́м'я твоє́, єгда́ обрі́тени би́ша святи́я твоя́ мо́щі, ти во виді́нії я́влься єму́, о і́мені своє́м возвісти́л єси́; он же, удиви́вся чудеси́ і просла́вив Бо́га, і похва́льния глаго́ли віща́я, вопія́ше тебі́ си́це:","Ра́дуйся, вели́кий пра́ведниче Бо́жий, в чудесі́х просія́вий;","Ра́дуйся, ціле́бниче неду́гов всім, призива́ющим тя с ві́рою;","Ра́дуйся, я́ко і пре́жде проше́нія по́мощію предваря́єши;","Ра́дуйся, я́ко і недоумевающих о прославле́нії нетлі́нних моще́й твої́х чудеси́ твої́ми вразуми́л єси́;","Ра́дуйся, я́ко разсла́бленних укріпи́л єси́;","Ра́дуйся, я́ко сліпи́м прозрі́ніє дарова́л єси́;","Ра́дуйся, хроми́м хожде́ніє устроя́яй;","Ра́дуйся, от бісну́ющихся бісо́в отгнателю;","Ра́дуйся, ско́рбних уті́шителю;","Ра́дуйся, ни́щих і убо́гих покрови́телю;","Ра́дуйся, правосла́вних утвержде́ніє;","Ра́дуйся, єресе́й посрамле́ніє;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 3","ps":["Си́ла Ви́шняго утверди́ тя в житії́ твоє́м свято́м; і ти подвиза́лся єси́ о спасе́нії душі́ твоєя́, труда́ми бо і воздержа́нієм ув'яди́л єси́ плотські́я стра́сті і в непреста́нних моли́твах твої́х всегда́ взива́л єси́ к Бо́гу: Аллилу́я."]},{"h":"Ікос 3","ps":["Імі́яй милосе́рдіє мно́гоє, о призива́ющих тя с ві́рою при́сно мо́лишися к Бо́гу, у Него́ же равноа́нгельним житіє́м твої́м вели́коє дерзнове́ніє стяжа́л єси́; не пре́зри і нас недосто́йних, тре́бующих твоєя́ по́мощі, і я́ко да́ри, прийми́ от нас піснь сію́:","Ра́дуйся, я́ко вся, єли́ка про́сиши от Бо́га, да́руєть ті Госпо́дь;","Ра́дуйся, я́ко моли́тви твої́ о нас, я́коже кади́ло благово́нноє, от Бо́га приємлються;","Ра́дуйся, я́ко возжада́ душа́ твоя́ к Бо́гу крі́пкому;","Ра́дуйся, Христа́ єди́наго возлюби́вий;","Ра́дуйся, я́ко невозвра́тним жела́нієм послі́довал єси́ Єму́;","Ра́дуйся, доброді́тельноє житіє́ всегда́ імі́вий;","Ра́дуйся, возненави́дівий стра́сті ми́ра сего́;","Ра́дуйся, маловре́меннаго утіше́нія на землі́ не іска́вий;","Ра́дуйся, смиренному́дрієм украси́вийся;","Ра́дуйся, тве́рдий адама́нте і сто́лпе непоколеби́мий прило́ги вра́жіїми;","Ра́дуйся, я́ко нетлі́нієм ті́ло твоє́ просла́ви Госпо́дь;","Ра́дуйся, я́ко от гро́ба твоєго́ і персть приє́млющії ісціля́ються;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 4","ps":["Бу́ря недоумі́нія смуща́єть м'я, ка́ко возмогу́ досто́йно воспі́ти чудеса́ твоя́, блаже́нне Симео́не, кто бо мно́гих чудотворе́ній твої́х да́ри по досто́їнству ізрещи́ мо́жеть? Оба́че і аз ди́вно в тебі́ прославля́ющемуся Бо́гу вопи́ти дерза́ю: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавше, блаже́нне і преди́вне Симео́не, о вели́чії чуде́с твої́х, я́ко моли́твами твої́ми су́щих в біда́х і ско́рбіх предваря́єши, ско́ро от них избавля́я, вопіє́м тебі́ такова́я:","Ра́дуйся, ізбавле́ніє на́ше от печа́лей і скорбе́й;","Ра́дуйся, я́ко твої́м предста́тельством да́рується духо́вная благода́ть всім, с те́плою ві́рою к тебі́ притекающим;","Ра́дуйся, я́ко твої́ми моли́твами ко́зні нечи́стих духо́в побіжде́ни;","Ра́дуйся, я́ко і неві́дущим і неслишавшим о прославле́нії твоє́м ісціле́ніє подає́ши;","Ра́дуйся, я́ко ціле́бния да́ри всю́ду то́чиши;","Ра́дуйся, я́ко страну́ сиби́рськую при́сно присіща́єши;","Ра́дуйся, ско́рий оби́димих засту́пниче;","Ра́дуйся, су́щим в лю́тих обстоя́ніїх пособниче і предста́телю;","Ра́дуйся, малоду́шния утіша́яй;","Ра́дуйся, неду́жним крі́пкоє ісправле́ніє;","Ра́дуйся, пліне́нним ско́роє свобожде́ніє;","Ра́дуйся, грі́шним ко спасе́нію наставле́ніє;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 5","ps":["Пресві́тлая звізда́ яви́лся єси́, пра́ведний Симео́не; су́щих бо во тьмі у́мния о́чі озаря́я сві́том Єва́нгелія Христо́ва і избавля́я заблу́ждших от сіте́й зміє́вих і от всіх кова́рств єго́, научи́л єси́ я благода́рственно і всера́достно с ли́ки святи́х ко Христу́ Бо́гу вопи́ти: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше в житії́ твоє́м, блаже́нне, духо́вних по́двигов твої́х висо́кая ісправле́нія, вся́кий ра́зум удивляющая, прославля́єм да́вшаго ті такову́ю благода́ть Бо́га, тебі́ же хвале́бними гла́си си́це вопіє́м:","Ра́дуйся, я́ко юро́д бив Христа́ ра́ди, висоту́ смиренному́дрія стяжа́л єси́;","Ра́дуйся, я́ко стра́нник і пришле́ць на землі́ обрі́лся єси́;","Ра́дуйся, я́ко ни́ні граждани́ном небе́сним би́ти на несконча́ємия ві́ки сподо́бился єси́;","Ра́дуйся, я́ко незло́бивий а́гнець в терпі́нії твоє́м бил єси́;","Ра́дуйся, я́ко кро́тостію ко озлобляющим тя зе́млю живи́х наслі́довал єси́;","Ра́дуйся, чи́стими ду́шу і ті́ло твоє́ сохрани́вий, і ни́ні чи́стим се́рдцем зряй Бо́га;","Ра́дуйся, я́ко му́дрою ми́слію утверди́вий ду́шу твою́ во спасе́ніє;","Ра́дуйся, я́ко с невозвра́тною наде́ждою благ ві́чних преста́вился єси́ к Бо́гу;","Ра́дуйся, я́ко десна́го стоя́нія со ізбра́нними удосто́їлся єси́;","Ра́дуйся, я́ко не скрил єси́ тала́нта, вві́реннаго ті Бо́гом;","Ра́дуйся, благи́й ра́бе і ві́рний, вше́дий в ра́дость Го́спода своєго́;","Ра́дуйся, я́ко ни́ні утіша́єшися, я́коже дре́вній о́ний єва́нгельський Ла́зар, на ло́ні Авраа́мли;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 6","ps":["Пропові́дника богоно́снаго Па́вла віща́ніє і глаго́ли ісполня́я, Симео́не свя́те, юро́дственноє Христа́ ра́ди на землі́ пожи́л єси́ житіє́, і болі́зні мно́гія претерпіва́я, всегда́ благода́рственния Бо́гу возсила́л єси́ хвали́, си́це глаго́ля Єму́: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́л єси́ ве́ліє просвіще́ніє сві́тлостію чуде́с твої́х, пра́ведний Симео́не, от свята́го гро́ба твоєго́ непреста́нно істека́ющих, і тім дале́че отгна́л єси́ тьму єресе́й і раско́лов от окре́стних міст, іді́же в правові́рії і благоче́стії подвиза́лся єси́ і в нетлі́нії тілесі́ почі́єши; ми же, чудя́щеся сим, взива́єм ті си́це:","Ра́дуйся, я́ко яви́лся єси́ во страні́ сиби́рстій крі́пкий защи́тник правосла́вія проти́ву развратников і ху́льников Христо́ви Це́ркве;","Ра́дуйся, я́ко і ни́ні борющимся с ни́ми усе́рдний посо́бник обріта́єшися;","Ра́дуйся, проти́вников Святи́я Це́ркви посрами́телю;","Ра́дуйся, злих волко́в от стада́ Христо́ва отгнателю;","Ра́дуйся, облеки́йся во ору́жіє сві́та; Ра́дуйся, лукавствующих обличи́телю;","Ра́дуйся, правосла́вних ти́хоє приста́нище;","Ра́дуйся, путеше́ствующих благо́є поспіше́ніє;","Ра́дуйся, я́ко і от мно́гія ску́дости твоєя́ разумевал єси́ на ни́ща і убо́га;","Ра́дуйся, я́ко ми́лостив бив при жи́зні, благотвори́ши всім тре́бующим і по сме́рті;","Ра́дуйся, я́ко ізбра́л єси́ до́брая, є́же Бо́га ра́ди тружда́тися;","Ра́дуйся, я́ко на тебі́ іспо́лнися сло́во подви́жничеськоє, болі́зненно, є́же тружда́тися, но блаже́нно восприя́тіє;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 7","ps":["Хотя́щу ні́коєму челові́ку от мно́гих враче́в ісціли́тися от очни́я болі́зні, і єгда́ нічто́же у́спе, прибегшу к тебі́, врачу́ безме́здному, ти о́чі єго́, напо́лнени кро́вію і зрі́ти немогущая, пе́рстію внеза́пу ісціли́л єси́; он же возрадовався, благодаряше тя і, Бо́га прославля́я, рече́: Аллилу́я."]},{"h":"Ікос 7","ps":["Ди́вна тя показа́ нам Творе́ць і Госпо́дь всіх чудотво́рця: єгда́ бо нетлі́нієм просла́ви ті́ло твоє́, тогда́ і земля́ не скри гроб твой і яви́ всім нам, я́ко многоці́нноє сокро́вище; ті́мже і ми чудя́щеся вопіє́м си́це:","Ра́дуйся, цві́те нетлі́нний, в страні́ сиби́рстій прекра́сно процвіти́й;","Ра́дуйся, до́блій подви́жниче благоче́стія, во гра́ді Верхотурстем возсія́вий;","Ра́дуйся, я́ко явля́єшися а́ки дре́во живо́тноє, от него́же неду́гующії получа́ють ісціле́ніє;","Ра́дуйся, я́ко предста́тельством твої́м пред Бо́гом, а́ки вітв благосеннолиственная, покрива́єши нас;","Ра́дуйся, я́ко до́брі вкоренился єси́ во вертогра́ді Христо́ви Це́ркве;","Ра́дуйся, я́ко обильниє плоди́ доброді́телей прине́сл єси́ Бо́гу;","Ра́дуйся, я́ко піє́ши ни́ні во́ду живо́тную от неісчерпа́ємаго істо́чника безсме́ртія;","Ра́дуйся, заблу́ждших наста́вниче;","Ра́дуйся, я́ко кающимся в согріше́ніях іспроша́єши от Бо́га проще́ніє;","Ра́дуйся, і всіх благи́х нам от Него́ хода́таю;","Ра́дуйся, я́ко сві́тлую оде́жду чистоти́ і цілому́дрія до́брі сохрани́в, вшел єси́ в черто́г небе́сний;","Ра́дуйся, я́ко чи́стая душа́ твоя́ к ли́ку Єва́нгельських му́дрих дів сопричтеся і ку́пно с ни́ми (а́нгельськи) водворя́ється в небе́сном черто́зі Жениха́ Христа́;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 8","ps":["Стра́нноє на землі́ житіє́ пожи́в і удали́вся су́єтнаго ми́ра, доброді́тельми к Бо́гу прибли́жился єси́, сего́ ра́ди висо́кий Бог, ви́дя твоє́ смире́ніє, возвели́чи тя Своє́ю благода́тію; Єго́же восхваля́юще, поє́м Єму́ ку́пно с тобо́ю а́нгельськую піснь: Аллилу́я."]},{"h":"Ікос 8","ps":["Весь ум твой во ви́шній Ієрусали́м при́сно простира́я, а́ще ті́лом і на землі́ пребива́л єси́, вся кра́сная ми́ра сего́ возненави́діл і равноа́нгельськоє житіє́ зді пожи́л єси́, Симео́не блаже́нне, тім і от чту́щих тя сли́шиши сія́:","Ра́дуйся, челові́че Бо́жий досточу́дний;","Ра́дуйся, зерца́ло доброді́телей преізящних;","Ра́дуйся, преміни́вий тлі́нная настоя́щая на бу́дущая ві́чная;","Ра́дуйся, уподо́бивийся І́ову терпі́нієм;","Ра́дуйся, селе́ніє честно́є Святи́я Тро́йці;","Ра́дуйся, свя́тче Бо́жий, со всі́ми святи́ми прославля́ємий;","Ра́дуйся, ковче́же, от пото́па гріхо́внаго призива́ющих тя спаса́ющий;","Ра́дуйся, я́ко услаждал єси́ се́рдце твоє́ весе́лієм бу́дущих благ;","Ра́дуйся, воздержа́нієм плоть твою́ ізнури́вий;","Ра́дуйся, я́ко свя́тостію житія́ твоєго́ ми́лость Бо́жию обрі́л єси́;","Ра́дуйся, я́ко непреста́нними моли́твами о нас Бо́га умилостивлявши;","Ра́дуйся, я́ко благи́м наде́ждам твої́м ісполне́ніє прия́л єси́;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 9","ps":["Все мно́жество челові́чеськоє удиви́ся є́же на землі́ во пло́ті твоєму́ терпі́нію і незло́бію, непоро́чна і пра́ведна тя зря́ще, і ни́ні ми́лостивим твої́м предста́тельством в ско́рбіх нас не оставля́юща; ті́мже і ми, ра́дующеся, к Бо́гу поє́м піснь: Аллилу́я."]},{"h":"Ікос 9","ps":["Виті́ї многовіща́нния ізнемого́ша по досто́їнству пові́дати мно́гоє твоє́ терпі́ніє і те́плую ко Христу́ любо́в; аз же многогрі́шний ка́ко возмогу́ ізглаго́лати равноа́нгельноє твоє́ житіє́ і пресла́вная чудеса́! Но оба́че дерза́ю, наді́яся на твоє́ беззло́біє, вопи́ти тебі́ си́це:","Ра́дуйся, я́ко а́нгелом подо́б'яся, ви́ну пуща́л єси́ на не́бо о́чі твоєго́ се́рдця;","Ра́дуйся, я́ко до́блими твої́ми по́двиги спасе́ніє і віне́ць нетлі́нний от Христа́ Бо́га прия́л єси́;","Ра́дуйся, я́ко на всяк день і на вся́ку нощ славосло́вил єси́ Творця́ вся́чеських;","Ра́дуйся, я́ко побіди́л єси́ дия́вола смире́нієм свої́м;","Ра́дуйся, я́ко нищ ті́лом і ду́хом бил єси́ на землі́, сего́ ра́ди угото́ва ті Госпо́дь Ца́рство Небе́сноє;","Ра́дуйся, кро́тости ра́ди твоєя́ наслі́дивий зе́млю обітова́нія;","Ра́дуйся, я́ко і іни́х, зря́щих твою́ свя́тость, научи́л єси́ пра́ведно жи́ти;","Ра́дуйся, я́ко душе́вния стра́сті іспепеляєши;","Ра́дуйся, я́ко тіле́сния болі́зні врачу́єши;","Ра́дуйся, я́ко і многовре́менния неду́ги от челові́к отгоня́єши;","Ра́дуйся, я́ко су́щим близ коне́чнаго іздиха́нія здра́віє да́руєши;","Ра́дуйся, я́ко і от смертоно́сних язв свобожда́єши;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 10","ps":["Спасе́ніє восхоті́в да́ти Госпо́дь лю́дем Свої́м, сві́тлаго світи́льника всім нам даде́ тебі́, точа́ща благода́ть цільби́ всім, притекающим к ра́ці моще́й твої́х; і ми, получи́вше ми́лость от безме́зднаго тя врача́, благода́рними гла́си восхваля́юще Бо́га, поє́м піснь: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́ єси́ ти і покро́во всім притекающим к тебі́, пра́ведний Симео́не, і́бо Госпо́дь просла́ви тя, украси́в нетлі́нієм і чудеси́ і приглаша́ти тебі́ научи́:","Ра́дуйся, сто́лпе непоколеби́мий правосла́вія;","Ра́дуйся, сокро́вище неоску́дно мно́гих ісціле́ній;","Ра́дуйся, пода́телю просящим у тебе́ я́же на по́льзу;","Ра́дуйся, уцілому́дривий живу́щия сту́дно;","Ра́дуйся, наказа́телю помраче́нних умо́м;","Ра́дуйся, учи́телю смиренному́дрія і терпі́нія;","Ра́дуйся, я́ко в со́ніях явля́яся, науча́єши до́брому житію́;","Ра́дуйся, звіздо́, чуде́сно возсія́вшая в сиби́рстій страні́;","Ра́дуйся, я́ко луча́ми чудотворе́ній твої́х просвіща́єши і далечайшия страни́;","Ра́дуйся, я́ко ні́когда незна́єм, ни́ні же со сла́вою познава́єшися от всіх і́щущих тя;","Ра́дуйся, я́ко рибаре́м бив, соді́лался єси́ ловце́м челові́ков;","Ра́дуйся, я́ко хода́тайством твої́м к Бо́гу мук ві́чних свобожда́єши нас;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 11","ps":["Пі́ніє умиле́нноє приношу́ ті, недосто́йний, і вопію́ со слеза́ми: хода́тайствуй за м'я при́сно к Бо́гу, душе́ю і ті́лом от страсте́й, вою́ющих на м'я, лю́ті неду́гующаго, і пода́ждь мі моли́твами твої́ми ісціле́ніє і гріхо́в ізбавле́ніє, от се́рдця тебі́ сія́ принося́щему, да і аз в ра́дості воспою́ прославля́ющему тя Бо́гу піснь: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоприє́мную свіщу́ зрим тя, богому́дре Симео́не: невеще́ствен-ним бо любве́ огне́м возже́глся єси́ і наставля́єши к боже́ственному дія́нію вся, о́бразом житія́ твоєго́, я́ко заре́ю, просвіща́я чу́вства на́ша; ті́мже і досто́їн єси́ зва́нієм почитатися сим:","Ра́дуйся, луче́ пресві́тлая, от Со́лнця Христа́ возсія́вшая;","Ра́дуйся, світи́ло благоче́стія немерцающеє","Ра́дуйся, я́ко світ прему́дрости Бо́жия просвіти́ ду́шу твою́;","Ра́дуйся, я́ко ві́чнаго сего́ сві́та луче́й чрез тебі́ і ми сподобля́ємся;","Ра́дуйся, безме́здний врачу́;","Ра́дуйся, я́ко істоча́єши оби́льния струї́ ісціле́ній;","Ра́дуйся, благонаде́жний о нас предста́телю і моли́твенниче пред Престо́лом Госпо́днім;","Ра́дуйся, спаси́тельноє приста́нище всім, притекающим к тебі́;","Ра́дуйся, я́ко су́щим в пучи́ні скорбе́й добр обріта́єшися ко́рмчий;","Ра́дуйся, те́плий засту́пниче су́щим во обстоя́ніїх лю́тих;","Ра́дуйся, благоуха́ніє духо́вноє істоча́яй от многоціле́бних твої́х моще́й;","Ра́дуйся, єле́єм ра́дованія ісціля́яй ско́рби душе́вния ві́рою моля́щихся тебі́;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 12","ps":["Благода́ть преве́лію даде́ тебі́ Госпо́дь неду́жних болі́зні врачева́ти, де́мони прогоня́ти і стра́сті ціли́ти; ті́мже не забу́ди і нас, усе́рдно призива́ющих тя во вре́м'я ті́сних обстоя́ній і тя́жких напа́стей, і моли́твами твої́ми от о́них ізба́ви, да благода́рно вопіє́м к Бо́гу: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще твоя́ чудеса́, пра́ведний Симео́не, ві́рою несомні́нною притека́єм к многоціле́бним і святи́м моще́м твої́м, і припа́дая к ним, с любо́вію і стра́хом лобиза́єм о́ния. Ти же, о свя́тче Бо́жий! Я́ко благоутро́бний, принеси́ моле́ніє ко Влади́ці, да сподо́бит нас десна́го стоя́нія на суді́ Своє́м, вопію́щих к тебі́ сицева́я:","Ра́дуйся, вели́кий Христо́в уго́дниче;","Ра́дуйся, моли́твенниче усе́рдний о воспіва́ющих тя;","Ра́дуйся, Бо́жий ізбра́нниче, благода́тію Ду́ха Свята́го приосіне́нний;","Ра́дуйся, пра́ведниче, возвеселивийся о Го́споді;","Ра́дуйся, я́ко мзда твоя́ мно́га на небесі́х;","Ра́дуйся, предста́телю наш ско́рий і те́плий;","Ра́дуйся, хода́таю неуси́пний о нас пред Бо́гом;","Ра́дуйся, і́го благо́є і бре́м'я ле́гкоє понеси́й;","Ра́дуйся, за труди́ твоя́ і по́двиги на землі́ ві́чноє упокоє́ніє обріти́й на небесі́;","Ра́дуйся, я́ко вре́менних і ві́чних благ от Бо́га нам при́сно про́сиши;","Ра́дуйся, о ка́ющихся споручниче пред Бо́гом;","Ра́дуйся, кади́ло благово́нноє, облагоуха́ющеє чту́щих тя;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 13","ps":["О пречу́дний і ми́лостивий но́вий чудотво́рче, пра́ведний Симео́не! Прийми́ ни́ні ма́лоє сіє́ моле́ніє на́ше і принеси́ є ко Христу́ Бо́гу на́шему, да сохрани́ть нас от враг ви́димих і неви́димих, от наше́ствія іноплеме́нник, от неду́га і гла́да, от вся́кия ско́рби і внеза́пния сме́рти і бу́дущаго ві́чнаго муче́нія ізба́вить, моли́твами твої́ми, всіх вопію́щих к Нему́: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгел во пло́ті і небе́сний челові́к яви́лся єси́, блаже́нний Симео́не, а́нгельськи бо в ми́рі сем пожи́л єси́, ті́мже і а́нгельстії чи́ни удиви́шася непоро́чности твоєго́ житія́ і, по преставле́нії твоє́м, с весе́лієм прия́та пра́ведную твою́ ду́шу; сего́ ра́ди і ми, чудя́щеся висоті́ твоєя́ доброді́телі, прославля́єм тя си́це:","Ра́дуйся, я́ко свя́то і богоуго́дно на землі́ пожи́л єси́;","Ра́дуйся, я́ко по́двигом до́брим зді подвиза́вся, тече́ніє своє́ пра́ведно сконча́л єси́;","Ра́дуйся, я́ко ни́ні пресели́лся єси́ в поко́їща небе́сная;","Ра́дуйся, я́ко в оби́теліх преми́рних, я́же угото́ва Бог лю́б'ящим Єго́, на несконча́ємия ві́ки водворя́єшися;","Ра́дуйся, я́ко Цар ца́рствующих прия́т тя в Небе́сноє Ца́рствіє;","Ра́дуйся, я́ко при́сно со а́нгели в небесі́ обита́єши;","Ра́дуйся, я́ко с проро́ки і апо́столи вселя́єшися;","Ра́дуйся, я́ко с по́стники і преподо́бними торжествова́ти сподо́бился єси́;","Ра́дуйся, я́ко предстої́ши ни́ні со всі́ми святи́ми Престо́лу Бо́жию;","Ра́дуйся, я́ко Пресвяту́ю Тро́йцю несре́дственне зрі́ти сподобля́єшися;","Ра́дуйся, я́ко неізрече́нную сла́ву Госпо́дню я́вственні созерца́єши;","Ра́дуйся, я́ко тоя́ прича́стника би́ти удосто́ї тя Госпо́дь;","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Кондак 1","ps":["Ізбра́нному і ди́вному но́вому сиби́рськия страни́ чудотво́рцю всера́достно ни́ні прино́сим ті, свя́те Симео́не, хвале́бная пі́нія; ти же, я́ко імі́яй дерзнове́ніє ко Христу́ Бо́гу, от вся́ких нас бід свободи́, да зове́м ті:","Ра́дуйся, Симео́не, чудотво́рче преди́вний."]},{"h":"Молитва","ps":["О святи́й і пра́ведний Симео́не, чи́стою душе́ю твоє́ю в Небе́сних оби́теліх в ли́ці святи́х водворя́яйся, на землі́ же с на́ми неотсту́пно пребива́яй! По да́нній ті благода́ті от Го́спода моли́тися о нас, ми́лостивно при́зри на нас многогрі́шних, а́ще і недосто́йні, оба́че с ві́рою і упова́нієм к тебі́ притека́ющих, і іспроси́ нам от Бо́га проще́ніє согріше́ній на́ших, в ня́же впада́єм мно́жицею во вся дні житія́ на́шего. І я́коже пре́жде о́вим у́бо, от о́чния зі́льния болі́зні ні ма́ло зрі́ти могу́щим ісціле́ніє оче́с, о́вим же близ сме́рти би́вшим от лю́тих неду́гов врачева́ніє, і іни́м іна́я мно́гая пресла́вная благодія́нія дарова́л єси́: си́це ізба́ви і нас от неду́гов душе́вних і тіле́сних і от вся́кия ско́рби і печа́лі, і вся блага́я к настоя́щему житію́ на́шему і к ві́чному спасе́нію благопотре́бная нам от Го́спода іспроси́, да та́ко твої́м предста́тельством і моли́твами стяжа́вше вся нам поле́зная, а́ще і недосто́йнії, благода́рні восхваля́юще тя, просла́вим Бо́га, ди́внаго во святи́х Свої́х, Отця́, і Си́на, і Свята́го Ду́ха, ни́ні і при́сно і во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Мирська́го м'яте́жа бі́гая, все жела́ніє обрати́л єси́ к Бо́гу, / да во виді́нія восхо́д обря́щеши го́ре, / отню́дуже не уклони́вся в лука́вствія се́рдця, / но очи́стив ду́шу і ті́ло, / прия́л єси́ благода́ть точи́ти цільби́ ві́рним і неві́рним, / притека́ющим к тебі́, пра́ведний Симео́не. / Ті́мже, по да́нному ті да́ру, / іспроси́ у Христа́ Бо́га ісціле́ніє нам, боля́щим душе́вними страстьми́, // і моли́ спасти́ ду́ші на́ша."]},{"h":"Кондак, глас 2","ps":["Ми́ра су́єтнаго отве́рглся єси́, / да бла́га ві́чния жи́зні наслі́диши, / возлюби́в незло́біє і чистоту́ душі́ і ті́ла. / Сниска́л єси́, є́же возлюби́л, / свиді́тельствують бо о сем гроб і нетлі́ніє моще́й твої́х, / і благода́ть чудотворе́нія найпа́че. / То́чиши бо цільби́ всім притекаю́щим к тебі́ і непросвіще́нним, / Симео́не блаже́нне, // чудотво́рче преди́вний."]},{"h":"Величання","ps":["Велича́єм тя, святи́й пра́ведний Симео́не, і чтим святу́ю па́м'ять твою́, ти бо мо́лиши за нас Христа́ Бо́га на́шего."]}],"notes":[]},{"u":"Акафіст блаженній Євфросинії Колюпановській","e":"Akathist to the Blessed Euphrosyne of Kolyupanovo","secs":[{"h":"Кондак 1","ps":["Ізбра́нной Бо́гом от палать ца́рських в Небе́сний Черто́г Ра́йський; блаже́нній старице Євфроси́нії, Христа́ ра́ди юродивей, я́ко покрови́тельнице на́шей і моли́твеннице похва́льноє принесе́м пі́ніє. Ти же, блаже́нная ма́ти, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід і болі́зней свободи́, с любо́вію зову́щих ті:","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Ікос 1","ps":["А́нгелом храни́телем ко спасе́нію наставля́єма, ю́ная княжна́ В'яземськая, презрі́в ро́скош і бога́тство, сла́ву і знатность і вся пре́лести су́єтнаго ми́ра сего́, оста́вила єси́ ца́рський дворець, вступив на у́зький і терни́стий путь, веду́щий в Ца́рство Небе́сноє. За сіє́ прийми́ от нас, блаже́нная, похвали́ сія́:","Ра́дуйся, я́ко Бо́га ра́ди із палать ца́рських ісшла єси́;","ра́дуйся, я́ко ра́ди спасе́нія душі́ своєя́ вся земна́я презрі́ла єси́.","Ра́дуйся, я́ко самопроізво́льную нищету́ ра́ди Христа́ ізбра́ла єси́;","ра́дуйся, я́ко бога́тство нетлі́нноє і ві́чноє обріла́ єси́.","Ра́дуйся, я́ко Небе́сному Жениху́ Христу́ уневісти́лася єси́;","ра́дуйся, я́ко с му́дрими ді́вами в Черто́г Єго́ Небе́сний вошла́ єси́.","Ра́дуйся, чи́стая голуби́це Христо́ва;","ра́дуйся, непоро́чная А́гнице Бо́жия.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 2","ps":["Ви́дяще, я́ко неудо́бно єсть среді́ собла́зн і суєти́ мирсько́й, в роскошних пала́тах ца́рських спасти́ся, тріє́ фрейлини цари́ці Єкатери́ни II (Саломія, Ма́рфа і Євфроси́нія) та́йно ізидо́ша із дворця (я́ко дре́вле пра́ведний Лот із Содо́ма гріхо́внаго), воспіва́я призва́вшему їх Го́споду хвале́бную піснь: Аллилу́я."]},{"h":"Ікос 2","ps":["Ра́зум богому́дрий стяжа́в, му́дрия ді́ви, послі́дуя Єва́нгельським слова́м Спаси́теля, вся Єго́ ра́ди оста́вили єсте́, і совлекшись риз свої́х многоці́нних, на бре́зі пруда оста́вили єсте́ їх, да забве́на бу́деть па́м'ять о них. І обле́кшеся в нищетния ру́бища, ізидо́ша странници Бо́жия, послі́дуя Го́споду, не імевшему гді глави́ приклонити; сего́ ра́ди зове́м ті, ма́ти:","Ра́дуйся, совлекшись оде́жд свої́х, ве́тхаго челові́ка совлекла́ся єси́;","ра́дуйся, рубищним одія́нієм, я́ко ри́зою спасе́нія облекла́ся єси́.","Ра́дуйся, для ми́ра і ле́стних пре́лестей Єго́ умерла́ єси́;","ра́дуйся, я́ко для ві́чния жи́зні душе́ю воскресла єси́.","Ра́дуйся, роди́телей і дру́ги оста́вила єси́;","ра́дуйся, я́ко всім се́рдцем Бо́га возлюби́ла єси́.","Ра́дуйся, я́ко сего́ ра́ди сожи́тельницею А́нгелов сподо́билася би́ти єси́;","ра́дуйся, я́ко в ли́кі дів святи́х Цари́це Небе́сній предстої́ши днесь.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 3","ps":["Си́лою, да́нною ті сви́ше, блаже́нная, і́го благо́є Сладча́йшаго Го́спода на́шего Ісу́са Христа́ на ся с ра́достію возложи́ла єси́, і облекшись в А́нгельський о́браз, в Серпуховськой монасти́р всели́лася єси́, ви́ну поя́ с і́ночествующими ді́вами Небе́сному Жениху́ Христу́: Аллилу́я."]},{"h":"Ікос 3","ps":["Іму́щи ве́лію любо́в ко Го́споду, плоть свою́, Євфроси́ніє, расп'я́ла єси́ со страстьми́ і похотьми́, бді́нієм і труда́ми, посто́м і воздержа́нієм, нестяжа́нієм і смире́нієм. Сего́ ра́ди і всели́ся в тя Дух Святи́й, наставля́я нас, грі́шних, ублажа́ти тя си́це:","Ра́дуйся, я́ко цари́цю земну́ю оста́вила єси́;","ра́дуйся, я́ко покро́ва Цари́ці Небе́сній сподо́билася єси́.","Ра́дуйся, я́ко із пучи́ни собла́зн ми́ра сего́ неврежде́нно ізшла́ єси́;","ра́дуйся, сіть іскуше́ній бісо́вських, я́ко паучи́ну расто́ргла єси́.","Ра́дуйся, смире́нієм, я́ко ца́рською порфи́рою оді́янная;","ра́дуйся, благода́тію Ду́ха Свята́го облагоуханная.","Ра́дуйся, ві́рою крі́пкою і живо́ю вооруженная;","ра́дуйся, крестним зна́менієм і моли́твою огражде́нная.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 4","ps":["Бу́ря гоне́ній і іскуше́ній на́йде на тя, ма́ти, єгда́ ігуменія монастиря́ повелі́ла єси́ уби́ти собак, їх же ти в своє́й хи́жині імі́ла єси́. Смиря́я себі́, с ни́ми на голом по́лу возлегала єси́ і, наказу́я себ'я́ за арома́ть духо́во во дворці, злосмра́діє от них терпі́ла єси́. І покинув монасти́р, ісшла єси́, возлага́я упова́ніє своє́ на Бо́га, в ско́рбі се́рдця взива́я к Нему́: Аллилу́я."]},{"h":"Ікос 4","ps":["Сли́шавши глас Апо́стольський: «Ми у́бо бу́ї Христа́ ра́ди... І а́ще кто мни́ться мудр би́ти во вас во ві́ці сем, буй да бива́єть, я́ко да прему́др бу́деть» (1 Кор. 3, 18-19), блаже́нная Євфроси́ніє, високого ума́ і образова́нія, всю му́дрость челові́чеськую в нічто́ вміни́ла єси́, восприя́в на ся юро́дство Христа́ ра́ди, смире́нно терп'я́щи поруга́нія і осменія людські́я. Ізумляясь сим по́двигом твої́м, возглаша́єм ті, сія́:","Ра́дуйся, я́ко Апо́стольському наставле́нію послі́довала єси́;","ра́дуйся,я́ко му́дрость ві́ка сего́ в бу́йство вміни́ла єси́.","Ра́дуйся, я́ко Прему́дрость Бо́жию Христа́ возлюби́ла єси́;","ра́дуйся, насмешкам і поруганієм людськи́м, я́ко царскиїм утварями себі́ украшала єси́.","Ра́дуйся, біє́ніє і оплева́ніє, я́ко я́зви Христо́ви на ті́лі своє́м носи́ла єси́;","ра́дуйся, я́ко умерщвля́я ті́ло, на локтях в нощі́ почивала єси́.","Ра́дуйся, я́ко тяжелиє вери́ги на себі́ возложи́ла єси́;","ра́дуйся, я́ко сим стра́сті плотські́я ув'яди́ла єси́.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 5","ps":["Боготе́чній звізді́ уподо́билася єда́, ма́ти честна́я, проходя́ мно́гія ві́си і селе́нія, із Серпухова в село́ Колюпаново близ гра́да Але́ксина переселилася єси́, свої́м благоче́стієм і душеполезними наставленіями приводя́ мно́гих ко спасе́нію, да сла́виться всю́ду і́м'я Святи́я Тро́йці: Отця́ і Си́на і Свята́го Ду́ха кра́сним пі́нієм: Аллилу́я."]},{"h":"Ікос 5","ps":["Ви́дівше лю́діє гра́да Але́ксина і окрестностей єго́ ангелоподо́бноє житіє́ блаже́нной ста́риці і благода́тния да́ри прозорливости і ісціле́нія неду́гов, Бо́гом єй данниє, потеко́ша к ней со свої́ми скорб'ями і ну́ждами, с болі́знями душе́вними і тіле́сними. І получи́в по́мощ, сла́в'ять свою́ благоді́тельницю та́ко:","Ра́дуйся, я́ко дар благода́тний прозрі́нія от Бо́га прия́ла єси́;","ра́дуйся, я́ко тім мно́гих от путі́ нече́стія отврати́ла єси́.","Ра́дуйся, ціли́тельнице язв душе́вних;","ра́дуйся, враче́бниці болі́зней тіле́сних.","Ра́дуйся, скорб'я́щих уті́шительнице;","ра́дуйся, о душа́х усо́пших усе́рдная моли́твеннице.","Ра́дуйся, ма́терей дітородя́щих ско́роє разріше́ніє;","ра́дуйся, діте́й боля́щих врачева́ніє.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 6","ps":["Пропові́дниця Єва́нгельських і́стин яви́лася єси́ блаже́нная, пра́ведним житіє́м свої́м показу́я на себі́ в сі́ї последніє времена́ живо́й о́браз і́стиннаго христия́нства і подви́жничества, поуча́ющий і зову́щий нас, грі́шних, оплетшихся земни́ми пристрастіями і жите́йськими попече́ніями, взиска́ти спасе́нія путі́, ведущего в Ца́рство Бо́жиє, іді́же а́нгели і всі Святі́ї немо́лчно пою́ть Бо́гу: Аллилу́я."]},{"h":"Ікос 6","ps":["Возсія́ світ Бо́жієй і спаси́тельной благода́ті в душе́ ю́наго купця́, і благослове́нієм ста́риці Євфроси́нії, оста́вил все в ми́рі сем, вступил в по́двиг юро́дства Христа́ ра́ди і подви́жник ізря́ден яви́лся єси́, блаже́нний Іоа́нн Тульський. Іни́я же єя́ наставле́нієм постригались в монашество і вселялись в святи́я оби́телі, до́брой наста́внице же своє́й благода́рно взивали:","Ра́дуйся, наста́внице спасе́нія;","ра́дуйся, пода́тельнице свята́го благослове́нія.","Ра́дуйся, пред Бо́гом о нас те́плая моли́твеннице;","ра́дуйся, благоче́стія учи́тельнице.","Ра́дуйся, от ко́зней вра́жиїх душі́ на́ші моли́твою своє́ю огражда́ющая;","ра́дуйся, в доброді́теліх христия́нських преуспіва́ти нам помога́ющая.","Ра́дуйся, нечести́вих вразумительнице;","ра́дуйся, благочести́вих покрови́тельнице.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Тулськия пресла́вноє украше́ніє."]},{"h":"Кондак 7","ps":["Хотя́ скри́ти своє́ духо́вноє ді́ланіє от челові́чеських взоров, юродствовала єси́, блаже́нная. І ча́сто ви́дя єя́ юро́дство і сли́ша непонятниє сло́ва, глумились лю́діє над не́ю. Она́ же, терп'я́ще все Бо́га ра́ди, благословляла і́м'я Госпо́днє, воспіва́я: Аллилу́я."]},{"h":"Ікос 7","ps":["Но́вую благода́ть дарова́ тебі́, ма́ти, Госпо́дь: безвре́дно бо в зи́мній мраз і сту́день босая і во ветхої оде́жді ходи́ла єси́, пра́веднице свята́я, подвиза́я нас возглаша́ти тебі́ со умиле́нієм:","Ра́дуйся, я́ко єстества́ уста́ви си́лою Бо́жиєю побіди́ла єси́;","ра́дуйся, я́ко зи́мній мраз і лі́тній вар терпі́ла єси́.","Ра́дуйся, я́ко ті́ло своє́ си́ми по́двигами ду́ху покори́ла єси́;","ра́дуйся, теплото́ю Ду́ха Свята́го согретая.","Ра́дуйся, пла́менем любве́ боже́ственния воспламененная;","ра́дуйся, я́ко многострада́льним житіє́м свої́м му́чеником уподо́билася єси́.","Ра́дуйся, я́ко смире́нієм свої́м главу́ змі́єву попра́ла єси́;","ра́дуйся, я́ко бісо́в прогони́тельнице яви́лася єси́.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 8","ps":["Стра́нно бисть лю́дем мирськи́м ви́діти старицю, главу́ іму́щу острижену, тряпицею пов'язану, босую, в єди́ном капоте, ве́рвієм подпоясанну, с медним кресто́м на гру́ди, с па́лицею в рука́х. І єя́ же не бі досто́їн весь мир, бесчестієм і поруганієм оскорбля́ти, не ві́дуще єя́ духо́внаго соверше́нства, ні є́же Бо́гу пі́ти благоразу́мно: Аллилу́я."]},{"h":"Ікос 8","ps":["Вся єси́ і всім ди́вна і сла́вна яви́лася єси́, блаже́нная, подо́бно дре́внім святи́м в послі́дняя лі́та сія́ просія́ла єси́ богоуго́дним житіє́м і благода́тію, да́нною от Бо́га: неду́ги ісціля́ти, бу́дущеє я́ко настоя́щеє прозира́ти. За вся сія́ воспіва́єм ті сицева́я:","Ра́дуйся, я́ко науче́нієм псалмопевця Дави́да сна очесе́м свої́м і ві́ждома дрема́нія не давала єси́;","ра́дуйся, я́ко бо́дренно в полу́нощі Жениха́ Небе́снаго ожидала єси́.","Ра́дуйся, я́ко терпі́нієм свої́м І́ову пра́ведному соравнялася єси́;","ра́дуйся, я́ко в болі́зні подо́бно Ілії́ проро́ку вра́ном пита́єма била́ єси́.","Ра́дуйся, я́ко преподо́бний Алексі́й, челові́к Бо́жий, дом і роди́телей Бо́га ра́ди оста́вила єси́;","ра́дуйся, я́ко блаже́нной Іси́доре подража́ла єси́.","Ра́дуйся, на гно́їще і сметище я́ко блаже́нний Христа́ ра́ди юро́дивий Андре́й возлегала єси́;","ра́дуйся, я́ко подо́бно Васи́лію Блаже́нному, зимой і лі́том босая ходи́ла єси́.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 9","ps":["Вся́кия болі́зні ісціля́єть святи́й кла́дезь, єго́же свої́ми рука́ми свята́я іскопала єси́ близ ріки́ Оки, говоря́ всім: беріте во́ду із моєго́ кладезя і здра́ві бу́дете. І́же і дони́ні ізлива́єть свої́ студениє води́ на врачева́ніє неду́г челові́чеських, во сла́ву Бо́жию і на ра́дость правосла́вним лю́дем, пою́щим о сем благода́рно Бо́гу: Аллилу́я."]},{"h":"Ікос 9","ps":["Вити́йство челові́чеськоє не мо́жеть ізрещи́ тісноти́ і вели́чія по́двига твоєго́, свята́я, так непостижи́маго для на́шего фарисе́йськаго ра́зума, к землі́ приверженнаго. Єди́н то́кмо Госпо́дь вість прославля́ти святи́я своя́: посему́ і а́нгели своя́ в белоснежних одеяніях посла́ пред сме́ртію зва́ти тя в Небе́сная селе́нія. І ни́ні, сли́ша їх ра́йськоє пі́ніє, преклони́ся ми́лостиво і к на́шим хваленіям убо́гим, і́ми же недоуміва́юще по достоя́нію восхваля́ти тя, зове́м ті:","Ра́дуйся, гра́да на́шего Але́ксина похвало́ і огражде́ніє;","ра́дуйся, прибі́жище на́ше в ско́рбіх і в болі́зніх утіше́ніє.","Ра́дуйся, я́ко нам, грі́шним, водо́ю істо́чника своєго́ ісціле́нія подава́ющая;","ра́дуйся, я́ко чту́щим па́м'ять твою́ святу́ю во всем помога́ющая.","Ра́дуйся, я́ко юро́дством свої́м мудрецо́во ві́ка сего́ посрами́ла єси́;","ра́дуйся, я́ко ідеяли християнського благоче́стія в себі́ воплоти́ла єси́.","Ра́дуйся, я́ко і́м'я твоє́ между́ пра́ведними і святи́ми почита́ється на землі́;","ра́дуйся, я́ко с ни́ми ни́ні лику́єши на небесі́.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 10","ps":["Спасти́ хотя́ ду́шу свою́, тру́дним путе́м подви́жничества і юро́дства всю свою́ до́лгую, вековую жизнь ше́ствовала єси́, ма́ти Євфроси́ніє, до́ндеже дости́гла єси́ ві́чнаго Небе́снаго блаже́нства, ра́достно зову́ще Спаси́телю Бо́гу: Аллилу́я."]},{"h":"Ікос 10","ps":["Стіна́,огражда́ющая от напа́стей, бід і болі́зней, всім к по́мощі і заступле́нію твоєму́ прибегающим яви́лася єси́, блаже́нная, при жи́зні і по сме́рті. Тім же і нас, насельников гра́да Але́ксина, огради́ предста́тельством свої́м от враг ви́димих і неви́димих, от скорбе́й і болі́зней, зову́щих ті:","Ра́дуйся, сліпи́м прозрі́ніє подава́ющая;","ра́дуйся, хроми́м хожде́ніє ісправля́ющая.","Ра́дуйся, вода́ми істо́чника, кладезя своєго́, немощни́х врачу́ющая;","ра́дуйся, от одра́ болі́зні мно́гих возставля́ющая.","Ра́дуйся, в ско́рбіх і обстояніях бедствующим помога́ющая;","ра́дуйся, на спасе́нія стезі́ нас наставля́ющая.","Ра́дуйся, я́ко і о нас, недосто́йних, к Бо́гу моля́щаяся;","ра́дуйся, я́ко і нас от іскуше́ній бісо́вських хода́тайством свої́м покрива́єши.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 11","ps":["Пі́ніє благода́рственноє прино́сим Христу́ Бо́гу на́шему, дарова́вшему нам правосла́вную уго́дницю свою́, ско́рую во всіх ско́рбіх помо́щницю і чудотво́рицю, пою́ще Єму́: Аллилу́я."]},{"h":"Ікос 11","ps":["Світоза́рний світи́льник душі́ своєя́ імі́я ви́ну горя́щим, ми́рно і ти́хо причастившись Пречи́стих Тайн Христо́вих, блаже́нная, отошла́ ко Го́споду. Небе́сним блаже́нством сія́л по сме́рті святолі́пний лик ста́риці, і несказа́нноє благоуха́ніє ісходило от многострада́льнаго ті́ла єя́. Мно́жество наро́да с любо́вію і слеза́ми провожало в послі́дній путь праведницю Бо́жию, вопію́ще:","Ра́дуйся, самопроізвольная му́ченице;","ра́дуйся, свята́я пра́веднице.","Ра́дуйся, я́ко вся до́брая діла́ своя́ в та́йні совершала єси́;","ра́дуйся, расп'я́тієм пло́ті, уничиже́нієм і смире́нієм стра́ждущему на Кресті́ Христу́ подража́ла єси́.","Ра́дуйся, я́ко в хра́мі Цари́ці Небе́сній ті́лом опочила єси́;","ра́дуйся, я́ко ду́хом предста́ти Престо́лу Всеви́шняго сподо́билася єси́.","Ра́дуйся, я́ко ни́ні вінце́м ра́йським от Го́спода уві́нчана єси́;","ра́дуйся, і нас, почита́ющих тя, пред Бо́гом пом'яну́ти не забивающая.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 12","ps":["Благода́ть, да́нную тебі́ от Бо́га, блаже́нная, сві́дуще, тебе́ про́сим і мо́лим: не оста́ви нас хода́тайством свої́м, іспроси́ нам гріхо́в проще́ніє, болі́зней ісціле́ніє, наві́тов вра́жиїх прогна́ніє, да спа́сшеся, просла́вим вели́коє милосе́рдіє Бо́жиє, восклиця́я: Аллилу́я."]},{"h":"Ікос 12","ps":["Пою́ще ди́внаго во святи́х свої́х Бо́га, ублажа́єм і свя́то чтим в безчисленном со́нме святи́х Єго́ блаже́нную старицю Євфроси́нію, прося́ єя́ моли́тв, по́мощі і благослове́нія на вся труди́ і діла́ на́ша. Ти же усли́ши нас, ма́ти, велича́ющих тя си́це:","Ра́дуйся, ді́во свята́я прему́драя;","ра́дуйся, неві́сто Христо́ва пречу́дная.","Ра́дуйся, Бо́жия ізбраннице;","ра́дуйся, на́ша пред Бо́гом предста́тельнице.","Ра́дуйся, му́жественно крест свой поне́сшая на землі́;","ра́дуйся, ни́ні ві́чно с Господом ра́дуєшися на Небесі́.","Ра́дуйся, блаже́нная старице, всі́ми люби́мая;","ра́дуйся, на небесі́ і на землі́ сла́вимая і блажи́мая.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 13","ps":["О блаже́нная старице Євфроси́ніє, не возгнуша́йся похвала́ми недосто́йними на́шими, но прийми́ ма́лоє моле́ніє сіє́ на́ше і іспроси́ у Го́спода вся блага́я на по́льзу душ і тіле́с на́ших, да сподо́бимся і ми ку́пно с тобо́ю во ві́чной жи́зні воспіва́ти Бо́гу: Аллилу́я.","§Цей кондак промовляй тричі, потім 1-й ікос і 1-й кондак."]},{"h":"Ікос 1","ps":["А́нгелом храни́телем ко спасе́нію наставля́єма, ю́ная княжна́ В'яземськая, презрі́в ро́скош і бога́тство, сла́ву і знатность і вся пре́лести су́єтнаго ми́ра сего́, оста́вила єси́ ца́рський дворець, вступив на у́зький і терни́стий путь, веду́щий в Ца́рство Небе́сноє. За сіє́ прийми́ от нас, блаже́нная, похвали́ сія́:","Ра́дуйся, я́ко Бо́га ра́ди із палать ца́рських ісшла єси́;","ра́дуйся, я́ко ра́ди спасе́нія душі́ своєя́ вся земна́я презрі́ла єси́.","Ра́дуйся, я́ко самопроізво́льную нищету́ ра́ди Христа́ ізбра́ла єси́;","ра́дуйся, я́ко бога́тство нетлі́нноє і ві́чноє обріла́ єси́.","Ра́дуйся, я́ко Небе́сному Жениху́ Христу́ уневісти́лася єси́;","ра́дуйся, я́ко с му́дрими ді́вами в Черто́г Єго́ Небе́сний вошла́ єси́.","Ра́дуйся, чи́стая голуби́це Христо́ва;","ра́дуйся, непоро́чная А́гнице Бо́жия.","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Кондак 1","ps":["Ізбра́нной Бо́гом от палать ца́рських в Небе́сний Черто́г Ра́йський; блаже́нній старице Євфроси́нії, Христа́ ра́ди юродивей, я́ко покрови́тельнице на́шей і моли́твеннице похва́льноє принесе́м пі́ніє. Ти же, блаже́нная ма́ти, я́ко імі́я дерзнове́ніє ко Го́споду, от вся́ких нас бід і болі́зней свободи́, с любо́вію зову́щих ті:","Ра́дуйся, блаже́нная старице Євфроси́ніє, Колюпановськая похвало́ і всея́ землі́ Ту́льськия пресла́вноє украше́ніє."]},{"h":"Молитва","ps":["О ма́ти блаже́нная Євфроси́ніє! На землі́ юро́дивая, на небесі́ прему́драя! Проше́дши до́блественно свой столетній путь земно́й, ни́ні с висоти́ небе́с при́зри на нас грі́шних в мо́ре жите́йськом обурева́ємих: от пло́ті — страстьми́ і болі́знями, от ми́ра — досажденіями і соблазнами, от дия́вола — многочи́сленними кознями, і уже́ близ потопле́нія єсть кораблики душ на́ших, не іму́ще крі́пкаго якоря ві́ри, наде́жду полага́юще на свої́ си́ли і челові́чеськую по́мощ, с угасшим світи́льником любві́ і благоче́стія. Не закосни́, матушка Євфроси́нія, по́мощи нам, не по досто́їнству на́шему, но по милосе́рдію, подоб'ясь всемилостивому́ Спа́су на́шему Ісу́су Христу́. Укріпи́ нас с ві́рі, наде́жде і любві́, хла́дних і черствих се́рдцем согрі́й свої́м участієм, болі́зні на́ші уврачу́й, ско́рби і печа́лі отими́ от нас, на скользком путі́ сем земно́м пода́ждь нам ру́ку по́мощі, да укрепившись ті́лом і душе́ю, с терпі́нієм крест свой понесе́м, с упова́нієм на Бо́га і твоє́ ско́роє предста́тельство, і да сподо́бимся по сме́рті ві́чния, блаже́нния жи́зні, сла́в'яще Отця́ і Си́на і Свята́го Ду́ха во ві́ки віко́в. Амі́нь."]},{"h":"Тропар, глас 4","ps":["Вся кра́сная ми́ра сего́ презрі́ла єси́, / дворе́ць ца́рський оста́вив, юро́дство Христа́ ра́ди на ся восприя́ла єси́, / блаже́нная ста́рице Євфроси́ніє, / сего́ ра́ди с му́дрими ді́вами в небе́сний черто́г Жениха́ Христа́ вошла́ єси́, // моля́ся о всіх нас."]},{"h":"Кондак, глас 2","ps":["Прему́дростію Бо́жиєю наставля́єма, / юро́дивою на землі́ пожила́ єси́, / му́дрость ві́ка сего́ в бу́йство вміни́в, / вінце́м нетлі́нним от Христа́ Бо́га за сіє́ увінча́лася єси́ / в ли́кі святи́х на небесі́ водворя́яся, // блаже́нная ма́ти Євфроси́ніє."]},{"h":"Величання","ps":["Ублажа́єм тя, свята́я блаже́нная ма́ти Євфроси́ніє, і чтим святу́ю па́м'ять твою́, наста́внице мона́хов і собесі́днице А́нгелов."]}],"notes":[]}];
export default D;
